# Backend de base de données.
# CORRECTIF CLOUD/NEON :
# dès qu'une configuration PostgreSQL/Neon est présente, PostgreSQL est prioritaire,
# même si une ancienne variable EDUSILLAB_DB_BACKEND=sqlite est restée configurée.
backend_env <- tolower(trimws(Sys.getenv("EDUSILLAB_DB_BACKEND", unset = "")))

pg_host_env <- trimws(Sys.getenv("EDUSILLAB_PG_HOST", unset = ""))
pg_db_env   <- trimws(Sys.getenv("EDUSILLAB_PG_DATABASE", unset = ""))
pg_user_env <- trimws(Sys.getenv("EDUSILLAB_PG_USER", unset = ""))
pg_pwd_env  <- Sys.getenv("EDUSILLAB_PG_PASSWORD", unset = "")

pg_config_detectee <- any(nzchar(c(pg_host_env, pg_db_env, pg_user_env, pg_pwd_env)))
pg_config_complete <- all(nzchar(c(pg_host_env, pg_db_env, pg_user_env, pg_pwd_env)))

if (pg_config_detectee) {
  if (!pg_config_complete) {
    manquantes_pg <- c(
      EDUSILLAB_PG_HOST = !nzchar(pg_host_env),
      EDUSILLAB_PG_DATABASE = !nzchar(pg_db_env),
      EDUSILLAB_PG_USER = !nzchar(pg_user_env),
      EDUSILLAB_PG_PASSWORD = !nzchar(pg_pwd_env)
    )
    stop(
      "Configuration PostgreSQL/Neon détectée mais incomplète. Variable(s) manquante(s) : ",
      paste(names(manquantes_pg)[manquantes_pg], collapse = ", "),
      ". EDUSILLAB refuse de basculer vers une base SQLite vide."
    )
  }
  edusillab_db_backend <- "postgres"
} else if (identical(backend_env, "postgres")) {
  stop(
    "EDUSILLAB_DB_BACKEND=postgres mais les variables EDUSILLAB_PG_HOST, ",
    "EDUSILLAB_PG_DATABASE, EDUSILLAB_PG_USER et EDUSILLAB_PG_PASSWORD ",
    "ne sont pas toutes configurées."
  )
} else {
  edusillab_db_backend <- "sqlite"
}

message("Backend DB réellement utilisé : ", edusillab_db_backend)
if (identical(edusillab_db_backend, "postgres")) {
  message("PostgreSQL/Neon prioritaire : OUI")
} else {
  message("PostgreSQL/Neon non configuré; SQLite utilisé.")
}

# Connexion renforcée. En mode SQLite, on conserve exactement les réglages
# multi-utilisateurs déjà validés. Le mode PostgreSQL utilise uniquement les
# variables secrètes de Connect Cloud / Neon et n'inscrit aucun secret dans app.R.
ouvrir_db <- function() {
  if (identical(edusillab_db_backend, "postgres")) {
    if (!requireNamespace("RPostgres", quietly = TRUE)) {
      stop("Le package RPostgres est requis pour EDUSILLAB_DB_BACKEND=postgres.")
    }

    pg_host <- trimws(Sys.getenv("EDUSILLAB_PG_HOST", unset = ""))
    pg_port <- suppressWarnings(as.integer(Sys.getenv("EDUSILLAB_PG_PORT", unset = "5432")))
    pg_db   <- trimws(Sys.getenv("EDUSILLAB_PG_DATABASE", unset = ""))
    pg_user <- trimws(Sys.getenv("EDUSILLAB_PG_USER", unset = ""))
    pg_pwd  <- Sys.getenv("EDUSILLAB_PG_PASSWORD", unset = "")
    pg_ssl  <- trimws(Sys.getenv("EDUSILLAB_PG_SSLMODE", unset = "require"))

    manquantes <- c(
      HOST = !nzchar(pg_host), DATABASE = !nzchar(pg_db),
      USER = !nzchar(pg_user), PASSWORD = !nzchar(pg_pwd)
    )
    if (any(manquantes)) {
      stop("Variables PostgreSQL manquantes : ",
           paste(names(manquantes)[manquantes], collapse = ", "))
    }
    if (is.na(pg_port)) pg_port <- 5432L

    con <- DBI::dbConnect(
      RPostgres::Postgres(),
      host = pg_host,
      port = pg_port,
      dbname = pg_db,
      user = pg_user,
      password = pg_pwd,
      sslmode = pg_ssl
    )
    DBI::dbExecute(con, "SET TIME ZONE 'America/Moncton'")
    return(con)
  }

  con <- NULL
  for (tentative in seq_len(5L)) {
    con <- tryCatch(
      DBI::dbConnect(RSQLite::SQLite(), db_path),
      error=function(e) NULL
    )
    if (!is.null(con) && DBI::dbIsValid(con)) break
    Sys.sleep(0.15 * tentative)
  }

  if (is.null(con) || !DBI::dbIsValid(con))
    stop("Connexion temporairement indisponible. Veuillez réessayer.")

  DBI::dbExecute(con, "PRAGMA foreign_keys = ON")
  DBI::dbExecute(con, "PRAGMA busy_timeout = 60000")
  DBI::dbExecute(con, "PRAGMA synchronous = NORMAL")

  mode_journal <- tryCatch(
    DBI::dbGetQuery(con, "PRAGMA journal_mode")[[1]][1],
    error=function(e) ""
  )
  if (!identical(toupper(as.character(mode_journal)), "WAL")) {
    try(DBI::dbExecute(con, "PRAGMA journal_mode = WAL"), silent=TRUE)
  }
  try(DBI::dbExecute(con, "PRAGMA wal_autocheckpoint = 1000"), silent=TRUE)
  con
}


# ============================================================
# COUCHE SQL PORTABLE SQLITE / POSTGRESQL
# ============================================================
est_postgres <- function(con = NULL) {
  if (!is.null(con)) return(inherits(con, "PqConnection"))
  identical(edusillab_db_backend, "postgres")
}

pg_placeholders <- function(sql) {
  if (!est_postgres()) return(sql)
  ch <- strsplit(sql, "", fixed = TRUE)[[1]]
  if (!length(ch)) return(sql)
  out <- character()
  in_single <- FALSE
  in_double <- FALSE
  n <- 0L
  i <- 1L
  while (i <= length(ch)) {
    z <- ch[i]
    if (z == "'" && !in_double) {
      if (in_single && i < length(ch) && ch[i + 1L] == "'") {
        out <- c(out, "''"); i <- i + 2L; next
      }
      in_single <- !in_single
      out <- c(out, z); i <- i + 1L; next
    }
    if (z == '"' && !in_single) {
      in_double <- !in_double
      out <- c(out, z); i <- i + 1L; next
    }
    if (z == "?" && !in_single && !in_double) {
      n <- n + 1L
      out <- c(out, paste0("$", n))
    } else {
      out <- c(out, z)
    }
    i <- i + 1L
  }
  paste0(out, collapse = "")
}

sql_adapter <- function(con, statement) {
  sql <- as.character(statement)
  if (!est_postgres(con)) return(sql)

  # SQLite accepte les backticks pour les identifiants; PostgreSQL utilise ".
  sql <- gsub("`([^`]*)`", '"\\1"', sql, perl = TRUE)

  sql <- gsub(
    "INTEGER\\s+PRIMARY\\s+KEY\\s+AUTOINCREMENT",
    "BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY",
    sql, ignore.case = TRUE, perl = TRUE
  )

  if (grepl("\\bINSERT\\s+OR\\s+IGNORE\\s+INTO\\b", sql, ignore.case = TRUE, perl = TRUE)) {
    sql <- gsub(
      "\\bINSERT\\s+OR\\s+IGNORE\\s+INTO\\b",
      "INSERT INTO", sql, ignore.case = TRUE, perl = TRUE
    )
    sql <- sub(";\\s*$", "", sql, perl = TRUE)
    sql <- paste0(sql, " ON CONFLICT DO NOTHING")
  }

  if (grepl("\\bINSERT\\s+OR\\s+REPLACE\\s+INTO\\s+hemato_frottis_parasites\\b",
            sql, ignore.case = TRUE, perl = TRUE)) {
    sql <- gsub(
      "\\bINSERT\\s+OR\\s+REPLACE\\s+INTO\\b",
      "INSERT INTO", sql, ignore.case = TRUE, perl = TRUE
    )
    sql <- sub(";\\s*$", "", sql, perl = TRUE)
    sql <- paste0(
      sql,
      " ON CONFLICT (frottis_id, parasite) DO UPDATE SET ",
      "present = EXCLUDED.present, commentaire = EXCLUDED.commentaire"
    )
  }

  sql <- gsub(
    "SELECT\\s+last_insert_rowid\\(\\)\\s+AS\\s+id",
    "SELECT LASTVAL() AS id",
    sql, ignore.case = TRUE, perl = TRUE
  )

  pg_placeholders(sql)
}

db_execute <- function(con, statement, params = NULL, ...) {
  if (est_postgres(con) &&
      grepl("CREATE\\s+TRIGGER\\s+IF\\s+NOT\\s+EXISTS\\s+trg_analyses_date_creation",
            statement, ignore.case = TRUE, perl = TRUE)) {
    return(DBI::dbExecute(
      con,
      "ALTER TABLE analyses ALTER COLUMN date_creation SET DEFAULT CURRENT_TIMESTAMP"
    ))
  }
  sql <- sql_adapter(con, statement)
  if (is.null(params)) DBI::dbExecute(con, sql, ...)
  else DBI::dbExecute(con, sql, params = params, ...)
}

db_query <- function(con, statement, params = NULL, ...) {
  sql <- sql_adapter(con, statement)
  if (is.null(params)) DBI::dbGetQuery(con, sql, ...)
  else DBI::dbGetQuery(con, sql, params = params, ...)
}

# Détecte uniquement les erreurs SQLite temporaires qui méritent une nouvelle tentative.
erreur_sqlite_temporaire <- function(e) {
  msg <- tolower(conditionMessage(e))
  grepl("database is locked|database is busy|locked|busy", msg)
}

db_begin_retry <- function(con, essais=10L) {
  derniere <- NULL
  for (i in seq_len(essais)) {
    ok <- tryCatch({
      DBI::dbBegin(con)
      TRUE
    }, error=function(e) {
      derniere <<- e
      FALSE
    })
    if (ok) return(invisible(TRUE))
    if (!erreur_sqlite_temporaire(derniere) || i == essais) stop(derniere)
    Sys.sleep(min(1.5, 0.12 * (2^(i-1L))))
  }
  invisible(FALSE)
}

db_commit_retry <- function(con, essais=10L) {
  derniere <- NULL
  for (i in seq_len(essais)) {
    ok <- tryCatch({
      DBI::dbCommit(con)
      TRUE
    }, error=function(e) {
      derniere <<- e
      FALSE
    })
    if (ok) return(invisible(TRUE))
    if (!erreur_sqlite_temporaire(derniere) || i == essais) stop(derniere)
    Sys.sleep(min(1.5, 0.12 * (2^(i-1L))))
  }
  invisible(FALSE)
}

# Pour les petites écritures hors transaction explicite.
# Suppression contrôlée d'un enregistrement avec ses descendants définis par
# les clés étrangères. Utilisé uniquement après confirmation explicite d'un administrateur.
edusillab_tables <- function(con) {
  if (est_postgres(con)) {
    return(db_query(con,
      "SELECT table_name FROM information_schema.tables WHERE table_schema=current_schema() AND table_type='BASE TABLE'")$table_name)
  }
  db_query(con,"SELECT name FROM sqlite_master WHERE type='table' AND name NOT LIKE 'sqlite_%'")$name
}

edusillab_fk_vers <- function(con, table_parent, colonne_parent="id") {
  if (est_postgres(con)) {
    return(db_query(con,"
      SELECT tc.table_name AS table_enfant,
             kcu.column_name AS colonne_enfant,
             ccu.column_name AS colonne_parent
      FROM information_schema.table_constraints tc
      JOIN information_schema.key_column_usage kcu
        ON tc.constraint_name=kcu.constraint_name AND tc.table_schema=kcu.table_schema
      JOIN information_schema.constraint_column_usage ccu
        ON ccu.constraint_name=tc.constraint_name AND ccu.table_schema=tc.table_schema
      WHERE tc.constraint_type='FOREIGN KEY'
        AND tc.table_schema=current_schema()
        AND ccu.table_name=?
        AND ccu.column_name=?",
      params=list(table_parent,colonne_parent)))
  }
  res <- list()
  for (tt in edusillab_tables(con)) {
    ident <- as.character(DBI::dbQuoteIdentifier(con,tt))
    fk <- tryCatch(DBI::dbGetQuery(con,paste0("PRAGMA foreign_key_list(",ident,")")),
                   error=function(e) data.frame())
    if(nrow(fk)>0) {
      ok <- fk$table==table_parent & fk$to==colonne_parent
      if(any(ok)) {
        res[[length(res)+1L]] <- data.frame(
          table_enfant=rep(tt,sum(ok)),
          colonne_enfant=fk$from[ok],
          colonne_parent=fk$to[ok],
          stringsAsFactors=FALSE)
      }
    }
  }
  if(length(res)==0) return(data.frame(table_enfant=character(),colonne_enfant=character(),colonne_parent=character()))
  do.call(rbind,res)
}

edusillab_supprimer_cascade <- function(con, table, id_value, visites=NULL) {
  cle <- paste(table,as.character(id_value),sep=":")
  if(!is.null(visites) && exists(cle,envir=visites,inherits=FALSE)) return(invisible(TRUE))
  if(is.null(visites)) visites <- new.env(parent=emptyenv())
  assign(cle,TRUE,envir=visites)

  refs <- edusillab_fk_vers(con,table,"id")
  if(nrow(refs)>0) {
    for(i in seq_len(nrow(refs))) {
      te <- refs$table_enfant[i]
      ce <- refs$colonne_enfant[i]
      cols <- sql_colonnes(con,te)
      qt <- as.character(DBI::dbQuoteIdentifier(con,te))
      qc <- as.character(DBI::dbQuoteIdentifier(con,ce))
      if("id" %in% cols) {
        enfants <- db_query(con,paste0("SELECT id FROM ",qt," WHERE ",qc,"=?"),params=list(id_value))
        if(nrow(enfants)>0) for(cid in enfants$id) edusillab_supprimer_cascade(con,te,cid,visites)
      }
      db_execute(con,paste0("DELETE FROM ",qt," WHERE ",qc,"=?"),params=list(id_value))
    }
  }
  qt <- as.character(DBI::dbQuoteIdentifier(con,table))
  db_execute(con,paste0("DELETE FROM ",qt," WHERE id=?"),params=list(id_value))
  invisible(TRUE)
}

db_execute_retry <- function(con, statement, params=NULL, essais=10L) {
  derniere <- NULL
  for (i in seq_len(essais)) {
    resultat <- tryCatch({
      if (is.null(params)) db_execute(con, statement)
      else db_execute(con, statement, params=params)
    }, error=function(e) {
      derniere <<- e
      NULL
    })
    if (!is.null(resultat)) return(resultat)
    if (!erreur_sqlite_temporaire(derniere) || i == essais) stop(derniere)
    Sys.sleep(min(1.5, 0.12 * (2^(i-1L))))
  }
  stop("Écriture SQLite impossible après plusieurs tentatives.")
}

norm_txt <- function(x) {
  x <- as.character(x)
  x[is.na(x)] <- ""
  trimws(x)
}

norm_upper <- function(x) toupper(norm_txt(x))

identifiant_patient_inconnu <- function(x) {
  toupper(trimws(as.character(x %||% ""))) %in% c("UNK","UNKNOWN","INCONNU")
}

identifiant_patient_db <- function(x) {
  x <- norm_txt(x)
  if (!nzchar(x) || identifiant_patient_inconnu(x)) NA_character_ else x
}

identifiant_patient_affichage <- function(x) {
  x <- norm_txt(x)
  if (!nzchar(x) || identifiant_patient_inconnu(x)) "UNK" else x
}

date_locale_edusillab <- function() {
  as.Date(format(Sys.time(), tz = edusillab_timezone, format = "%Y-%m-%d"))
}

sql_colonnes <- function(con, table) {
  if (inherits(con, "PqConnection")) {
    return(db_query(
      con,
      "SELECT column_name FROM information_schema.columns WHERE table_schema = current_schema() AND table_name = ? ORDER BY ordinal_position",
      params = list(table)
    )$column_name)
  }
  db_query(con, paste0("PRAGMA table_info(", table, ")"))$name
}

ajouter_colonne_si_absente <- function(con, table, colonne, definition) {
  if (!colonne %in% sql_colonnes(con, table)) {
    db_execute(con, paste(
      "ALTER TABLE", table,
      "ADD COLUMN", colonne, definition
    ))
  }
}

email_valide <- function(x) {
  x <- norm_txt(x)
  nzchar(x) &&
    grepl("^[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\\.[A-Za-z]{2,}$", x)
}

generer_numero_requisition <- function(con) {
  repeat {
    numero <- paste0(sample(0:9, 10, replace = TRUE), collapse = "")
    if (substr(numero, 1, 1) == "0") {
      substr(numero, 1, 1) <- as.character(sample(1:9, 1))
    }

    existe <- db_query(
      con,
      "SELECT id FROM requisitions WHERE numero_requisition = ? LIMIT 1",
      params = list(numero)
    )

    if (nrow(existe) == 0) return(numero)
  }
}

generer_code_barre <- function(con) {
  repeat {
    code <- paste0(sample(0:9, 6, replace = TRUE), collapse = "")
    if (substr(code, 1, 1) == "0") substr(code, 1, 1) <- as.character(sample(1:9, 1))
    existe <- db_query(con, "SELECT id FROM specimens WHERE code_barre = ? LIMIT 1", params = list(code))
    if (nrow(existe) == 0) return(code)
  }
}

code_priorite <- function(x) {
  x <- toupper(norm_txt(x))
  if (x == "STAT") return("S")
  if (x == "URGENCE") return("U")
  "R"
}


formater_nombre_tubes <- function(x) {
  x <- suppressWarnings(as.numeric(x))
  x <- x[!is.na(x)]

  if (length(x) == 0) return("N/P")

  total <- sum(x)

  if (abs(total - round(total)) < 0.000001) {
    return(as.character(as.integer(round(total))))
  }

  format(total, trim = TRUE, scientific = FALSE)
}

generer_numero_specimen <- function(con, date_specimen, px, priorite) {
  d <- as.Date(date_specimen)
  if (is.na(d)) d <- Sys.Date()
  prefixe_date <- format(d, "%d%m")
  px <- toupper(gsub("[^A-Z0-9]", "", norm_txt(px)))
  if (!nzchar(px)) px <- "X"
  n <- db_query(
    con,
    "SELECT COUNT(*) AS n FROM specimens WHERE date_specimen = ? AND UPPER(COALESCE(px,'')) = UPPER(?)",
    params = list(as.character(d), px)
  )$n[1] + 1L
  paste0(prefixe_date, ":", px, formatC(as.numeric(n), format="f", digits=0, width=5, flag="0"), code_priorite(priorite))
}

code39_patterns <- c(
  "0"="nnnwwnwnn","1"="wnnwnnnnw","2"="nnwwnnnnw","3"="wnwwnnnnn",
  "4"="nnnwwnnnw","5"="wnnwwnnnn","6"="nnwwwnnnn","7"="nnnwnnwnw",
  "8"="wnnwnnwnn","9"="nnwwnnwnn","*"="nwnnwnwnn"
)

dessiner_code39 <- function(code, x, y, largeur, hauteur) {
  chars <- strsplit(paste0("*", code, "*"), "")[[1]]
  poids_total <- 0
  for (ch in chars) {
    pat <- strsplit(code39_patterns[[ch]], "")[[1]]
    poids_total <- poids_total + sum(ifelse(pat == "w", 3, 1)) + 1
  }
  pos <- x
  for (ch in chars) {
    pat <- strsplit(code39_patterns[[ch]], "")[[1]]
    for (i in seq_along(pat)) {
      w <- largeur * (ifelse(pat[i] == "w", 3, 1) / poids_total)
      if (i %% 2 == 1) rect(pos, y, pos + w, y + hauteur, col = "black", border = NA)
      pos <- pos + w
    }
    pos <- pos + largeur * (1 / poids_total)
  }
}

preview_dir <- file.path(tempdir(), "edulab_label_previews")
dir.create(preview_dir, showWarnings = FALSE, recursive = TRUE)
addResourcePath("edulab_labels", preview_dir)

creer_pdf_etiquettes <- function(
  labels, fichier, largeur_mm = 100, hauteur_mm = 50,
  offset_x_mm = 0, offset_y_mm = 0, echelle_pct = 100
) {
  if (is.null(labels) || nrow(labels) == 0) stop("Aucune étiquette à générer.")

  # La taille physique du PDF est directement celle configurée pour
  # l'imprimante. La mise en page reste proportionnelle et la taille
  # du texte est ajustée légèrement selon le format de l'étiquette.
  facteur <- min(
    1.35,
    max(
      0.72,
      min(largeur_mm / 100, hauteur_mm / 50)
    )
  )

  grDevices::pdf(
    fichier,
    width = largeur_mm / 25.4,
    height = hauteur_mm / 25.4,
    paper = "special",
    onefile = TRUE,
    family = "Helvetica"
  )
  on.exit(grDevices::dev.off(), add = TRUE)

  for (i in seq_len(nrow(labels))) {
    par(mar = c(0, 0, 0, 0), xaxs = "i", yaxs = "i")
    plot.new()

    echelle <- suppressWarnings(as.numeric(echelle_pct))
    if (is.na(echelle) || echelle <= 0) echelle <- 100
    echelle <- echelle / 100

    dx <- suppressWarnings(as.numeric(offset_x_mm))
    dy <- suppressWarnings(as.numeric(offset_y_mm))
    if (is.na(dx)) dx <- 0
    if (is.na(dy)) dy <- 0

    dx_logique <- dx / largeur_mm * 100
    dy_logique <- dy / hauteur_mm * 50
    largeur_vue <- 100 / echelle
    hauteur_vue <- 50 / echelle

    plot.window(
      xlim = c(50 - largeur_vue / 2 - dx_logique, 50 + largeur_vue / 2 - dx_logique),
      ylim = c(25 - hauteur_vue / 2 - dy_logique, 25 + hauteur_vue / 2 - dy_logique)
    )

    # GRAND CODE À BARRES
    dessiner_code39(
      labels$code_barre[i],
      x = 3,
      y = 38.5,
      largeur = 94,
      hauteur = 10
    )

    # BC# affiché une seule fois.
    text(
      50, 36.3,
      paste0("BC# ", labels$code_barre[i]),
      adj = 0.5,
      cex = 0.72 * facteur,
      font = 2
    )

    # POINT 2 + POINT 7 : numéro d'échantillon et dossier.
    text(
      4, 32.7,
      labels$numero_specimen[i],
      adj = 0,
      cex = 0.76 * facteur,
      font = 2
    )
    text(
      96, 32.7,
      paste0("DOSSIER ", labels$numero_dossier[i]),
      adj = 1,
      cex = 0.70 * facteur,
      font = 2
    )

    # POINT 3 + POINT 12
    text(
      4, 28.6,
      paste0(labels$nom[i], ", ", labels$prenom[i]),
      adj = 0,
      cex = 0.76 * facteur,
      font = 2
    )
    text(
      96, 28.6,
      paste0("SEXE: ", labels$sexe[i]),
      adj = 1,
      cex = 0.66 * facteur
    )

    # POINT 8 + POINT 5
    text(
      4, 24.5,
      paste0("MED ", labels$medicare[i]),
      adj = 0,
      cex = 0.64 * facteur
    )
    text(
      96, 24.5,
      paste0("LOC ", labels$location[i]),
      adj = 1,
      cex = 0.64 * facteur
    )

    # POINT 9 + POINT 10
    text(
      4, 20.3,
      paste0("# TUBES: ", labels$quantite[i]),
      adj = 0,
      cex = 0.66 * facteur,
      font = 2
    )
    text(
      96, 20.3,
      labels$contenant[i],
      adj = 1,
      cex = 0.62 * facteur,
      font = 2
    )

    # POINT 6 : analyses en ligne, séparées par des virgules.
    analyses_aff <- labels$analyses[i]
    analyses_aff <- gsub(" | ", ", ", analyses_aff, fixed = TRUE)

    cex_tests <- if (nchar(analyses_aff) > 100) {
      0.46
    } else if (nchar(analyses_aff) > 75) {
      0.52
    } else if (nchar(analyses_aff) > 55) {
      0.58
    } else {
      0.64
    }

    text(
      4, 15.7,
      paste0("ANALYSES: ", analyses_aff),
      adj = 0,
      cex = cex_tests * facteur,
      font = 2
    )

    # Le PX et le département ne sont pas imprimés sur l'étiquette.
    # Le numéro de réquisition reste discret en bas.
    text(
      96, 10.8,
      paste0("REQ ", labels$numero_requisition[i]),
      adj = 1,
      cex = 0.52 * facteur
    )

    # TRAÇABILITÉ DE SAISIE : nom complet, date/heure et signature automatique.
    nom_saisie <- if ("saisi_nom_complet" %in% names(labels)) labels$saisi_nom_complet[i] else ""
    date_saisie <- if ("date_saisie" %in% names(labels)) labels$date_saisie[i] else ""
    signature_saisie <- if ("signature_initiales" %in% names(labels)) labels$signature_initiales[i] else ""
    nom_saisie <- ifelse(is.na(nom_saisie), "", as.character(nom_saisie))
    date_saisie <- ifelse(is.na(date_saisie), "", as.character(date_saisie))
    signature_saisie <- ifelse(is.na(signature_saisie), "", as.character(signature_saisie))

    text(4, 10.8, paste0("SAISI PAR: ", nom_saisie), adj=0, cex=0.46*facteur, font=2)
    text(4, 7.4, paste0("DATE/HEURE: ", date_saisie), adj=0, cex=0.43*facteur)
    text(96, 7.4, paste0("SIGNATURE: ", signature_saisie), adj=1, cex=0.46*facteur, font=3)
  }

  invisible(fichier)
}


creer_pdf_etiquettes_selection <- function(
  labels,
  indices,
  fichier,
  largeur_mm = 100,
  hauteur_mm = 50
) {
  if (is.null(labels) || nrow(labels) == 0) {
    stop("Aucune étiquette disponible.")
  }

  indices <- suppressWarnings(as.integer(indices))
  indices <- indices[
    !is.na(indices) &
      indices >= 1 &
      indices <= nrow(labels)
  ]

  indices <- unique(indices)

  if (length(indices) == 0) {
    stop("Sélectionnez au moins une étiquette.")
  }

  creer_pdf_etiquettes(
    labels = labels[indices, , drop = FALSE],
    fichier = fichier,
    largeur_mm = largeur_mm,
    hauteur_mm = hauteur_mm
  )
}

