# Fonctions robustes d'accès aux départements.
# IMPORTANT : px peut contenir plusieurs codes séparés par une virgule (ex. H,HC).
departements_autorises_utilisateur <- function(con, utilisateur_id, role = "") {
  role <- toupper(trimws(ifelse(is.null(role) || is.na(role), "", as.character(role))))
  if (role %in% c("ADMIN", "SUPERUTILISATEUR")) {
    return(db_query(
      con,
      "SELECT id,code,nom,COALESCE(px,'') AS px
       FROM departements_portail
       WHERE actif=1
       ORDER BY nom"
    ))
  }

  uid <- suppressWarnings(as.integer(utilisateur_id))
  if (length(uid) != 1 || is.na(uid)) {
    return(data.frame(id=integer(),code=character(),nom=character(),px=character()))
  }

  tryCatch(
    db_query(
      con,
      "SELECT d.id,d.code,d.nom,COALESCE(d.px,'') AS px
       FROM utilisateur_departements ud
       INNER JOIN departements_portail d ON d.id=ud.departement_id
       WHERE ud.utilisateur_id=? AND d.actif=1
       ORDER BY d.nom",
      params=list(uid)
    ),
    error=function(e) data.frame(id=integer(),code=character(),nom=character(),px=character())
  )
}

utilisateur_a_acces_departement <- function(con, utilisateur_id, role,
                                             departement = "", px = "") {
  role <- toupper(trimws(ifelse(is.null(role) || is.na(role), "", as.character(role))))
  if (role %in% c("ADMIN", "SUPERUTILISATEUR")) return(TRUE)

  autor <- departements_autorises_utilisateur(con, utilisateur_id, role)
  if (nrow(autor) == 0) return(FALSE)

  dep_recherche <- toupper(trimws(as.character(departement)))
  px_recherche <- toupper(trimws(as.character(px)))

  # Correspondance par nom/code.
  if (nzchar(dep_recherche) &&
      any(toupper(trimws(autor$nom)) == dep_recherche |
          toupper(trimws(autor$code)) == dep_recherche)) {
    return(TRUE)
  }

  # Correspondance PX; accepte H,HC dans un même département.
  if (nzchar(px_recherche)) {
    px_ok <- vapply(
      autor$px,
      function(z) {
        codes <- toupper(trimws(unlist(strsplit(ifelse(is.na(z),"",z), ","))))
        px_recherche %in% codes
      },
      logical(1)
    )
    if (any(px_ok)) return(TRUE)
  }

  FALSE
}


