ui <- fluidPage(
  tags$head(
    tags$script(HTML("
/* ==========================================================
   EDUSILLAB - EDITEUR REQUISITION MULTI-PAGES
   Déplacement patient / X / commentaires / textes libres
   ========================================================== */

window.initReqMultiDrag = function() {
  var elements = document.querySelectorAll(
    '.req-pdf-page-wrap .req-live-overlay'
  );

  elements.forEach(function(el) {
    if (el.dataset.multiDragReady === '1') return;
    el.dataset.multiDragReady = '1';

    var active = false;
    var dx = 0;
    var dy = 0;

    el.addEventListener('mousedown', function(ev) {
      ev.preventDefault();
      ev.stopPropagation();

      active = true;

      var er = el.getBoundingClientRect();
      dx = ev.clientX - er.left;
      dy = ev.clientY - er.top;

      el.style.zIndex = '100';
      document.body.style.userSelect = 'none';
    });

    document.addEventListener('mousemove', function(ev) {
      if (!active) return;

      var wrap = el.closest('.req-pdf-page-wrap');
      if (!wrap) return;

      var canvas = wrap.querySelector('.req-pdf-page-canvas, canvas');
      if (!canvas) return;

      var cr = canvas.getBoundingClientRect();

      var x = (ev.clientX - cr.left - dx) / cr.width;
      var y = (ev.clientY - cr.top - dy) / cr.height;

      x = Math.max(0, Math.min(0.98, x));
      y = Math.max(0, Math.min(0.98, y));

      el.style.left = (x * 100) + '%';
      el.style.top  = (y * 100) + '%';
    });

    document.addEventListener('mouseup', function() {
      if (!active) return;
      active = false;
      document.body.style.userSelect = '';

      var wrap = el.closest('.req-pdf-page-wrap');
      if (!wrap) return;

      var canvas = wrap.querySelector('.req-pdf-page-canvas, canvas');
      if (!canvas) return;

      var cr = canvas.getBoundingClientRect();
      var er = el.getBoundingClientRect();

      var x = (er.left - cr.left) / cr.width;
      var y = (er.top  - cr.top)  / cr.height;

      x = Math.max(0, Math.min(1, x));
      y = Math.max(0, Math.min(1, y));

      Shiny.setInputValue(
        'req_overlay_moved',
        {
          kind: el.dataset.kind || '',
          id: el.dataset.id || '',
          key: el.dataset.key || '',
          page: parseInt(wrap.dataset.page || '1'),
          x: x,
          y: y,
          nonce: Date.now()
        },
        {priority: 'event'}
      );

      if (el.dataset.kind === 'test') el.style.zIndex = '21';
      else if (el.dataset.kind === 'comment') el.style.zIndex = '22';
      else if (el.dataset.kind === 'free') el.style.zIndex = '23';
      else el.style.zIndex = '20';
    });
  });
};


window.reqChoosePointMulti = function(callback) {
  var pages = Array.from(
    document.querySelectorAll('.req-pdf-page-wrap')
  );

  if (!pages.length) {
    alert('La réquisition doit être affichée avant de placer un élément.');
    return;
  }

  function cleanup() {
    pages.forEach(function(wrap) {
      wrap.style.cursor = 'default';

      if (wrap._edusilPlacementHandler) {
        wrap.removeEventListener(
          'click',
          wrap._edusilPlacementHandler,
          true
        );
        wrap._edusilPlacementHandler = null;
      }
    });
  }

  pages.forEach(function(wrap) {
    wrap.style.cursor = 'crosshair';

    var handler = function(ev) {
      /* Ne pas placer un nouveau X lorsqu'on clique sur un élément existant. */
      if (ev.target.closest('.req-live-overlay')) return;

      var canvas = wrap.querySelector('.req-pdf-page-canvas, canvas');
      if (!canvas) return;

      var cr = canvas.getBoundingClientRect();

      /* Ignorer la bande Page 1/2 située au-dessus du canvas. */
      if (
        ev.clientX < cr.left ||
        ev.clientX > cr.right ||
        ev.clientY < cr.top ||
        ev.clientY > cr.bottom
      ) return;

      var x = (ev.clientX - cr.left) / cr.width;
      var y = (ev.clientY - cr.top) / cr.height;

      cleanup();

      callback({
        page: parseInt(wrap.dataset.page || '1'),
        x: Math.max(0, Math.min(1, x)),
        y: Math.max(0, Math.min(1, y))
      });
    };

    wrap._edusilPlacementHandler = handler;
    wrap.addEventListener('click', handler, true);
  });
};


