Shiny.addCustomMessageHandler(
  'req-print-all-final',
  function() {
    var pages = Array.from(
      document.querySelectorAll('.req-pdf-page-wrap')
    );

    if (!pages.length) {
      alert('Aucune page de réquisition à imprimer.');
      return;
    }

    var images = [];

    pages.forEach(function(wrap) {
      var canvas = wrap.querySelector(
        '.req-pdf-page-canvas, canvas'
      );
      if (!canvas) return;

      var out = document.createElement('canvas');
      out.width = canvas.width;
      out.height = canvas.height;

      var ctx = out.getContext('2d');
      ctx.drawImage(canvas, 0, 0);

      var cr = canvas.getBoundingClientRect();

      wrap.querySelectorAll('.req-live-overlay').forEach(
        function(el) {
          var er = el.getBoundingClientRect();

          var px =
            (er.left - cr.left) / cr.width * out.width;
          var py =
            (er.top - cr.top) / cr.height * out.height;

          var fs =
            (parseFloat(getComputedStyle(el).fontSize) || 14) *
            (out.width / cr.width);

          var weight =
            (el.dataset.kind === 'test') ? '900 ' : '700 ';

          ctx.font = weight + fs + 'px Arial';
          ctx.fillStyle = '#000';
          ctx.textBaseline = 'top';

          ctx.fillText(el.innerText || '', px, py);
        }
      );

      images.push(out.toDataURL('image/png'));
    });

    var w = window.reqPrintWindow;
    window.reqPrintWindow = null;

    if (!w || w.closed) {
      w = window.open('', '_blank');
    }

    if (!w) {
      alert(
        'Autorisez les fenêtres contextuelles pour EDUSILLAB, puis cliquez de nouveau sur Imprimer.'
      );
      return;
    }

    var d = w.document;
    d.open();
    d.title = 'Réquisition';

    var style = d.createElement('style');
    style.textContent =
      '@page{margin:0;} body{margin:0;} ' +
      '.page{page-break-after:always;} ' +
      '.page:last-child{page-break-after:auto;} ' +
      'img{display:block;width:100%;height:auto;}';
    d.head.appendChild(style);

    images.forEach(function(src) {
      var page = d.createElement('div');
      page.className = 'page';

      var img = d.createElement('img');
      img.src = src;

      page.appendChild(img);
      d.body.appendChild(page);
    });

    d.close();

    var imgs = Array.from(d.images || []);
    var lancerImpression = function(){
      setTimeout(function(){
        try { w.focus(); w.print(); } catch(e) {}
      }, 150);
    };

    if (!imgs.length || imgs.every(function(im){ return im.complete; })) {
      lancerImpression();
    } else {
      var restants = imgs.length;
      imgs.forEach(function(im){
        var fini=function(){ restants--; if(restants<=0) lancerImpression(); };
        if(im.complete) fini(); else { im.onload=fini; im.onerror=fini; }
      });
    }
  }
);
")),

    tags$script(HTML("
Shiny.addCustomMessageHandler('req-place-test',function(msg){
