Shiny.addCustomMessageHandler('req-print-final',function(msg){
  var canvas=document.getElementById('req_pdf_canvas');
  var wrap=document.getElementById('req_pdf_live_wrap');
  if(!canvas || !wrap) return;

  var out=document.createElement('canvas');
  out.width=canvas.width; out.height=canvas.height;
  var ctx=out.getContext('2d');
  ctx.drawImage(canvas,0,0);

  var wr=wrap.getBoundingClientRect();
  wrap.querySelectorAll('.req-live-overlay').forEach(function(el){
    var er=el.getBoundingClientRect();
    var x=(er.left-wr.left)/wr.width*out.width;
    var y=(er.top-wr.top)/wr.height*out.height;
    var txt=el.innerText || '';
    var fs=parseFloat(getComputedStyle(el).fontSize)||12;
    var scale=out.width/wr.width;
    ctx.font=(el.dataset.kind==='test'?'bold ':'')+(fs*scale)+'px Arial';
    ctx.fillStyle='black';
    ctx.textBaseline='top';
    ctx.fillText(txt,x,y);
  });

  var img=out.toDataURL('image/png');
  var w=window.open('','_blank');
  if(!w) { alert('Autorisez les fenêtres contextuelles pour imprimer.'); return; }
  var d=w.document;
  d.open();
  d.title='Réquisition';
  var style=d.createElement('style');
  style.textContent='@page{size:auto;margin:0} body{margin:0;text-align:center} img{width:100%;height:auto}';
  d.head.appendChild(style);
  var imageEl=d.createElement('img');
  imageEl.src=img;
  imageEl.onload=function(){ setTimeout(function(){ w.focus(); w.print(); },100); };
