    tags$script(HTML("
(function(){
  function initReqDrag(){
    var wrap=document.getElementById('req_pdf_live_wrap');
    if(!wrap) return;
    var active=null, dx=0, dy=0;

    wrap.querySelectorAll('.req-live-overlay').forEach(function(el){
      if(el.dataset.dragReady==='1') return;
      el.dataset.dragReady='1';

      el.addEventListener('mousedown',function(ev){
        ev.preventDefault();
        active=el;
        var er=el.getBoundingClientRect();
        dx=ev.clientX-er.left;
        dy=ev.clientY-er.top;
        el.style.zIndex='50';
      });
    });

    document.addEventListener('mousemove',function(ev){
      if(!active || !wrap.contains(active)) return;
      var wr=wrap.getBoundingClientRect();
      var x=(ev.clientX-wr.left-dx)/wr.width*100;
      var y=(ev.clientY-wr.top-dy)/wr.height*100;
      x=Math.max(0,Math.min(98,x));
      y=Math.max(0,Math.min(98,y));
      active.style.left=x+'%';
      active.style.top=y+'%';
    });

    document.addEventListener('mouseup',function(){
      if(!active) return;
      var wr=wrap.getBoundingClientRect();
      var er=active.getBoundingClientRect();
      var x=(er.left-wr.left)/wr.width;
      var y=(er.top-wr.top)/wr.height;
      Shiny.setInputValue('req_overlay_moved',{
        kind:active.dataset.kind,
        id:active.dataset.id,
        key:active.dataset.key,
        x:x,y:y,
        nonce:Date.now()
      },{priority:'event'});
      active.style.zIndex=(active.dataset.kind==='test'?'21':'20');
      active=null;
    });
  }

  $(document).on('shiny:value',function(e){
    if(e.name==='creation_pdf_preview_ui')
      setTimeout(initReqDrag,250);
  });
  $(document).on('shiny:connected',function(){
    setTimeout(initReqDrag,500);
  });
})();
