      db_execute(
        con_audit,
        "
        INSERT INTO audit_trail(
          patient_id,requisition_id,specimen_id,utilisateur_id,
          initiales,matricule,action,details
        ) VALUES (?,?,?,?,?,?,?,?)
        ",
        params = list(
          if (is.null(patient_id) || length(patient_id) == 0 || is.na(patient_id[1])) NA_integer_ else as.integer(patient_id[1]),
          if (is.null(requisition_id) || length(requisition_id) == 0 || is.na(requisition_id[1])) NA_integer_ else as.integer(requisition_id[1]),
          if (is.null(specimen_id) || length(specimen_id) == 0 || is.na(specimen_id[1])) NA_integer_ else as.integer(specimen_id[1]),
          if (is.null(u) || is.null(u$id) || length(u$id) == 0 || is.na(u$id[1])) NA_integer_ else as.integer(u$id[1]),
          if (is.null(u) || is.null(u$initiales) || length(u$initiales) == 0 || is.na(u$initiales[1])) "" else as.character(u$initiales[1]),
          if (is.null(u) || is.null(u$matricule) || length(u$matricule) == 0 || is.na(u$matricule[1])) "" else as.character(u$matricule[1]),
          if (is.null(action) || length(action) == 0 || is.na(action[1])) "" else as.character(action[1]),
          if (is.null(details) || length(details) == 0 || is.na(details[1])) "" else as.character(details[1])
        )
      )

      TRUE
    }, error=function(e) {
      message("Audit non enregistré : ", conditionMessage(e))
      FALSE
    })
  }


  # ----------------------------------------------------------
  # PLANCHES D'ÉTIQUETTES PARTAGÉES ENTRE TOUS LES UTILISATEURS
  # ----------------------------------------------------------
  reserver_cases_planche <- function(con, imprimante_id, nb_etiquettes, utilisateur_id=NA_integer_) {
    nb_etiquettes <- as.integer(nb_etiquettes)
    if (is.na(nb_etiquettes) || nb_etiquettes < 1) stop("Nombre d'étiquettes invalide.")

    imp <- db_query(con, "SELECT * FROM materiel_impression WHERE id=? LIMIT 1",
                           params=list(as.integer(imprimante_id)))
    if (nrow(imp) != 1) stop("Imprimante introuvable.")

    capacite <- max(1L, as.integer(imp$nb_colonnes[1]) * as.integer(imp$nb_lignes[1]))
    if (nb_etiquettes > capacite) stop("Le nombre d'étiquettes dépasse la capacité d'une planche.")

    # Transaction portable : SQLite conserve BEGIN IMMEDIATE; PostgreSQL/Neon
    # utilise DBI::dbBegin(), car PostgreSQL ne reconnaît pas BEGIN IMMEDIATE.
    if (est_postgres(con)) {
      DBI::dbBegin(con)
    } else {
      db_execute(con, "BEGIN IMMEDIATE")
    }
    ok <- FALSE
    on.exit(if (!ok) try(DBI::dbRollback(con), silent=TRUE), add=TRUE)

    etat <- db_query(con,
      "SELECT * FROM planches_etiquettes WHERE imprimante_id=?",
      params=list(as.integer(imprimante_id)))

    if (nrow(etat) == 0) {
      numero_planche <- 1L
      prochaine_case <- 1L
      db_execute(con,
        "INSERT INTO planches_etiquettes(imprimante_id,numero_planche,prochaine_case) VALUES (?,1,1)",
        params=list(as.integer(imprimante_id)))
    } else {
      numero_planche <- as.integer(etat$numero_planche[1])
      prochaine_case <- as.integer(etat$prochaine_case[1])
    }

    # Si les étiquettes ne tiennent plus, démarrer automatiquement une nouvelle planche.
    if ((prochaine_case + nb_etiquettes - 1L) > capacite) {
      numero_planche <- numero_planche + 1L
      prochaine_case <- 1L
    }

    debut <- prochaine_case
    fin <- debut + nb_etiquettes - 1L
    suivante <- fin + 1L

    if (suivante > capacite) {
      prochain_numero <- numero_planche + 1L
      prochaine_stockee <- 1L
    } else {
      prochain_numero <- numero_planche
      prochaine_stockee <- suivante
    }

    db_execute(con, "
      UPDATE planches_etiquettes
      SET numero_planche=?, prochaine_case=?, date_modification=CURRENT_TIMESTAMP, modifie_par=?
      WHERE imprimante_id=?",
      params=list(prochain_numero, prochaine_stockee, utilisateur_id, as.integer(imprimante_id)))

    db_execute(con, "
      INSERT INTO planches_etiquettes_historique
      (imprimante_id,numero_planche,case_debut,case_fin,nb_etiquettes,utilisateur_id)
      VALUES (?,?,?,?,?,?)",
      params=list(as.integer(imprimante_id),numero_planche,debut,fin,nb_etiquettes,utilisateur_id))

    DBI::dbCommit(con)
    ok <- TRUE
    list(numero_planche=numero_planche, case_debut=debut, case_fin=fin, capacite=capacite)
  }

  creer_pdf_planche_partagee <- function(labels, fichier, imp, case_debut=1L) {
    stopifnot(nrow(imp) == 1)
    pw <- as.numeric(imp$papier_largeur_mm[1]); ph <- as.numeric(imp$papier_hauteur_mm[1])
    lw <- as.numeric(imp$largeur_mm[1]); lh <- as.numeric(imp$hauteur_mm[1])
    nc <- as.integer(imp$nb_colonnes[1]); nr <- as.integer(imp$nb_lignes[1])
    orientation <- toupper(trimws(as.character(imp$orientation_page[1] %||% "PORTRAIT")))
    if (orientation == "PAYSAGE") {
      tmp <- pw; pw <- ph; ph <- tmp
      # En paysage, la grille physique est tournée avec la feuille.
      tmp <- nc; nc <- nr; nr <- tmp
    }
    ml <- as.numeric(imp$marge_gauche_mm[1]); mt <- as.numeric(imp$marge_haut_mm[1])
    px <- as.numeric(imp$pas_x_mm[1]); py <- as.numeric(imp$pas_y_mm[1])
    if (is.na(px)) px <- lw
    if (is.na(py)) py <- lh

    grDevices::pdf(fichier, width=pw/25.4, height=ph/25.4, paper="special",
                   onefile=TRUE, family="Helvetica")
    on.exit(grDevices::dev.off(), add=TRUE)
    par(mar=c(0,0,0,0), xaxs="i", yaxs="i")
    plot.new()
    plot.window(xlim=c(0,pw), ylim=c(0,ph))

    dessiner_une_etiquette <- function(z, x0, y0) {
      # Coordonnées locales 0..100 x 0..50 converties dans la case physique.
      X <- function(v) x0 + (v/100)*lw
      Y <- function(v) y0 + (v/50)*lh
      facteur <- min(1.35,max(0.55,min(lw/100,lh/50)))
      # Code-barres Code39
      chars <- strsplit(paste0("*", z$code_barre, "*"), "")[[1]]
      poids <- sum(vapply(chars,function(ch) sum(ifelse(strsplit(code39_patterns[[ch]],"")[[1]]=="w",3,1))+1,numeric(1)))
      pos <- X(3)
      largeur_bar <- X(97)-X(3)
      for (ch in chars) {
        pat <- strsplit(code39_patterns[[ch]],"")[[1]]
        for (j in seq_along(pat)) {
          w <- largeur_bar*(ifelse(pat[j]=="w",3,1)/poids)
          if (j%%2==1) rect(pos,Y(38.5),pos+w,Y(48.5),col="black",border=NA)
          pos <- pos+w
        }
        pos <- pos+largeur_bar*(1/poids)
      }
      text(X(50),Y(36.3),paste0("BC# ",z$code_barre),cex=.72*facteur,font=2)
      text(X(4),Y(32.7),z$numero_specimen,adj=0,cex=.76*facteur,font=2)
      text(X(96),Y(32.7),paste0("DOSSIER ",z$numero_dossier),adj=1,cex=.70*facteur,font=2)
      text(X(4),Y(28.6),paste0(z$nom,", ",z$prenom),adj=0,cex=.76*facteur,font=2)
      text(X(96),Y(28.6),paste0("SEXE: ",z$sexe),adj=1,cex=.66*facteur)
      text(X(4),Y(24.5),paste0("MED ",z$medicare),adj=0,cex=.64*facteur)
      text(X(96),Y(24.5),paste0("LOC ",z$location),adj=1,cex=.64*facteur)
      text(X(4),Y(20.3),paste0("# TUBES: ",z$quantite),adj=0,cex=.66*facteur,font=2)
      text(X(96),Y(20.3),z$contenant,adj=1,cex=.62*facteur,font=2)
      aa <- gsub(" | ",", ",z$analyses,fixed=TRUE)
      text(X(4),Y(15.7),paste0("ANALYSES: ",aa),adj=0,cex=.54*facteur,font=2)
      text(X(96),Y(10.8),paste0("REQ ",z$numero_requisition),adj=1,cex=.48*facteur)
      text(X(4),Y(10.8),paste0("SAISI PAR: ",z$saisi_nom_complet),adj=0,cex=.42*facteur,font=2)
      text(X(4),Y(7.4),paste0("DATE/HEURE: ",z$date_saisie),adj=0,cex=.39*facteur)
      text(X(96),Y(7.4),paste0("SIGNATURE: ",z$signature_initiales),adj=1,cex=.42*facteur,font=3)
    }

    for (i in seq_len(nrow(labels))) {
      case <- as.integer(case_debut) + i - 1L
      col <- (case - 1L) %% nc
      row <- (case - 1L) %/% nc
      x0 <- ml + col*px
      # PDF/R utilise l'origine en bas; Avery est mesuré depuis le haut.
      y0 <- ph - mt - lh - row*py
      dessiner_une_etiquette(labels[i,,drop=FALSE], x0, y0)
    }
    invisible(fichier)
  }

  creer_pdf_partage_ou_individuel <- function(labels, fichier, con, utilisateur_id=NA_integer_) {
    imp <- db_query(con, "
      SELECT * FROM materiel_impression
      WHERE actif=1
      ORDER BY par_defaut DESC,id LIMIT 1")
    if (nrow(imp)==1 && isTRUE(as.integer(imp$planche_partagee[1])==1L)) {
      res <- reserver_cases_planche(con, imp$id[1], nrow(labels), utilisateur_id)
      creer_pdf_planche_partagee(labels, fichier, imp, res$case_debut)
      attr(fichier,"reservation_planche") <- res
      return(fichier)
    }
    creer_pdf_selon_imprimante(labels,fichier,con)
    fichier
  }

  parametres_impression <- function(con=NULL) {
    fermer <- FALSE
    if (is.null(con)) {
      con <- ouvrir_db()
      fermer <- TRUE
    }
    if (fermer) on.exit(DBI::dbDisconnect(con), add=TRUE)

    imp <- db_query(
      con,
      "
      SELECT *
      FROM materiel_impression
      WHERE actif=1
        AND UPPER(COALESCE(type,'')) IN ('IMPRIMANTE','IMPRIMANTE ETIQUETTES','PDF')
      ORDER BY par_defaut DESC,id
      LIMIT 1
      "
    )

    if (nrow(imp)!=1) {
      return(list(largeur=100,hauteur=50,offset_x=0,offset_y=0,echelle=100,mode="AUTO"))
    }

    mode <- toupper(ifelse(
      is.na(imp$mode_ajustement[1]) || !nzchar(imp$mode_ajustement[1]),
      "AUTO",imp$mode_ajustement[1]
    ))

    list(
      largeur=ifelse(is.na(imp$largeur_mm[1]),100,imp$largeur_mm[1]),
      hauteur=ifelse(is.na(imp$hauteur_mm[1]),50,imp$hauteur_mm[1]),
      offset_x=ifelse(mode=="MANUEL",ifelse(is.na(imp$offset_x_mm[1]),0,imp$offset_x_mm[1]),0),
      offset_y=ifelse(mode=="MANUEL",ifelse(is.na(imp$offset_y_mm[1]),0,imp$offset_y_mm[1]),0),
      echelle=ifelse(mode=="MANUEL",ifelse(is.na(imp$echelle_pct[1]),100,imp$echelle_pct[1]),100),
      mode=mode
    )
  }

  creer_pdf_selon_imprimante <- function(labels,fichier,con=NULL) {
    p <- parametres_impression(con)
    creer_pdf_etiquettes(
      labels,fichier,
      largeur_mm=p$largeur,
      hauteur_mm=p$hauteur,
      offset_x_mm=p$offset_x,
      offset_y_mm=p$offset_y,
      echelle_pct=p$echelle
    )
  }

  charger_historique <- function() {
    con <- ouvrir_db()
    on.exit(DBI::dbDisconnect(con), add = TRUE)

    if (est_postgres(con)) {
      sql_hist <- "
      SELECT
        r.id AS requisition_id,
        r.numero_requisition AS Req,
        r.date_creation AS Date_creation,
        r.date_prelevement AS Date_prelevement,
        r.heure_prelevement AS Heure,
        p.numero_dossier AS Dossier,
        p.medicare AS Medicare,
        p.nom AS Nom_patient,
        p.prenom AS Prenom_patient,
        r.priorite AS Priorite,
        r.prescripteur AS Prescripteur,
        STRING_AGG(a.mnemonique, ', ' ORDER BY a.mnemonique) AS Analyses,
        STRING_AGG(COALESCE(dp.px, ''), ', ' ORDER BY COALESCE(dp.px, '')) AS Px,
        r.statut AS Statut,
        COALESCE(NULLIF(r.saisi_initiales,''), u.initiales, '') AS Initiales_saisie,
        COALESCE(NULLIF(r.saisi_matricule,''), u.matricule, '') AS Matricule_saisie,
        u.nom AS Nom_utilisateur,
        u.prenom AS Prenom_utilisateur,
        u.email AS Courriel,
        u.role AS Niveau,
        (
          SELECT STRING_AGG(
                   DISTINCT TRIM(COALESCE(ur.prenom,'') || ' ' || COALESCE(ur.nom,'')),
                   ', '
                 )
          FROM specimens sr
          LEFT JOIN utilisateurs ur ON ur.id = sr.recu_par
          WHERE sr.requisition_id = r.id
            AND sr.recu_par IS NOT NULL
        ) AS Receptionne_par,
        (
          SELECT STRING_AGG(
                   DISTINCT COALESCE(NULLIF(sr.recu_initiales,''), ur.initiales, ''),
                   ', '
                 )
          FROM specimens sr
          LEFT JOIN utilisateurs ur ON ur.id = sr.recu_par
          WHERE sr.requisition_id = r.id
            AND sr.recu_par IS NOT NULL
        ) AS Initiales_reception,
        (
          SELECT MAX(sr.date_reception)
          FROM specimens sr
          WHERE sr.requisition_id = r.id
        ) AS Date_reception
      FROM requisitions r
      INNER JOIN patients p ON p.id = r.patient_id
      LEFT JOIN utilisateurs u ON u.id = r.cree_par
      LEFT JOIN requisition_analyses ra ON ra.requisition_id = r.id
      LEFT JOIN analyses a ON a.id = ra.analyse_id
      LEFT JOIN departements_px dp ON UPPER(dp.departement) = UPPER(a.departement)
      GROUP BY
        r.id, r.numero_requisition, r.date_creation, r.date_prelevement,
        r.heure_prelevement, p.numero_dossier, p.medicare, p.nom, p.prenom,
        r.priorite, r.prescripteur, r.statut, r.saisi_initiales,
        r.saisi_matricule, u.initiales, u.matricule, u.nom, u.prenom,
        u.email, u.role
      ORDER BY r.id DESC
      "
    } else {
      sql_hist <- "
      SELECT
        r.id AS requisition_id,
        r.numero_requisition AS Req,
        r.date_creation AS Date_creation,
        r.date_prelevement AS Date_prelevement,
        r.heure_prelevement AS Heure,
        p.numero_dossier AS Dossier,
        p.medicare AS Medicare,
        p.nom AS Nom_patient,
        p.prenom AS Prenom_patient,
        r.priorite AS Priorite,
        r.prescripteur AS Prescripteur,
        GROUP_CONCAT(a.mnemonique, ', ') AS Analyses,
        GROUP_CONCAT(COALESCE(dp.px, ''), ', ') AS Px,
        r.statut AS Statut,
        COALESCE(NULLIF(r.saisi_initiales,''), u.initiales, '') AS Initiales_saisie,
        COALESCE(NULLIF(r.saisi_matricule,''), u.matricule, '') AS Matricule_saisie,
        u.nom AS Nom_utilisateur,
        u.prenom AS Prenom_utilisateur,
        u.email AS Courriel,
        u.role AS Niveau,
        (
          SELECT GROUP_CONCAT(DISTINCT TRIM(COALESCE(ur.prenom,'') || ' ' || COALESCE(ur.nom,'')))
          FROM specimens sr
          LEFT JOIN utilisateurs ur ON ur.id = sr.recu_par
          WHERE sr.requisition_id = r.id
            AND sr.recu_par IS NOT NULL
        ) AS Receptionne_par,
        (
          SELECT GROUP_CONCAT(DISTINCT COALESCE(NULLIF(sr.recu_initiales,''), ur.initiales, ''))
          FROM specimens sr
          LEFT JOIN utilisateurs ur ON ur.id = sr.recu_par
          WHERE sr.requisition_id = r.id
            AND sr.recu_par IS NOT NULL
        ) AS Initiales_reception,
        (
          SELECT MAX(sr.date_reception)
          FROM specimens sr
          WHERE sr.requisition_id = r.id
        ) AS Date_reception
      FROM requisitions r
      INNER JOIN patients p ON p.id = r.patient_id
      LEFT JOIN utilisateurs u ON u.id = r.cree_par
      LEFT JOIN requisition_analyses ra ON ra.requisition_id = r.id
      LEFT JOIN analyses a ON a.id = ra.analyse_id
      LEFT JOIN departements_px dp ON UPPER(dp.departement) = UPPER(a.departement)
      GROUP BY r.id
      ORDER BY r.id DESC
      "
    }

    tab <- tryCatch(
      db_query(con, sql_hist),
      error = function(e) {
        message("ERREUR HISTORIQUE : ", conditionMessage(e))
        data.frame()
      }
    )
    historique(tab)
  }

