                      document.addEventListener('keydown', function(e){
                        var zone = document.getElementById('hemato_compteur_clavier');
                        if(!zone || !Shiny || !Shiny.setInputValue) return;
                        var tag = (document.activeElement && document.activeElement.tagName || '').toLowerCase();
                        if(tag === 'input' || tag === 'textarea' || tag === 'select') return;
                        if(e.ctrlKey || e.altKey || e.metaKey) return;
                        if(e.key && e.key.length === 1){
                          Shiny.setInputValue(
                            'hemato_touche_pressee',
                            e.key.toUpperCase() + '|' + Date.now(),
                            {priority:'event'}
                          );
                          e.preventDefault();
                        }
                      }, true);
                    })();
                  ")),
                  uiOutput("hemato_compteur_resume")
