  normaliser_reference_specimen <- function(x, date_defaut=Sys.Date()) {
    x <- toupper(norm_txt(x))
    if (!nzchar(x)) return("")

    # ;H10 ou :H10 = date du jour + H10
    if (grepl("^[;:]\\s*[A-Z]+\\s*0*[0-9]+$", x)) {
      x <- paste0(format(as.Date(date_defaut), "%d%m"), sub("^[;:]\\s*", "", x))
    }

    # 2808 H10 / 2808:H10 / 2808-H10
    x <- gsub("[^A-Z0-9]", "", x)

    m <- regexec("^([0-9]{4})([A-Z]+)0*([0-9]+)([RUS])?$", x)
    z <- regmatches(x, m)[[1]]

    if (length(z) >= 4) {
      return(paste0(z[2], z[3], as.integer(z[4])))
    }

    x
  }

  trouver_specimen_par_reference <- function(con, code) {
    code <- norm_txt(code)
    if (!nzchar(code)) return(data.frame())

    code_normalise <- toupper(gsub("[^A-Z0-9]","",code))

    base_sql <- "
      SELECT
        s.id,s.requisition_id,s.patient_id,s.numero_specimen,s.code_barre,
        s.date_specimen,s.departement,s.px,s.analyses,s.contenant,s.quantite,
        s.location,s.priorite,s.statut_reception,s.date_reception,
        COALESCE(s.heure_collecte_recue,'') AS heure_collecte_recue,
        COALESCE(s.initiales_preleveur,'') AS initiales_preleveur,
        COALESCE(s.source_prelevement,'') AS source_prelevement,
        p.numero_dossier,p.medicare,p.nom,p.prenom,p.sexe,
        r.numero_requisition,
        COALESCE(NULLIF(s.saisi_initiales,''),uc.initiales,'') AS saisi_initiales,
        COALESCE(NULLIF(s.saisi_matricule,''),uc.matricule,'') AS saisi_matricule,
        COALESCE(NULLIF(s.recu_initiales,''),ur.initiales,'') AS recu_initiales,
        COALESCE(NULLIF(s.recu_matricule,''),ur.matricule,'') AS recu_matricule
      FROM specimens s
      JOIN patients p ON p.id=s.patient_id
      JOIN requisitions r ON r.id=s.requisition_id
      LEFT JOIN utilisateurs uc ON uc.id=s.cree_par
      LEFT JOIN utilisateurs ur ON ur.id=s.recu_par
    "

    direct <- db_query(
      con,
      paste0(
        base_sql,
        "
        WHERE
          s.code_barre=?
          OR UPPER(REPLACE(REPLACE(REPLACE(s.numero_specimen,':',''),' ',''),'-',''))=?
          OR p.numero_dossier=?
          OR r.numero_requisition=?
        ORDER BY CASE WHEN s.code_barre=? THEN 0 ELSE 1 END,s.id DESC
        LIMIT 1
        "
      ),
      params=list(code,code_normalise,code,code,code)
    )

    if (nrow(direct)==1) return(direct)

    # Recherche abrégée : 2808 H10 ou ;H10 pour la journée courante.
    cle_recherche <- normaliser_reference_specimen(code)
    if (!nzchar(cle_recherche)) return(data.frame())

    candidats <- db_query(
      con,
      paste0(
        base_sql,
        "
        WHERE substr(COALESCE(s.date_specimen,''),1,10) >= date('now','localtime','-7 day')
        ORDER BY s.id DESC
        LIMIT 500
        "
      )
    )

    if (nrow(candidats)==0) return(data.frame())

    cles <- vapply(
      candidats$numero_specimen,
      normaliser_reference_specimen,
      character(1)
    )

    candidats <- candidats[cles == cle_recherche, , drop=FALSE]
    if (nrow(candidats)==0) return(data.frame())

    candidats[1, , drop=FALSE]
  }

  # ----------------------------------------------------------
  # RÉCEPTION DES SPÉCIMENS
  # ----------------------------------------------------------

  observeEvent(input$rechercher_specimen_reception, {
    req(utilisateur_connecte()$perm_reception == 1)

    code <- norm_txt(input$reception_code)
    if (!nzchar(code)) {
      output$resultat_reception <- renderUI(
        div(class="danger-box","Saisissez ou scannez un BC#, un numéro de spécimen ou un dossier (ex. 2808 H10 ou ;H10 pour aujourd’hui).")
      )
      return()
    }

    con <- ouvrir_db()
    on.exit(DBI::dbDisconnect(con),add=TRUE)

    s <- trouver_specimen_par_reference(con, code)

    if (nrow(s)!=1) {
      specimen_reception(NULL)
      output$resultat_reception <- renderUI(div(class="danger-box","Spécimen non trouvé."))
      return()
    }

    specimen_reception(s)
    journaliser(
      "CONSULTATION_SPECIMEN",
      paste0("Consultation réception ",s$numero_specimen[1]," / BC# ",s$code_barre[1]),
      patient_id=s$patient_id[1],requisition_id=s$requisition_id[1],specimen_id=s$id[1]
    )

    deja_recu <- !is.na(s$statut_reception[1]) &&
      toupper(norm_txt(s$statut_reception[1]))=="RECU"
    annule <- !is.na(s$statut_reception[1]) &&
      toupper(norm_txt(s$statut_reception[1]))=="ANNULE"

    date_s <- suppressWarnings(as.Date(s$date_specimen[1]))
    retard <- !is.na(date_s) && date_s < Sys.Date()

    output$resultat_reception <- renderUI(
      div(
        class="admin-zone",
        h4(paste0(s$prenom[1]," ",s$nom[1])),
        p(strong("Dossier : "),s$numero_dossier[1]),
        p(strong("Req # : "),s$numero_requisition[1]),
        p(strong("Date du spécimen : "),s$date_specimen[1]),
        p(strong("Spécimen : "),s$numero_specimen[1]),
        p(strong("BC# : "),s$code_barre[1]),
        p(strong("Département : "),s$departement[1]),
        p(strong("Analyses : "),s$analyses[1]),
        p(strong("Contenant : "),s$contenant[1]),
        p(strong("Tests saisis par : "),paste0(s$saisi_initiales[1],s$saisi_matricule[1])),
        if (annule) {
          div(class="danger-box",strong("Ce spécimen est annulé."))
        } else if (deja_recu) {
          div(
            class="warning-box",
            p(strong("Déjà reçu.")),
            p(paste0("Reçu par ",s$recu_initiales[1],s$recu_matricule[1]," le ",s$date_reception[1]))
          )
        } else {
          tagList(
            if (retard) {
              div(
                class="warning-box",
                strong("Spécimen saisi à une date antérieure. "),
                "EDUSILLAB proposera de conserver ou corriger la date au moment de la réception."
              )
            },
            hr(),
            h4("Informations de collecte"),
            fluidRow(
              column(
                6,
                textInput(
                  "reception_heure_collecte",
                  "Heure de collecte",
                  value=ifelse(
                    nzchar(norm_txt(s$heure_collecte_recue[1])),
                    s$heure_collecte_recue[1],
                    ""
                  ),
                  placeholder="Ex. 08:35"
                )
              ),
              column(
                6,
                textInput(
                  "reception_initiales_preleveur",
                  "Initiales de la personne qui a prélevé",
                  value=s$initiales_preleveur[1],
                  placeholder="Ex. CK"
                )
              )
            ),
            p(
              class="text-muted",
              "Ces informations peuvent être saisies manuellement par la personne qui reçoit le spécimen."
            ),
            div(
              style="display:flex;gap:10px;flex-wrap:wrap;",
              actionButton("confirmer_reception_specimen","Confirmer la réception",class="btn-success"),
              actionButton("cancel_reception_specimen","Cancel",class="btn-default")
            )
          )
        }
      )
    )
  })


  # ------------------------------------------------------------
  # FICHE PDF DE RÉCEPTION DES SPÉCIMENS
  # Le PDF est lié à la dernière opération de réception.
  # ------------------------------------------------------------
  reception_pdf_data <- reactive({
    ids <- suppressWarnings(as.integer(derniere_reception_pdf_ids()))
    ids <- unique(ids[!is.na(ids)])
    if(length(ids)==0) return(data.frame())

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    marks <- paste(rep("?",length(ids)),collapse=",")

    db_query(
      con,
      paste0("
        SELECT
          s.id,
          s.numero_specimen,
          s.code_barre,
          s.departement,
          s.date_reception,
          COALESCE(NULLIF(s.recu_initiales,''),u.initiales,'') AS recu_initiales,
          COALESCE(NULLIF(s.recu_matricule,''),u.matricule,'') AS recu_matricule,
          p.numero_dossier,
          p.nom,
          p.prenom,
          p.date_naissance
        FROM specimens s
        JOIN patients p ON p.id=s.patient_id
        LEFT JOIN utilisateurs u ON u.id=s.recu_par
        WHERE s.id IN (",marks,")
        ORDER BY p.nom,p.prenom,s.numero_specimen
      "),
      params=as.list(ids)
    )
  })

  output$reception_pdf_document_ui <- renderUI({
    ids <- suppressWarnings(as.integer(derniere_reception_pdf_ids()))
    ids <- unique(ids[!is.na(ids)])
    if(length(ids)==0) return(NULL)

    d <- reception_pdf_data()
    if(nrow(d)==0) return(NULL)

    initials <- unique(trimws(as.character(d$recu_initiales)))
    initials <- initials[!is.na(initials) & nzchar(initials)]
    ini_txt <- if(length(initials)) paste(initials,collapse=", ") else "—"

    patients <- unique(paste(trimws(d$prenom),trimws(d$nom)))
    patients <- patients[nzchar(trimws(patients))]

    div(
      id="reception_pdf_document_box",
      style=paste0(
        "margin-top:16px;padding:16px 18px;",
        "border:2px solid #188b73;border-radius:10px;",
        "background:#f3fbf8;"
      ),
      h4("Document de réception"),
      p(
        strong("Patient : "),
        paste(patients,collapse=" / ")
      ),
      p(
        strong("Reçu par — initiales : "),
        ini_txt
      ),
      p(
        strong("Spécimens inclus : "),
        nrow(d)
      ),
      downloadButton(
        "reception_pdf_download",
        "Télécharger le PDF de réception",
        class="btn-success"
      )
    )
  })

  output$reception_pdf_download <- downloadHandler(
    filename=function() {
      d <- reception_pdf_data()
      if(nrow(d)==0)
        return(paste0("RECEPTION_SPECIMEN_",format(Sys.Date(),"%Y%m%d"),".pdf"))

      patient <- paste0(
        gsub("[^A-Za-z0-9_-]","_",toupper(norm_txt(d$nom[1]))),
        "_",
        gsub("[^A-Za-z0-9_-]","_",toupper(norm_txt(d$prenom[1])))
      )
      ini <- gsub("[^A-Za-z0-9_-]","",toupper(norm_txt(d$recu_initiales[1])))
      if(!nzchar(ini)) ini <- "UTILISATEUR"

      paste0(
        "RECEPTION_",patient,"_",ini,"_",
        format(Sys.Date(),"%Y%m%d"),".pdf"
      )
    },
    contentType="application/pdf",
    content=function(file) {
      d <- reception_pdf_data()
      if(nrow(d)==0) stop("Aucun spécimen reçu à inclure dans le PDF.")

      grDevices::pdf(
        file,
        width=8.5,
        height=11,
        paper="letter",
        onefile=TRUE
      )
      on.exit(grDevices::dev.off(),add=TRUE)

      # One patient section per patient. A multi-reception may contain
      # specimens from more than one patient.
      patient_key <- paste(d$numero_dossier,d$nom,d$prenom,sep="|")
      groupes <- split(seq_len(nrow(d)),patient_key)

      for(g in groupes) {
        z <- d[g,,drop=FALSE]

        graphics::plot.new()
        graphics::par(mar=c(0,0,0,0))

        graphics::text(
          .5,.95,
          "EDUSILLAB — FICHE DE RÉCEPTION DE SPÉCIMEN",
          cex=1.25,font=2
        )
        graphics::segments(.08,.925,.92,.925,lwd=1.5)

        y <- .88
        line <- function(label,value,cex=1) {
          graphics::text(.10,y,paste0(label," :"),adj=c(0,.5),font=2,cex=cex)
          graphics::text(.46,y,ifelse(is.na(value),"",as.character(value)),
                         adj=c(0,.5),cex=cex)
          y <<- y-.038
        }

        line("Patient",paste(z$prenom[1],z$nom[1]),1.08)
        line("Numéro de dossier",z$numero_dossier[1])
        line(
          "Date de naissance",
          ifelse(is.na(z$date_naissance[1]) || !nzchar(trimws(as.character(z$date_naissance[1]))),
                 "Non renseignée",z$date_naissance[1])
        )

        graphics::segments(.08,y+.005,.92,y+.005)
        y <- y-.035

        graphics::text(.10,y,"Réception effectuée par",adj=c(0,.5),font=2)
        y <- y-.045

        graphics::text(.10,y,"Initiales de l'étudiant / utilisateur :",adj=c(0,.5),font=2,cex=.92)
        graphics::text(.52,y,ifelse(is.na(z$recu_initiales[1]),"",z$recu_initiales[1]),
                       adj=c(0,.5),cex=1.25,font=2)
        y <- y-.038

        graphics::text(.10,y,"Matricule :",adj=c(0,.5),font=2)
        graphics::text(.28,y,ifelse(is.na(z$recu_matricule[1]),"",z$recu_matricule[1]),
                       adj=c(0,.5))
        y <- y-.055

        graphics::segments(.08,y+.018,.92,y+.018)
        graphics::text(.10,y,"Spécimen(s) reçu(s)",adj=c(0,.5),font=2,cex=1.05)
        y <- y-.045

        graphics::text(.10,y,"Détails des spécimens",adj=c(0,.5),font=2,cex=.92)
        y <- y-.035

        for(i in seq_len(nrow(z))) {
          if(y < .22) {
            graphics::text(.5,.055,"EDUSILLAB - document pédagogique",cex=.75)
            graphics::plot.new()
            graphics::par(mar=c(0,0,0,0))
            y <- .93
            graphics::text(.10,y,
              paste("Patient :",z$prenom[1],z$nom[1]),
              adj=c(0,.5),font=2)
            y <- y-.055
          }

          graphics::rect(.09,y-.115,.91,y+.018,border="grey70")

          graphics::text(.11,y,"BC# :",adj=c(0,.5),font=2,cex=.82)
          graphics::text(.20,y,
            ifelse(is.na(z$code_barre[i]),"",as.character(z$code_barre[i])),
            adj=c(0,.5),cex=.82)

          graphics::text(.40,y,"Spécimen :",adj=c(0,.5),font=2,cex=.82)
          graphics::text(.53,y,
            ifelse(is.na(z$numero_specimen[i]),"",as.character(z$numero_specimen[i])),
            adj=c(0,.5),cex=.82)

          y <- y-.035
          graphics::text(.11,y,"Département :",adj=c(0,.5),font=2,cex=.82)
          graphics::text(.28,y,
            ifelse(is.na(z$departement[i]),"",as.character(z$departement[i])),
            adj=c(0,.5),cex=.82)

          y <- y-.035
          graphics::text(.11,y,"Date / heure :",adj=c(0,.5),font=2,cex=.82)
          graphics::text(.28,y,
            ifelse(is.na(z$date_reception[i]),"",as.character(z$date_reception[i])),
            adj=c(0,.5),cex=.82)

          graphics::text(.66,y,"Initiales :",adj=c(0,.5),font=2,cex=.82)
          graphics::text(.78,y,
            ifelse(is.na(z$recu_initiales[i]),"",as.character(z$recu_initiales[i])),
            adj=c(0,.5),font=2,cex=.88)

          y <- y-.075
        }

        graphics::segments(.08,.085,.92,.085)
        graphics::text(
          .10,.055,
          paste0(
            "Document généré le ",
            format(Sys.time(),"%Y-%m-%d %H:%M")
          ),
          adj=c(0,.5),cex=.72
        )
        graphics::text(
          .90,.055,
          "EDUSILLAB",
          adj=c(1,.5),font=2,cex=.72
        )
      }
    }
  )


