  # Liste seulement les dossiers dont la demande contient une FSC.
  requetes_fsc <- reactive({
    req(utilisateur_connecte())
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    db_query(con,"
      SELECT DISTINCT r.id AS requisition_id,r.numero_requisition,r.patient_id,
             p.numero_dossier,p.nom,p.prenom
      FROM requisitions r
      JOIN patients p ON p.id=r.patient_id
      JOIN requisition_analyses ra ON ra.requisition_id=r.id
      JOIN analyses a ON a.id=ra.analyse_id
      LEFT JOIN departements_px dp ON UPPER(dp.departement)=UPPER(a.departement)
      LEFT JOIN attribution_dossiers_departement ad
        ON ad.requisition_id=r.id AND ad.px='H' AND ad.actif=1
      WHERE r.statut='ACTIVE'
        AND UPPER(COALESCE(dp.px,''))='H'
        AND (
          UPPER(?) IN ('ADMIN','SUPERUTILISATEUR')
          OR ad.etudiant_id=?
        )
        AND (
          UPPER(TRIM(COALESCE(a.mnemonique,''))) IN ('FSC','CBC','FBC','NFS')
          OR UPPER(COALESCE(a.nom,'')) LIKE '%FORMULE SANGUINE%'
          OR UPPER(COALESCE(a.nom,'')) LIKE '%NUMERATION FORMULE%'
          OR UPPER(COALESCE(a.nom,'')) LIKE '%NUMÉRATION FORMULE%'
          OR UPPER(COALESCE(a.nom,'')) LIKE '%COMPLETE BLOOD COUNT%'
        )
      ORDER BY r.id DESC",
      params=list(toupper(utilisateur_connecte()$role),utilisateur_connecte()$id))
  })

