  # Retourne les étudiants autorisés dans le département correspondant.
  etudiants_autorises_px <- function(con, px) {
    # L'attribution d'un dossier est elle-même une autorisation pédagogique.
    # Tous les comptes ETUDIANT actifs sont donc proposés à l'administrateur.
    db_query(con,"
      SELECT id,nom,prenom,identifiant
      FROM utilisateurs
      WHERE actif=1 AND UPPER(role)='ETUDIANT'
      ORDER BY nom,prenom,identifiant")
  }

  # Spécimens réellement reçus, séparés H et HC.
  dossiers_recus_px <- function(con, px) {
    db_query(con,"
      SELECT DISTINCT
        s.id AS specimen_id,s.requisition_id,s.patient_id,
        s.numero_specimen,s.code_barre,s.date_reception,
        p.numero_dossier,p.nom,p.prenom,
        r.numero_requisition,
        ad.etudiant_id,
        u.nom AS etudiant_nom,u.prenom AS etudiant_prenom,u.identifiant AS etudiant_identifiant
      FROM specimens s
      JOIN patients p ON p.id=s.patient_id
      JOIN requisitions r ON r.id=s.requisition_id
      LEFT JOIN attribution_dossiers_departement ad
        ON ad.requisition_id=s.requisition_id
       AND ad.px=?
       AND ad.actif=1
      LEFT JOIN utilisateurs u ON u.id=ad.etudiant_id
      WHERE UPPER(COALESCE(s.px,''))=?
        AND (
          UPPER(COALESCE(s.statut_reception,''))='RECU'
          OR s.date_reception IS NOT NULL
        )
        AND COALESCE(r.statut,'ACTIVE')<>'ANNULEE'
      ORDER BY s.date_reception DESC,s.id DESC",
      params=list(px,px))
  }



  tests_dynamiques_px <- function(con, px, seulement_hc_labo=FALSE) {
    px <- toupper(px)
    if(px=="HC" && isTRUE(seulement_hc_labo)) {
      return(db_query(con,"
        SELECT DISTINCT a.id,a.mnemonique,a.nom
        FROM analyses a
        JOIN hemato_hc_tests_labo hc ON hc.analyse_id=a.id AND hc.actif=1
        WHERE a.actif=1
        ORDER BY a.nom"))
    }
    db_query(con,"
      SELECT DISTINCT a.id,a.mnemonique,a.nom
      FROM analyses a
      LEFT JOIN departements_px dp ON UPPER(dp.departement)=UPPER(a.departement)
      WHERE a.actif=1 AND UPPER(COALESCE(dp.px,''))=?
      ORDER BY a.nom",params=list(px))
  }



  qc_tests_disponibles <- function(con, px) {
    d <- db_query(con,"
      SELECT qt.id,qt.px,qt.code,qt.nom,COALESCE(qu.symbole,'') AS unite
      FROM qc_tests qt
      LEFT JOIN qc_unites qu ON qu.id=qt.unite_id
      WHERE qt.actif=1
      ORDER BY qt.nom,qt.code")
    if (nrow(d)==0) return(d)
    d[toupper(as.character(d$px)) == toupper(as.character(px)),,drop=FALSE]
  }

  qc_unites_disponibles <- function(con) {
    db_query(con,"
      SELECT id,symbole,COALESCE(description,'') AS description
      FROM qc_unites WHERE actif=1 ORDER BY symbole")
  }

