  observeEvent(input$qc_run_save,{
    req(input$qc_run_controle,input$qc_run_valeur)
    val <- suppressWarnings(as.numeric(input$qc_run_valeur))
    if(is.na(val)) {
      showNotification("Entrez un résultat numérique.",type="error"); return()
    }
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    c0 <- db_query(con,"
      SELECT moyenne_cible,ecart_type_cible,date_expiration,actif
      FROM hemato_qc_controles WHERE id=?",params=list(as.integer(input$qc_run_controle)))
    if(nrow(c0)!=1 || c0$actif[1]!=1) {
      showNotification("Ce contrôle n'est pas actif.",type="error"); return()
    }
    if(nzchar(norm_txt(c0$date_expiration[1])) &&
       !is.na(as.Date(c0$date_expiration[1])) &&
       as.Date(c0$date_expiration[1]) < Sys.Date()) {
      showNotification("Ce lot de contrôle est expiré.",type="error"); return()
    }
    z <- NA_real_
    statut <- "NON_EVALUE"
    moy <- suppressWarnings(as.numeric(c0$moyenne_cible[1]))
    sd <- suppressWarnings(as.numeric(c0$ecart_type_cible[1]))
    if(!is.na(moy) && !is.na(sd) && sd>0) {
      z <- (val-moy)/sd
      statut <- if(abs(z)>=3) "HORS_CONTROLE" else if(abs(z)>=2) "AVERTISSEMENT" else "ACCEPTE"
    }
    db_execute(con,"
      INSERT INTO hemato_qc_resultats(
        controle_id,valeur,saisi_par,commentaire,statut_westgard,z_score
      ) VALUES (?,?,?,?,?,?)",
      params=list(as.integer(input$qc_run_controle),val,utilisateur_connecte()$id,
                  norm_txt(input$qc_run_commentaire),statut,z))
    qc_refresh(qc_refresh()+1L)
    showNotification(paste("Résultat QC enregistré —",statut),type=ifelse(statut=="HORS_CONTROLE","error","message"))
  })

