  qc_historique_filtre <- reactive({
    qc_refresh()
    req(input$qc_work_px)
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    sql <- "
      SELECT r.id AS `ID point`,r.date_resultat AS Date,c.px AS Département,
             COALESCE(qt.code,'') AS Code,COALESCE(qt.nom,'') AS Test,
             COALESCE(qu.symbole,'') AS Unité,
             c.nom_controle AS Contrôle,c.niveau AS Niveau,c.lot AS Lot,
             c.date_expiration AS Expiration,c.moyenne_cible AS `Moyenne cible`,
             c.ecart_type_cible AS `Écart-type cible`,r.valeur AS Résultat,
             ROUND(CAST(r.z_score AS NUMERIC),2) AS `Z-score`,r.statut_westgard AS Statut,
             CASE WHEN COALESCE(r.exclu_calcul,0)=1 THEN 'Oui' ELSE 'Non' END AS `Exclu calcul`,
             COALESCE(r.motif_exclusion,'') AS `Motif exclusion`,
             COALESCE(u.prenom,'') || ' ' || COALESCE(u.nom,'') AS `Saisi par`,
             COALESCE(u.identifiant,'') AS Identifiant,
             COALESCE(r.commentaire,'') AS Commentaire
      FROM hemato_qc_resultats r
      JOIN hemato_qc_controles c ON c.id=r.controle_id
      LEFT JOIN qc_tests qt ON qt.id=c.qc_test_id
      LEFT JOIN qc_unites qu ON qu.id=qt.unite_id
      LEFT JOIN utilisateurs u ON u.id=r.saisi_par
      WHERE c.px=?"
    params <- list(input$qc_work_px)

    if(!is.null(input$qc_hist_test) && nzchar(input$qc_hist_test)) {
      sql <- paste0(sql," AND c.qc_test_id=?")
      params <- c(params,list(as.integer(input$qc_hist_test)))
    }
    if(!is.null(input$qc_hist_user) && nzchar(input$qc_hist_user)) {
      sql <- paste0(sql," AND r.saisi_par=?")
      params <- c(params,list(as.integer(input$qc_hist_user)))
    }
    periode_qc <- as.character(input$qc_hist_periode %||% "jour")
    debut_qc <- NULL
    fin_qc <- NULL

    if (periode_qc == "jour") {
      debut_qc <- Sys.Date()
      fin_qc <- Sys.Date()
    } else if (periode_qc == "7j") {
      debut_qc <- Sys.Date()-6
      fin_qc <- Sys.Date()
    } else if (periode_qc == "30j") {
      debut_qc <- Sys.Date()-29
      fin_qc <- Sys.Date()
    } else if (periode_qc == "perso" &&
               !is.null(input$qc_hist_intervalle) &&
               length(input$qc_hist_intervalle)==2) {
      debut_qc <- as.Date(input$qc_hist_intervalle[1])
      fin_qc <- as.Date(input$qc_hist_intervalle[2])
    }

    if(!is.null(debut_qc) && !is.na(debut_qc)) {
      sql <- paste0(sql," AND CAST(r.date_resultat AS DATE) >= CAST(? AS DATE)")
      params <- c(params,list(as.character(debut_qc)))
    }
    if(!is.null(fin_qc) && !is.na(fin_qc)) {
      sql <- paste0(sql," AND CAST(r.date_resultat AS DATE) <= CAST(? AS DATE)")
      params <- c(params,list(as.character(fin_qc)))
    }
    sql <- paste0(sql," ORDER BY r.date_resultat DESC,r.id DESC")
    db_query(con,sql,params=params)
  })

