  observeEvent(input$qc_supprimer_point_confirmer,{
    req(qc_role_admin())
    d <- qc_historique_filtre()
    sel <- input$qc_historique_table_rows_selected
    if(length(sel)!=1 || sel<1 || sel>nrow(d)) { removeModal(); return() }
