      }
      pages <- split(seq_len(nrow(d)),ceiling(seq_len(nrow(d))/22))
      for(ids in pages) {
        graphics::plot.new()
        graphics::title(
          main=paste("EDUSILLAB — Historique QC",input$qc_work_px),
          sub=paste("Généré le",format(Sys.time(),"%Y-%m-%d %H:%M"))
        )
        dd <- d[ids,,drop=FALSE]
        txt <- apply(dd,1,function(z)
          paste(z[["Date"]]," | ",z[["Code"]]," ",z[["Test"]],
                " | ",z[["Résultat"]]," ",z[["Unité"]],
                " | ",z[["Contrôle"]]," ",z[["Niveau"]],
                " | Lot ",z[["Lot"]]," | Z ",z[["Z-score"]],
                " | ",z[["Statut"]]," | ",z[["Saisi par"]]))
        graphics::text(.02,seq(.9,.08,length.out=length(txt)),txt,adj=c(0,.5),cex=.52)
      }
    }
  )


  output$qc_lj_plot <- renderPlot({
    qc_refresh()
    req(input$qc_run_controle)
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)

    # Contrôle actuellement sélectionné.
    c0 <- db_query(con,"
      SELECT id,qc_test_id,px,nom_controle,niveau,lot,
             moyenne_cible,ecart_type_cible
      FROM hemato_qc_controles
      WHERE id=?",
      params=list(as.integer(input$qc_run_controle)))

    if(nrow(c0)!=1) {
      plot.new(); text(.5,.5,"Contrôle QC introuvable."); return()
    }

    # Afficher l'historique du même test + même contrôle + même niveau.
    # Chaque résultat conserve ainsi la moyenne, l'ET et le lot du contrôle
    # auquel il appartenait au moment de sa saisie.
    q <- db_query(con,"
      SELECT
        r.id AS resultat_id,
        r.valeur,
        r.date_resultat,
        c.id AS controle_id,
        c.lot,
        c.moyenne_cible,
        c.ecart_type_cible,
        c.date_creation
      FROM hemato_qc_resultats r
      JOIN hemato_qc_controles c ON c.id=r.controle_id
      WHERE c.qc_test_id=?
        AND c.px=?
        AND COALESCE(r.exclu_calcul,0)=0
        AND COALESCE(c.nom_controle,'')=COALESCE(?,'')
        AND COALESCE(c.niveau,'')=COALESCE(?,'')
      ORDER BY r.date_resultat,r.id",
      params=list(
        as.integer(c0$qc_test_id[1]),
        c0$px[1],
        c0$nom_controle[1],
        c0$niveau[1]
      ))

    if(nrow(q)==0) {
      plot.new(); text(.5,.5,"Aucun résultat QC à afficher."); return()
    }

    q$moyenne_cible <- suppressWarnings(as.numeric(q$moyenne_cible))
    q$ecart_type_cible <- suppressWarnings(as.numeric(q$ecart_type_cible))
    q$lot <- ifelse(is.na(q$lot),"",as.character(q$lot))

    x <- seq_len(nrow(q))
    y <- suppressWarnings(as.numeric(q$valeur))

    # L'échelle Y tient compte des résultats et des limites ±3 ET de
    # chaque période de moyenne.
    bornes <- y
    valides <- !is.na(q$moyenne_cible) & !is.na(q$ecart_type_cible) &
               q$ecart_type_cible > 0
    if(any(valides)) {
      bornes <- c(
        bornes,
        q$moyenne_cible[valides] - 3*q$ecart_type_cible[valides],
        q$moyenne_cible[valides] + 3*q$ecart_type_cible[valides]
      )
    }
    bornes <- bornes[is.finite(bornes)]
    ylim <- if(length(bornes)>=2) range(bornes) else range(y,na.rm=TRUE)
    marge <- diff(ylim)*0.08
    if(!is.finite(marge) || marge==0) marge <- max(abs(ylim),1)*0.08
    ylim <- ylim + c(-marge,marge)

    plot(x,y,type="b",pch=19,ylim=ylim,
         xlab="Série / résultat",ylab="Valeur QC",
         main=paste("Levey-Jennings —",c0$nom_controle[1],c0$niveau[1]))

    # Dessiner les lignes de moyenne/ET par segment historique.
    signature <- paste(q$controle_id,q$moyenne_cible,q$ecart_type_cible,q$lot,sep="|")
    debut_segment <- c(1L,which(signature[-1] != signature[-length(signature)])+1L)
    fin_segment <- c(debut_segment[-1]-1L,nrow(q))

    for(k in seq_along(debut_segment)) {
      a <- debut_segment[k]; b <- fin_segment[k]
      moy <- q$moyenne_cible[a]
      sd <- q$ecart_type_cible[a]
      if(is.finite(moy) && is.finite(sd) && sd>0) {
        graphics::segments(a-.45,moy,b+.45,moy,lwd=2)
        for(mult in c(-3,-2,-1,1,2,3)) {
          lt <- if(abs(mult)==2) 2 else 3
          graphics::segments(a-.45,moy+mult*sd,b+.45,moy+mult*sd,lty=lt)
        }
      }
    }

    # Changements entre deux résultats successifs.
    changement_moyenne <- rep(FALSE,nrow(q))
    changement_lot <- rep(FALSE,nrow(q))
    if(nrow(q)>1) {
      m1 <- q$moyenne_cible[-1]; m0 <- q$moyenne_cible[-nrow(q)]
      changement_moyenne[-1] <- (is.na(m1) != is.na(m0)) |
        (!is.na(m1) & !is.na(m0) & abs(m1-m0) > .Machine$double.eps^0.5)

      changement_lot[-1] <- q$lot[-1] != q$lot[-nrow(q)]
    }

    # Barrière orange = changement de moyenne cible.
    pos_moy <- which(changement_moyenne)
    if(length(pos_moy)>0)
      graphics::abline(v=pos_moy-.5,col="darkorange",lwd=3,lty=1)

    # Barrière bleue = changement de lot.
    # Si moyenne et lot changent au même endroit, la barre bleue est
    # légèrement décalée afin que les deux événements restent visibles.
    pos_lot <- which(changement_lot)
    if(length(pos_lot)>0) {
      xpos <- pos_lot-.5
      xpos[pos_lot %in% pos_moy] <- xpos[pos_lot %in% pos_moy]+.06
      graphics::abline(v=xpos,col="dodgerblue3",lwd=3,lty=1)
    }

    leg <- c("Résultat QC","Moyenne cible","±1/2/3 ET")
    cols <- c("black","black","black")
    ltys <- c(1,1,3)
    lwds <- c(1,2,1)

    if(length(pos_moy)>0) {
      leg <- c(leg,"Changement de moyenne")
      cols <- c(cols,"darkorange"); ltys <- c(ltys,1); lwds <- c(lwds,3)
    }
    if(length(pos_lot)>0) {
      leg <- c(leg,"Changement de lot")
      cols <- c(cols,"dodgerblue3"); ltys <- c(ltys,1); lwds <- c(lwds,3)
    }

    legend("topright",legend=leg,col=cols,lty=ltys,lwd=lwds,
           pch=c(19,NA,NA,rep(NA,length(leg)-3)),
           bg="white",cex=.78)

    # Annotation compacte des nouveaux lots au-dessus de leur barrière.
    if(length(pos_lot)>0) {
      for(j in pos_lot) {
        lab <- paste0("Lot ",q$lot[j])
        graphics::text(j-.45,ylim[2],labels=lab,pos=2,srt=90,
                       cex=.65,col="dodgerblue3",xpd=NA)
      }
    }
  })

