  observeEvent(input$qc_delete_test_btn,{
    req(qc_role_admin())
    test_id <- suppressWarnings(as.integer(input$qc_delete_test))
    if(length(test_id)!=1 || is.na(test_id)) {
      showNotification("Sélectionnez un test QC.",type="error"); return()
    }

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    test <- db_query(con,"
      SELECT id,code,nom,px FROM qc_tests WHERE id=? LIMIT 1",
      params=list(test_id))
    if(nrow(test)!=1) {
      showNotification("Test QC introuvable.",type="error"); return()
    }

    n_controles <- db_query(con,"
      SELECT COUNT(*) AS n FROM hemato_qc_controles WHERE qc_test_id=?",
      params=list(test_id))$n[1]
    n_resultats <- db_query(con,"
      SELECT COUNT(*) AS n
      FROM hemato_qc_resultats r
      JOIN hemato_qc_controles c ON c.id=r.controle_id
      WHERE c.qc_test_id=?",
      params=list(test_id))$n[1]

    if(n_resultats>0) {
      showModal(modalDialog(
        title="Désactiver le test QC ?",
        tags$p(
          tags$strong(paste0(test$code[1]," — ",test$nom[1])),
          " possède déjà ",n_resultats," résultat(s) QC."
        ),
        tags$p("Pour préserver la traçabilité, le test et ses contrôles seront désactivés mais l'historique ne sera pas supprimé."),
        footer=tagList(
          modalButton("Annuler"),
          actionButton("qc_delete_test_confirm_disable","Désactiver",class="btn-danger")
        ),
        easyClose=FALSE
      ))
    } else {
      showModal(modalDialog(
        title="Supprimer définitivement le test QC ?",
        tags$p(tags$strong(paste0(test$code[1]," — ",test$nom[1]))),
        tags$p("Aucun résultat QC n'est associé à ce test. Le test et ses contrôles sans résultat peuvent être supprimés définitivement."),
        footer=tagList(
          modalButton("Annuler"),
          actionButton("qc_delete_test_confirm_delete","Supprimer définitivement",class="btn-danger")
        ),
        easyClose=FALSE
      ))
    }
  })

  observeEvent(input$qc_delete_test_confirm_disable,{
    req(qc_role_admin())
    test_id <- suppressWarnings(as.integer(input$qc_delete_test))
    req(!is.na(test_id))
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)

    tryCatch({
      db_begin_retry(con)
      db_execute(con,"UPDATE qc_tests SET actif=0 WHERE id=?",params=list(test_id))
      db_execute(con,"
        UPDATE hemato_qc_controles SET actif=0 WHERE qc_test_id=?",
        params=list(test_id))
      db_commit_retry(con)
      removeModal()
      qc_refresh(qc_refresh()+1L)
      showNotification("Test QC désactivé. Son historique est conservé.",type="message")
    },error=function(e){
      try(DBI::dbRollback(con),silent=TRUE)
      removeModal()
      showNotification(paste("Impossible de désactiver le test :",conditionMessage(e)),
                       type="error",duration=10)
    })
  },ignoreInit=TRUE)

  observeEvent(input$qc_delete_test_confirm_delete,{
    req(qc_role_admin())
    test_id <- suppressWarnings(as.integer(input$qc_delete_test))
    req(!is.na(test_id))
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)

    # Recontrôle au moment exact de la suppression : un autre utilisateur
    # pourrait avoir saisi un résultat pendant que la confirmation était ouverte.
    n_resultats <- db_query(con,"
      SELECT COUNT(*) AS n
      FROM hemato_qc_resultats r
      JOIN hemato_qc_controles c ON c.id=r.controle_id
      WHERE c.qc_test_id=?",params=list(test_id))$n[1]

    if(n_resultats>0) {
      removeModal()
      showNotification(
        "Suppression annulée : un résultat QC existe maintenant. Désactivez plutôt le test.",
        type="warning",duration=10
      )
      qc_refresh(qc_refresh()+1L)
      return()
    }

    tryCatch({
      db_begin_retry(con)
      # Les contrôles sont sans résultats à ce stade.
      db_execute(con,"
        DELETE FROM hemato_qc_controles WHERE qc_test_id=?",
        params=list(test_id))
      db_execute(con,"DELETE FROM qc_tests WHERE id=?",params=list(test_id))
      db_commit_retry(con)
      removeModal()
      qc_refresh(qc_refresh()+1L)
      showNotification("Test QC supprimé définitivement.",type="message")
    },error=function(e){
      try(DBI::dbRollback(con),silent=TRUE)
      removeModal()
      showNotification(paste("Impossible de supprimer le test :",conditionMessage(e)),
                       type="error",duration=10)
    })
  },ignoreInit=TRUE)


  observeEvent(input$qc_admin_add,{
    req(qc_role_admin(),input$qc_work_px,input$qc_admin_test)
    nom <- norm_txt(input$qc_admin_nom)
    if(!nzchar(nom)) {
      showNotification("Le nom du contrôle est obligatoire.",type="error"); return()
    }
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)

    qc_test_id <- suppressWarnings(as.integer(input$qc_admin_test))
    if(length(qc_test_id)!=1 || is.na(qc_test_id)) {
      showNotification("Sélectionnez un test QC valide.",type="error")
      return()
    }

    # Compatibilité avec les anciennes bases EDUSILLAB :
    # analyse_id était historiquement NOT NULL.
    # Pour les nouveaux tests QC indépendants, on conserve qc_test_id
    # dans qc_test_id ET dans analyse_id (champ de compatibilité).
    tryCatch({
      db_execute(con,"
        INSERT INTO hemato_qc_controles(
          px,qc_test_id,analyse_id,nom_controle,niveau,lot,date_expiration,
          moyenne_cible,ecart_type_cible,actif,cree_par
        ) VALUES (?,?,?,?,?,?,?,?,?,1,?)",
        params=list(
          input$qc_work_px,
          qc_test_id,
          qc_test_id,
          nom,
          norm_txt(input$qc_admin_niveau),
          norm_txt(input$qc_admin_lot),
          as.character(input$qc_admin_exp),
          suppressWarnings(as.numeric(input$qc_admin_mean)),
          suppressWarnings(as.numeric(input$qc_admin_sd)),
          utilisateur_connecte()$id
        )
      )
      qc_refresh(qc_refresh()+1L)
      showNotification("Contrôle QC configuré pour le test.",type="message")
    }, error=function(e) {
      showNotification(
        paste("Impossible d'ajouter le contrôle :", conditionMessage(e)),
        type="error",
        duration=10
      )
    })
  })

