  # Catalogue HC : analyses du répertoire dont le PX est HC.
  analyses_hc_catalogue <- function(con) {
    db_query(con,"
      SELECT DISTINCT a.id,a.mnemonique,a.nom,
             COALESCE(hc.actif,0) AS actif_labo
      FROM analyses a
      LEFT JOIN departements_px dp
        ON UPPER(dp.departement)=UPPER(a.departement)
      LEFT JOIN hemato_hc_tests_labo hc ON hc.analyse_id=a.id
      WHERE a.actif=1 AND UPPER(COALESCE(dp.px,''))='HC'
      ORDER BY a.nom")
  }

  analyses_qc_px <- function(con,px) {
    if(toupper(px)=="HC") {
      return(db_query(con,"
        SELECT DISTINCT a.id,a.mnemonique,a.nom
        FROM analyses a
        JOIN hemato_hc_tests_labo hc ON hc.analyse_id=a.id AND hc.actif=1
        WHERE a.actif=1
        ORDER BY a.nom"))
    }
    db_query(con,"
      SELECT DISTINCT a.id,a.mnemonique,a.nom
      FROM analyses a
      LEFT JOIN departements_px dp
        ON UPPER(dp.departement)=UPPER(a.departement)
      WHERE a.actif=1 AND UPPER(COALESCE(dp.px,''))='H'
      ORDER BY a.nom")
  }

