  qc_controles_ui <- function(px,analyse_id,prefixe) {
    if(is.null(analyse_id) || !nzchar(as.character(analyse_id)))
      return(div(class="info-box","Sélectionnez une analyse."))
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    q <- db_query(con,"
      SELECT id,nom_controle,niveau,lot,date_expiration,moyenne_cible,ecart_type_cible,actif
      FROM hemato_qc_controles
      WHERE px=? AND analyse_id=?
      ORDER BY actif DESC,id DESC",
      params=list(px,as.integer(analyse_id)))

    config <- NULL
    if(role_admin_global()) {
      config <- wellPanel(
        h5("Ajouter un contrôle"),
        fluidRow(
          column(3,textInput(paste0(prefixe,"_nom"),"Nom du contrôle")),
          column(2,textInput(paste0(prefixe,"_niveau"),"Niveau")),
          column(2,textInput(paste0(prefixe,"_lot"),"Lot")),
          column(2,dateInput(paste0(prefixe,"_expiration"),"Expiration")),
          column(3,br(),actionButton(paste0(prefixe,"_ajouter"),"Ajouter",class="btn-primary"))
        ),
        fluidRow(
          column(3,numericInput(paste0(prefixe,"_moyenne"),"Moyenne cible",NA)),
          column(3,numericInput(paste0(prefixe,"_sd"),"Écart-type cible",NA))
        )
      )
    }

    table_controles <- if(nrow(q)==0)
      p("Aucun contrôle configuré pour cette analyse.")
    else tags$table(class="table table-bordered table-condensed",
      tags$thead(tags$tr(tags$th("Contrôle"),tags$th("Niveau"),tags$th("Lot"),
                         tags$th("Expiration"),tags$th("Moyenne"),tags$th("ET"),tags$th("État"))),
      tags$tbody(lapply(seq_len(nrow(q)),function(i)
        tags$tr(tags$td(q$nom_controle[i]),tags$td(q$niveau[i]),tags$td(q$lot[i]),
                tags$td(q$date_expiration[i]),tags$td(q$moyenne_cible[i]),
                tags$td(q$ecart_type_cible[i]),
                tags$td(ifelse(q$actif[i]==1,"Actif","Inactif")))))
    )
    tagList(config,table_controles)
  }

