  ajouter_controle_qc <- function(px,analyse_id,prefixe) {
    req(role_admin_global(),analyse_id)
    nom <- norm_txt(input[[paste0(prefixe,"_nom")]])
    if(!nzchar(nom)) {
      showNotification("Le nom du contrôle est obligatoire.",type="error")
      return()
    }
    exp <- as.character(input[[paste0(prefixe,"_expiration")]])
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    tryCatch({
      db_execute(con,"
        INSERT INTO hemato_qc_controles(
          px,analyse_id,nom_controle,niveau,lot,date_expiration,
          moyenne_cible,ecart_type_cible,cree_par,actif
        ) VALUES (?,?,?,?,?,?,?,?,?,1)",
        params=list(px,as.integer(analyse_id),nom,
                    norm_txt(input[[paste0(prefixe,"_niveau")]]),
                    norm_txt(input[[paste0(prefixe,"_lot")]]),
                    exp,
                    suppressWarnings(as.numeric(input[[paste0(prefixe,"_moyenne")]])),
                    suppressWarnings(as.numeric(input[[paste0(prefixe,"_sd")]])),
                    utilisateur_connecte()$id))
      refresh_hemato(refresh_hemato()+1L)
      showNotification(paste("Contrôle QC",px,"ajouté."),type="message")
    }, error=function(e) {
      showNotification(
        paste("Impossible d'ajouter le contrôle :",conditionMessage(e)),
        type="error",duration=10
      )
    })
  }

