  observeEvent(input$ref_ajouter,{
    req(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR"))
    req(input$ref_px,input$ref_test)
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)

    token <- as.character(input$ref_test)
    if(startsWith(token,"S:")) {
      code <- sub("^S:","",token)
      labels <- c(GB="GB",GR="GR",HB="Hb",HCT="Hct",VGM="VGM",TGMH="TGMH",
                  CGMH="CGMH",IDVE_CV="IDVE-CV",PLT="PLT",VPM="VPM",
                  GI="Granulocytes immatures",ERY_NUC="Érythrocytes nucléés")
      nom <- labels[[code]] %||% code
    } else {
      aid <- suppressWarnings(as.integer(sub("^A:","",token)))
      a <- db_query(con,"SELECT mnemonique,nom FROM analyses WHERE id=?",
                           params=list(aid))
      if(nrow(a)!=1) return()
      code <- norm_txt(a$mnemonique[1])
      if(!nzchar(code)) code <- paste0("ANALYSE_",aid)
      nom <- a$nom[1]
    }

    nval <- function(x) {
      z <- suppressWarnings(as.numeric(x))
      if(length(z)==0 || is.na(z)) NA_real_ else z
    }

    db_execute(con,"
      INSERT INTO references_tests(
        px,test_code,test_nom,sexe,age_min,age_max,valeur_min,valeur_max,
        valeur_texte,unite,actif,cree_par
      ) VALUES (?,?,?,?,?,?,?,?,?,?,1,?)",
      params=list(input$ref_px,code,nom,input$ref_sexe,
                  nval(input$ref_age_min),nval(input$ref_age_max),
                  nval(input$ref_val_min),nval(input$ref_val_max),
                  norm_txt(input$ref_val_texte),norm_txt(input$ref_unite),
                  utilisateur_connecte()$id))
    references_refresh(references_refresh()+1L)
    showNotification("Référence enregistrée.",type="message")
