  reference_hemato_patient <- function(con,rid,code) {
    pat <- db_query(con,"SELECT p.date_naissance,p.sexe FROM requisitions r JOIN patients p ON p.id=r.patient_id WHERE r.id=?",params=list(as.integer(rid)))
    rr <- db_query(con,"SELECT valeur_min,valeur_max,valeur_texte,unite,sexe,age_min,age_max FROM references_tests WHERE px='H' AND UPPER(test_code)=UPPER(?) AND actif=1 ORDER BY id DESC",params=list(code))
    if(nrow(rr)==0) return(list(min=NA_real_,max=NA_real_,texte="",unite=""))
    if(nrow(pat)==1){
      sx<-toupper(norm_txt(pat$sexe[1])); z<-rr[toupper(rr$sexe)=="TOUS"|toupper(rr$sexe)==sx,,drop=FALSE]; if(nrow(z)>0) rr<-z
      age<-suppressWarnings(floor(as.numeric(difftime(Sys.Date(),as.Date(pat$date_naissance[1]),units="days"))/365.2425))
      if(!is.na(age)){z<-rr[(is.na(rr$age_min)|age>=rr$age_min)&(is.na(rr$age_max)|age<=rr$age_max),,drop=FALSE];if(nrow(z)>0)rr<-z}
    }
    z<-rr[1,];list(min=z$valeur_min,max=z$valeur_max,texte=ifelse(is.na(z$valeur_texte),"",z$valeur_texte),unite=ifelse(is.na(z$unite),"",z$unite))
  }

  afficher_modal_parametres_hemato <- function(rid){
    hemato_config_requisition(as.integer(rid)); con<-ouvrir_db();on.exit(DBI::dbDisconnect(con),add=TRUE)
    old<-db_query(con,"SELECT * FROM hemato_attribution_parametres WHERE requisition_id=? AND px='H'",params=list(as.integer(rid)))
    pat<-db_query(con,"SELECT p.numero_dossier,p.prenom,p.nom FROM requisitions r JOIN patients p ON p.id=r.patient_id WHERE r.id=?",params=list(as.integer(rid)))
    lignes<-lapply(names(hemato_param_codes),function(code){
      o<-old[toupper(old$param_code)==toupper(code),,drop=FALSE]; ref<-reference_hemato_patient(con,rid,code)
      section <- NULL
      if(code=="GB") section <- tags$h4("Paramètres FSC",style="margin-top:8px;color:#1b5963;")
      if(code=="DIFF_NEUT") section <- tags$h4("Différentiel leucocytaire",style="margin-top:18px;color:#1b5963;")

      val<-if(nrow(o)==1&&!is.na(o$valeur_attendue[1]))as.character(o$valeur_attendue[1])else""
      unit<-if(nrow(o)==1&&nzchar(norm_txt(o$unite[1])))o$unite[1] else if(nzchar(ref$unite))ref$unite else hemato_param_unites_defaut[[code]]
      mn<-if(nrow(o)==1&&!is.na(o$ref_min[1]))o$ref_min[1] else ref$min; mx<-if(nrow(o)==1&&!is.na(o$ref_max[1]))o$ref_max[1] else ref$max
      rt<-if(nrow(o)==1&&nzchar(norm_txt(o$ref_texte[1])))o$ref_texte[1] else ref$texte
      tagList(section,
      div(style="border-bottom:1px solid #ddd;padding:8px 0;",fluidRow(
        column(2,strong(unname(hemato_param_codes[[code]]))),column(2,textInput(paste0("hap_val_",code),"Valeur attendue",val)),
        column(2,textInput(paste0("hap_unit_",code),"Unité",unit)),column(2,numericInput(paste0("hap_min_",code),"Réf. min",mn)),
        column(2,numericInput(paste0("hap_max_",code),"Réf. max",mx)),column(2,checkboxInput(paste0("hap_show_",code),"Montrer",nrow(o)==1&&o$montrer_etudiant[1]==1))),
        textInput(paste0("hap_reftext_",code),"Référence qualitative / note de correction",rt)))
    })
    titre<-if(nrow(pat)==1)paste0(pat$numero_dossier," — ",pat$prenom," ",pat$nom)else paste0("Réq. #",rid)
    showModal(modalDialog(title=paste("Paramètres Hématologie —",titre),
      div(class="info-box",strong("Réservé à l'administrateur : "),"les valeurs attendues et intervalles de la FSC et du différentiel servent à la correction. Seuls les paramètres cochés « Montrer » sont visibles par l'étudiant."),
      div(style="max-height:65vh;overflow-y:auto",lignes),footer=tagList(modalButton("Annuler"),actionButton("hap_save","Enregistrer",class="btn-success")),size="l",easyClose=FALSE))
  }

  observeEvent(input$hap_save,{
    req(role_admin_global());rid<-hemato_config_requisition();req(rid);con<-ouvrir_db();on.exit(DBI::dbDisconnect(con),add=TRUE)
    for(code in names(hemato_param_codes)){
      val<-norm_txt(input[[paste0("hap_val_",code)]]);unit<-norm_txt(input[[paste0("hap_unit_",code)]]);rt<-norm_txt(input[[paste0("hap_reftext_",code)]])
      mn<-suppressWarnings(as.numeric(input[[paste0("hap_min_",code)]]));mx<-suppressWarnings(as.numeric(input[[paste0("hap_max_",code)]]));show<-if(isTRUE(input[[paste0("hap_show_",code)]]))1L else 0L
      if(is.na(mn))mn<-NA_real_;if(is.na(mx))mx<-NA_real_
      db_execute(con,"INSERT INTO hemato_attribution_parametres(requisition_id,px,param_code,param_nom,valeur_attendue,unite,montrer_etudiant,ref_min,ref_max,ref_texte,configure_par,date_configuration) VALUES (?,'H',?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP) ON CONFLICT(requisition_id,px,param_code) DO UPDATE SET param_nom=excluded.param_nom,valeur_attendue=excluded.valeur_attendue,unite=excluded.unite,montrer_etudiant=excluded.montrer_etudiant,ref_min=excluded.ref_min,ref_max=excluded.ref_max,ref_texte=excluded.ref_texte,configure_par=excluded.configure_par,date_configuration=CURRENT_TIMESTAMP",params=list(as.integer(rid),code,unname(hemato_param_codes[[code]]),val,unit,show,mn,mx,rt,utilisateur_connecte()$id))
    }
    removeModal();refresh_hemato(refresh_hemato()+1L);showNotification("Paramètres pédagogiques enregistrés.",type="message")
  })

  # Observateur dynamique des boutons d'attribution.
  observe({
    req(role_admin_global())
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    for(px in c("H","HC")) {
      d <- dossiers_recus_px(con,px)
      if(nrow(d)==0) next
      for(i in seq_len(nrow(d))) local({
        rid <- d$requisition_id[i]
        pid <- d$patient_id[i]
        sid <- d$specimen_id[i]
        px_local <- px
        btn <- paste0("save_attrib_",px_local,"_",rid)
        sel <- paste0("attrib_",px_local,"_",rid)
        observeEvent(input[[btn]],{
          valeur_etu <- input[[sel]]
          etu <- suppressWarnings(as.integer(valeur_etu))
          con2 <- ouvrir_db(); on.exit(DBI::dbDisconnect(con2),add=TRUE)
          if(length(etu) == 0 || is.na(etu)) {
            db_execute(con2,"
              UPDATE attribution_dossiers_departement
              SET actif=0
              WHERE requisition_id=? AND px=?",
              params=list(rid,px_local))
            showNotification("Attribution retirée.",type="message")
          } else {
            db_execute(con2,"
              INSERT INTO attribution_dossiers_departement(
                requisition_id,patient_id,specimen_id,px,etudiant_id,attribue_par,actif
              ) VALUES (?,?,?,?,?,?,1)
              ON CONFLICT(requisition_id,px) DO UPDATE SET
                patient_id=excluded.patient_id,
                specimen_id=excluded.specimen_id,
                etudiant_id=excluded.etudiant_id,
                attribue_par=excluded.attribue_par,
                date_attribution=CURRENT_TIMESTAMP,
                actif=1",
              params=list(rid,pid,sid,px_local,etu,utilisateur_connecte()$id))
            showNotification(paste("Dossier",px_local,"attribué à l'étudiant."),type="message")
          }
          refresh_hemato(refresh_hemato()+1L)
        },ignoreInit=TRUE)
        if(px_local=="H") {
          btn_param <- paste0("config_hemato_",rid)
          observeEvent(input[[btn_param]],{req(role_admin_global());afficher_modal_parametres_hemato(rid)},ignoreInit=TRUE)
        }
      })
    }
  })

  # Contrôle central : un étudiant ne peut voir qu'un dossier qui lui est attribué,
  # et l'attribution H ne donne pas accès à HC (et inversement).
  etudiant_peut_voir_dossier_px <- function(con,requisition_id,px) {
    if(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR")) return(TRUE)
    q <- db_query(con,"
      SELECT 1
      FROM attribution_dossiers_departement
      WHERE requisition_id=? AND px=? AND etudiant_id=? AND actif=1
      LIMIT 1",
      params=list(as.integer(requisition_id),toupper(px),utilisateur_connecte()$id))
    nrow(q)==1
  }


  # À appliquer aux listes de réception : les admins voient tous les spécimens;
  # les étudiants voient seulement ceux qui leur sont attribués dans le PX concerné.
  filtrer_reception_attribuee <- function(con, donnees) {
    if(is.null(donnees) || nrow(donnees)==0) return(donnees)
    if(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR")) return(donnees)
    if(!all(c("requisition_id","px") %in% names(donnees))) return(donnees[0,,drop=FALSE])
    ok <- vapply(seq_len(nrow(donnees)),function(i)
      etudiant_peut_voir_dossier_px(con,donnees$requisition_id[i],donnees$px[i]),logical(1))
    donnees[ok,,drop=FALSE]
  }

  output$hemato_raccourcis_ui <- renderUI({
    req(utilisateur_connecte())
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    x <- db_query(con,
      "SELECT cellule,touche FROM hemato_frottis_raccourcis WHERE utilisateur_id=?",
      params=list(utilisateur_connecte()$id))
    vals <- setNames(touches_defaut,cellules_gb)
    if(nrow(x)>0) for(i in seq_len(nrow(x))) vals[x$cellule[i]] <- x$touche[i]
    tagList(lapply(seq_along(cellules_gb),function(i)
      textInput(paste0("hemato_key_",i),cellules_gb[i],value=vals[cellules_gb[i]])))
