  observeEvent(input$hemato_sauver_raccourcis,{
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    keys <- toupper(trimws(vapply(seq_along(cellules_gb),function(i)
      input[[paste0("hemato_key_",i)]] %||% "",character(1))))
    if(any(!nzchar(keys)) || any(nchar(keys)!=1) || anyDuplicated(keys)) {
      showNotification("Chaque cellule doit avoir une touche unique d'un seul caractère.",type="error")
      return()
    }
    db_execute(con,"DELETE FROM hemato_frottis_raccourcis WHERE utilisateur_id=?",
                   params=list(utilisateur_connecte()$id))
    for(i in seq_along(cellules_gb))
      db_execute(con,
        "INSERT INTO hemato_frottis_raccourcis(utilisateur_id,cellule,touche) VALUES (?,?,?)",
        params=list(utilisateur_connecte()$id,cellules_gb[i],keys[i]))
    showNotification("Touches de comptage enregistrées.",type="message")
  })

  observeEvent(input$hemato_nouveau_frottis,{
    req(hemato_requisition_fsc())
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    if(!etudiant_peut_voir_dossier_px(con,hemato_requisition_fsc(),"H")) {
      showNotification("Ce dossier H n'est pas attribué à cet étudiant.",type="error")
      return()
    }

    # Vérification serveur : la FSC doit encore être présente dans la demande.
    verif_fsc <- db_query(con,"
      SELECT r.patient_id
      FROM requisitions r
      JOIN requisition_analyses ra ON ra.requisition_id=r.id
      JOIN analyses a ON a.id=ra.analyse_id
      LEFT JOIN departements_px dp ON UPPER(dp.departement)=UPPER(a.departement)
      WHERE r.id=? AND UPPER(COALESCE(dp.px,''))='H'
        AND (
          UPPER(TRIM(COALESCE(a.mnemonique,''))) IN ('FSC','CBC','FBC','NFS')
          OR UPPER(COALESCE(a.nom,'')) LIKE '%FORMULE SANGUINE%'
          OR UPPER(COALESCE(a.nom,'')) LIKE '%NUMERATION FORMULE%'
          OR UPPER(COALESCE(a.nom,'')) LIKE '%NUMÉRATION FORMULE%'
          OR UPPER(COALESCE(a.nom,'')) LIKE '%COMPLETE BLOOD COUNT%'
        )
      LIMIT 1",params=list(hemato_requisition_fsc()))
    if(nrow(verif_fsc)!=1) {
      showNotification("FSC absente de la demande : différentiel bloqué.",type="error")
      return()
    }

    # Si l'étudiant n'a jamais sauvegardé ses touches, créer automatiquement
    # les raccourcis par défaut afin que le clavier fonctionne immédiatement.
    nb_keys <- db_query(con,
      "SELECT COUNT(*) AS n FROM hemato_frottis_raccourcis WHERE utilisateur_id=?",
      params=list(utilisateur_connecte()$id))$n[1]
    if(is.na(nb_keys) || nb_keys==0) {
      for(i in seq_along(cellules_gb))
        db_execute(con,
          "INSERT OR IGNORE INTO hemato_frottis_raccourcis(utilisateur_id,cellule,touche) VALUES (?,?,?)",
          params=list(utilisateur_connecte()$id,cellules_gb[i],touches_defaut[i]))
    }

    sp <- db_query(con,"
      SELECT id FROM specimens
      WHERE requisition_id=? AND UPPER(COALESCE(px,''))='H'
      ORDER BY id DESC LIMIT 1",params=list(hemato_requisition_fsc()))
    specimen_id <- if(nrow(sp)==1) sp$id[1] else NA_integer_
    db_execute(con,
      "INSERT INTO hemato_frottis(utilisateur_id,patient_id,specimen_id) VALUES (?,?,?)",
      params=list(utilisateur_connecte()$id,verif_fsc$patient_id[1],specimen_id))
    id <- db_query(con,"SELECT last_insert_rowid() AS id")$id[1]
    for(cell in cellules_gb)
      db_execute(con,"INSERT INTO hemato_frottis_gb(frottis_id,cellule,nombre) VALUES (?,?,0)",
                     params=list(id,cell))
    frottis_actif(id)
    refresh_hemato(refresh_hemato()+1L)
    showNotification("Nouveau comptage démarré — le clavier est actif.",type="message")
  })

  derniere_touche_hemato <- reactiveVal("")

  observeEvent(input$hemato_touche_pressee,{
    req(frottis_actif())
    brut <- as.character(input$hemato_touche_pressee)
    key <- toupper(trimws(strsplit(brut,"|",fixed=TRUE)[[1]][1]))
    if(!nzchar(key)) return()
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    r <- db_query(con,
      "SELECT cellule FROM hemato_frottis_raccourcis WHERE utilisateur_id=? AND UPPER(touche)=UPPER(?)",
      params=list(utilisateur_connecte()$id,key))
    if(nrow(r)==1) {
      derniere_touche_hemato(paste0("Touche ",key," → ",r$cellule[1]))
      total_actuel <- db_query(con,
        "SELECT COALESCE(total_gb,0) AS total FROM hemato_frottis WHERE id=?",
        params=list(frottis_actif()))$total[1]
      if (is.na(total_actuel)) total_actuel <- 0
      if (total_actuel >= 100) {
        showNotification("Comptage terminé : 100 cellules. Aucun résultat ne peut dépasser 100 %.",type="message",duration=3)
        return()
      }
      db_execute(con,
        "UPDATE hemato_frottis_gb SET nombre=nombre+1 WHERE frottis_id=? AND cellule=?",
        params=list(frottis_actif(),r$cellule[1]))
      db_execute(con,
        "UPDATE hemato_frottis SET total_gb=MIN(total_gb+1,100) WHERE id=?",
        params=list(frottis_actif()))
      refresh_hemato(refresh_hemato()+1L)
    }
  })

