      "SELECT g.cellule,g.nombre,COALESCE(r.touche,'') AS touche
       FROM hemato_frottis_gb g
       LEFT JOIN hemato_frottis_raccourcis r
         ON r.utilisateur_id=? AND r.cellule=g.cellule
