          tags$tr(tags$td(paste0(d$cellule[i],ifelse(nzchar(d$touche[i]),paste0(" [",d$touche[i],"]"),""))),
                  tags$td(strong(d$nombre[i])),
                  tags$td(sprintf("%.1f %%",pct[i]))))))
    )
  })

