    val <- function(x) if(is.null(x) || length(x)==0 || is.na(x)) NA_real_ else as.numeric(x)
    db_execute(con,"
      INSERT INTO hemato_frottis_rapport(
        frottis_id,gb,gr,hb,hct,vgm,tgmh,cgmh,idve_cv,plt,vpm,
