      ) VALUES (?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,?,CURRENT_TIMESTAMP)
      ON CONFLICT(frottis_id) DO UPDATE SET
        gb=excluded.gb,gr=excluded.gr,hb=excluded.hb,hct=excluded.hct,
        vgm=excluded.vgm,tgmh=excluded.tgmh,cgmh=excluded.cgmh,idve_cv=excluded.idve_cv,
        plt=excluded.plt,vpm=excluded.vpm,granulocytes_immatures=excluded.granulocytes_immatures,
