  output$hr_professeur_ui <- renderUI({
    req(frottis_actif())
    u <- utilisateur_connecte()
    if(!toupper(u$role) %in% c("ADMIN","SUPERUTILISATEUR")) return(
      div(class="info-box","Le commentaire du professeur apparaîtra ici après correction.")
    )
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    fi <- db_query(con,"SELECT f.*,s.requisition_id,r.* FROM hemato_frottis f LEFT JOIN specimens s ON s.id=f.specimen_id LEFT JOIN hemato_frottis_rapport r ON r.frottis_id=f.id WHERE f.id=?",params=list(frottis_actif()))
    correction <- NULL
    if(nrow(fi)==1 && !is.na(fi$requisition_id[1])) {
      pa <- db_query(con,"SELECT * FROM hemato_attribution_parametres WHERE requisition_id=? AND px='H' ORDER BY id",params=list(fi$requisition_id[1]))
      if(nrow(pa)>0){
        diff_counts <- db_query(con,"
          SELECT cellule,nombre
          FROM hemato_frottis_gb
          WHERE frottis_id=?",params=list(frottis_actif()))
        total_diff <- sum(diff_counts$nombre,na.rm=TRUE)

        diff_pct <- function(noms) {
          if(nrow(diff_counts)==0 || total_diff<=0) return(NA_real_)
          cle <- toupper(trimws(diff_counts$cellule))
          n <- sum(diff_counts$nombre[cle %in% toupper(noms)],na.rm=TRUE)
          round(100*n/total_diff,1)
        }

        sval<-function(c)switch(toupper(c),
          GB=fi$gb[1],GR=fi$gr[1],HB=fi$hb[1],HCT=fi$hct[1],
          VGM=fi$vgm[1],TGMH=fi$tgmh[1],CGMH=fi$cgmh[1],
          IDVE_CV=fi$idve_cv[1],PLT=fi$plt[1],VPM=fi$vpm[1],
          GI=fi$granulocytes_immatures[1],ERY_NUC=fi$erythrocytes_nuclees[1],
          DIFF_NEUT=diff_pct(c("NEUTROPHILE","NEUTROPHILES","NEUT")),
          DIFF_LYMPH=diff_pct(c("LYMPHOCYTE","LYMPHOCYTES","LYMPH")),
          DIFF_MONO=diff_pct(c("MONOCYTE","MONOCYTES","MONO")),
          DIFF_EOS=diff_pct(c("EOSINOPHILE","ÉOSINOPHILE","EOSINOPHILES","ÉOSINOPHILES","EOS")),
          DIFF_BASO=diff_pct(c("BASOPHILE","BASOPHILES","BASO")),
          DIFF_BAND=diff_pct(c("BANDE","BANDES","BAND")),
          DIFF_META=diff_pct(c("METAMYELOCYTE","MÉTAMYÉLOCYTE","METAMYELOCYTES","MÉTAMYÉLOCYTES")),
          DIFF_MYELO=diff_pct(c("MYELOCYTE","MYÉLOCYTE","MYELOCYTES","MYÉLOCYTES")),
          DIFF_PROMYELO=diff_pct(c("PROMYELOCYTE","PROMYÉLOCYTE","PROMYELOCYTES","PROMYÉLOCYTES")),
          DIFF_BLAST=diff_pct(c("BLASTE","BLASTES","BLAST")),
          NA)
        rows<-lapply(seq_len(nrow(pa)),function(i){sv<-sval(pa$param_code[i]);svt<-if(length(sv)==0||is.na(sv))""else as.character(sv);mn<-pa$ref_min[i];mx<-pa$ref_max[i];ref<-if(nzchar(norm_txt(pa$ref_texte[i])))pa$ref_texte[i] else if(!is.na(mn)&&!is.na(mx))paste0(mn," – ",mx) else if(!is.na(mn))paste0("≥ ",mn) else if(!is.na(mx))paste0("≤ ",mx) else "—"; exp<-norm_txt(pa$valeur_attendue[i]);stat<-if(!nzchar(svt))"NON SAISI" else if(nzchar(exp)){a<-suppressWarnings(as.numeric(svt));b<-suppressWarnings(as.numeric(exp));if(!is.na(a)&&!is.na(b)&&isTRUE(all.equal(a,b,tolerance=1e-8)))"CONFORME" else if(toupper(svt)==toupper(exp))"CONFORME" else "À CORRIGER"} else {a<-suppressWarnings(as.numeric(svt));if(!is.na(a)&&(!is.na(mn)||!is.na(mx))){if((is.na(mn)||a>=mn)&&(is.na(mx)||a<=mx))"DANS L'INTERVALLE" else "HORS INTERVALLE"}else"À VÉRIFIER"};tags$tr(tags$td(pa$param_nom[i]),tags$td(ifelse(nzchar(exp),exp,"—")),tags$td(ifelse(nzchar(svt),svt,"—")),tags$td(ref),tags$td(pa$unite[i]),tags$td(ifelse(pa$montrer_etudiant[i]==1,"Oui","Non")),tags$td(strong(stat)))})
        correction<-tagList(h4("Grille de correction — administrateur seulement"),div(class="warning-box","Les intervalles corrects ne sont jamais montrés à l'étudiant."),tags$div(style="overflow-x:auto",tags$table(class="table table-bordered table-condensed",tags$thead(tags$tr(tags$th("Paramètre"),tags$th("Valeur attendue"),tags$th("Saisie étudiant"),tags$th("Intervalle correct"),tags$th("Unité"),tags$th("Montré"),tags$th("Correction"))),tags$tbody(rows))))
      }
    }
    tagList(
      correction,
      h4("Correction du professeur"),
      textAreaInput("hr_commentaire_prof","Commentaire du professeur après correction"),
      actionButton("hr_valider_prof","Valider / corriger le rapport",class="btn-success")
    )
  })

