      SELECT f.*,r.*,
        u.nom AS lecteur_nom,u.prenom AS lecteur_prenom,u.initiales AS lecteur_initiales,u.matricule AS lecteur_matricule,
        p.nom AS patient_nom,p.prenom AS patient_prenom,p.numero_dossier,p.medicare,p.date_naissance,p.sexe,
        s.numero_specimen,s.code_barre,
        up.nom AS prof_nom,up.prenom AS prof_prenom,up.initiales AS prof_initiales
      FROM hemato_frottis f
      LEFT JOIN hemato_frottis_rapport r ON r.frottis_id=f.id
      JOIN utilisateurs u ON u.id=f.utilisateur_id
      LEFT JOIN patients p ON p.id=f.patient_id
      LEFT JOIN specimens s ON s.id=f.specimen_id
      LEFT JOIN utilisateurs up ON up.id=r.corrige_par
      WHERE f.id=?",params=list(frottis_actif()))
    diff <- db_query(con,
      "SELECT cellule,nombre FROM hemato_frottis_gb WHERE frottis_id=? ORDER BY cellule",
      params=list(frottis_actif()))
    morph <- db_query(con,
      "SELECT morphologie,grade FROM hemato_frottis_morphologie_gr WHERE frottis_id=? ORDER BY morphologie",
      params=list(frottis_actif()))
    list(info=info,diff=diff,morph=morph)
  })

  output$hr_rapport_resume <- renderUI({
