    if(nrow(x$info)==0) return(NULL)
    total <- sum(x$diff$nombre)
    pct <- if(total>0) 100*x$diff$nombre/total else rep(0,nrow(x$diff))
    gb <- suppressWarnings(as.numeric(x$info$gb[1]))
    absolu <- if(!is.na(gb) && total>0) gb*pct/100 else rep(NA_real_,nrow(x$diff))
    tagList(
      h4("Aperçu du différentiel"),
      tags$table(class="table table-bordered table-condensed",
        tags$thead(tags$tr(tags$th("Cellule"),tags$th("Compte"),tags$th("Pourcentage GB (%)"),tags$th("Compte absolu (×10^9/L)"))),
        tags$tbody(lapply(seq_len(nrow(x$diff)),function(i)
          tags$tr(tags$td(x$diff$cellule[i]),tags$td(x$diff$nombre[i]),
                  tags$td(sprintf("%.1f %%",pct[i])),
                  tags$td(if(is.na(absolu[i])) "—" else sprintf("%.3f",absolu[i]))))))
    )
  })

  observeEvent(input$hr_generer_pdf,{
    req(frottis_actif())
    x <- donnees_rapport_frottis()
    req(nrow(x$info)==1)
    # PDF HTML autonome imprimable depuis le navigateur.
    i <- x$info[1,]
    total <- sum(x$diff$nombre)
    pct <- if(total>0) 100*x$diff$nombre/total else rep(0,nrow(x$diff))
    gb <- suppressWarnings(as.numeric(i$gb))
    absolu <- if(!is.na(gb) && total>0) gb*pct/100 else rep(NA_real_,nrow(x$diff))
    esc <- function(z) htmltools::htmlEscape(ifelse(is.na(z),"",as.character(z)))
    rows_diff <- paste(vapply(seq_len(nrow(x$diff)),function(k)
      sprintf("<tr><td>%s</td><td>%d</td><td>%.1f %%</td><td>%s</td></tr>",
              esc(x$diff$cellule[k]),x$diff$nombre[k],pct[k],
              if(is.na(absolu[k])) "—" else sprintf("%.3f",absolu[k])),character(1)),collapse="")
    rows_morph <- if(nrow(x$morph)==0) "<tr><td colspan='2'>Aucune morphologie rapportée</td></tr>" else
      paste(vapply(seq_len(nrow(x$morph)),function(k)
        sprintf("<tr><td>%s</td><td>%s</td></tr>",esc(x$morph$morphologie[k]),esc(x$morph$grade[k])),
        character(1)),collapse="")
    vals <- c(GB=i$gb,GR=i$gr,Hb=i$hb,Hct=i$hct,VGM=i$vgm,TGMH=i$tgmh,CGMH=i$cgmh,
              `IDVE-CV`=i$idve_cv,PLT=i$plt,VPM=i$vpm,`Granulocytes immatures`=i$granulocytes_immatures)
    # Références configurées pour les paramètres de l'hémogramme.
    con_ref <- ouvrir_db()
    refs_pdf <- db_query(con_ref,"
      SELECT test_code,sexe,age_min,age_max,valeur_min,valeur_max,valeur_texte,unite
      FROM references_tests
      WHERE px='H' AND actif=1")
    DBI::dbDisconnect(con_ref)

    age_patient <- suppressWarnings(as.numeric(
      floor(as.numeric(difftime(Sys.Date(),as.Date(i$date_naissance),units='days'))/365.2425)
    ))
    sexe_patient <- toupper(norm_txt(i$sexe))

    ref_affiche <- function(code) {
      rr <- refs_pdf[toupper(refs_pdf$test_code)==toupper(code),,drop=FALSE]
      if(nrow(rr)==0) return("—")
      rr <- rr[(toupper(rr$sexe)=="TOUS" | toupper(rr$sexe)==sexe_patient),,drop=FALSE]
      if(!is.na(age_patient) && nrow(rr)>0) {
        rr <- rr[(is.na(rr$age_min) | age_patient>=rr$age_min) &
                 (is.na(rr$age_max) | age_patient<=rr$age_max),,drop=FALSE]
      }
      if(nrow(rr)==0) return("—")
      z <- rr[1,]
      if(nzchar(norm_txt(z$valeur_texte)))
        return(paste0(z$valeur_texte,if(nzchar(norm_txt(z$unite))) paste0(" ",z$unite) else ""))
      if(!is.na(z$valeur_min) || !is.na(z$valeur_max)) {
        lim <- if(!is.na(z$valeur_min) && !is.na(z$valeur_max))
          paste0(z$valeur_min," – ",z$valeur_max)
        else if(!is.na(z$valeur_min)) paste0("≥ ",z$valeur_min)
        else paste0("≤ ",z$valeur_max)
        return(paste0(lim,if(nzchar(norm_txt(z$unite))) paste0(" ",z$unite) else ""))
      }
      "—"
    }

    code_map <- c(GB="GB",GR="GR",Hb="HB",Hct="HCT",VGM="VGM",TGMH="TGMH",
                  CGMH="CGMH",`IDVE-CV`="IDVE_CV",PLT="PLT",VPM="VPM",
                  `Granulocytes immatures`="GI")
    rows_cbc <- paste(vapply(names(vals),function(nm)
      sprintf("<tr><td>%s</td><td>%s</td><td>%s</td></tr>",
              esc(nm),esc(vals[[nm]]),esc(ref_affiche(code_map[[nm]]))),
      character(1)),collapse="")
    html <- paste0("<!doctype html><html><head><meta charset='utf-8'><style>",
      "body{font-family:Arial,sans-serif;margin:28px;color:#111} h1{text-align:center} table{border-collapse:collapse;width:100%;margin:12px 0} td,th{border:1px solid #777;padding:6px} .meta{display:grid;grid-template-columns:1fr 1fr;gap:5px}.sign{margin-top:28px;border-top:1px solid #222;padding-top:8px}@media print{button{display:none}}",
      "</style></head><body><h1>EDUSILLAB — Rapport d'hématologie</h1>",
      "<div class='meta'><div><b>Patient :</b> ",esc(paste(i$patient_prenom,i$patient_nom)),"</div>",
      "<div><b>Dossier :</b> ",esc(i$numero_dossier),"</div><div><b>Medicare :</b> ",esc(i$medicare),"</div>",
      "<div><b>DDN :</b> ",esc(i$date_naissance),"</div><div><b>Sexe :</b> ",esc(i$sexe),"</div>",
      "<div><b>Spécimen :</b> ",esc(i$numero_specimen),"</div><div><b>BC# :</b> ",esc(i$code_barre),"</div></div>",
      "<h2>Hémogramme</h2><table><tr><th>Paramètre</th><th>Résultat</th><th>Référence</th></tr>",rows_cbc,"</table>",
      if(nzchar(norm_txt(i$autre_nom))) paste0("<p><b>Autre — ",esc(i$autre_nom)," :</b> ",esc(i$autre_valeur),"</p>") else "",
      "<h2>Différentiel leucocytaire</h2><table><tr><th>Cellule</th><th>Compte</th><th>%</th><th>Compte absolu</th></tr>",rows_diff,"</table>",
      "<h2>Morphologie des globules rouges</h2><table><tr><th>Morphologie</th><th>Grade</th></tr>",rows_morph,"</table>",
      "<p><b>Érythrocytes nucléés :</b> ",esc(i$erythrocytes_nuclees),"</p>",
      "<p><b>Commentaire frottis :</b> ",esc(i$commentaire_frottis),"</p>",
      "<p><b>Commentaire professeur :</b> ",esc(i$commentaire_professeur),"</p>",
      "<div class='sign'><b>Décompte effectué par :</b> ",esc(paste(i$lecteur_prenom,i$lecteur_nom)),
      " — ",esc(i$lecteur_matricule)," — Initiales/signature : ",esc(i$lecteur_initiales),
      "<br><b>Date et heure :</b> ",esc(i$date_lecture),"</div>",
      if(!is.na(i$corrige_par)) paste0("<div class='sign'><b>Corrigé par :</b> ",esc(paste(i$prof_prenom,i$prof_nom)),
        " — Initiales : ",esc(i$prof_initiales),"<br><b>Date de correction :</b> ",esc(i$date_correction),"</div>") else "",
      "<script>window.onload=function(){window.print();}</script></body></html>")
    fn <- file.path(preview_dir,paste0("RAPPORT_HEMATOLOGIE_",frottis_actif(),"_",format(Sys.time(),"%Y%m%d_%H%M%S"),".html"))
    writeLines(html,fn,useBytes=TRUE)
    rapport_frottis_pdf(fn)
  })

