  # Une cellule "Autre" est ajoutée uniquement au décompte actif.
  observeEvent(input$hemato_liquide_autre_ajouter,{
    req(liquide_actif())
    nom <- trimws(as.character(input$hemato_liquide_autre_nom %||% ""))
    touche <- toupper(trimws(as.character(input$hemato_liquide_autre_touche %||% "")))

    if(!nzchar(nom)) {
      showNotification("Entrez le nom de la cellule observée.",type="error"); return()
    }
    if(nzchar(touche) && nchar(touche)!=1) {
      showNotification("La touche doit contenir un seul caractère.",type="error"); return()
    }
    touches <- liquide_touches()
    if(nzchar(touche) && touche %in% unname(touches)) {
      showNotification("Cette touche est déjà utilisée.",type="error"); return()
    }

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    existe <- db_query(con,"
      SELECT 1 FROM hemato_liquides_decompte
      WHERE liquide_id=? AND UPPER(cellule)=UPPER(?) LIMIT 1",
      params=list(liquide_actif(),nom))
    if(nrow(existe)>0) {
      showNotification("Cette cellule est déjà dans le décompte.",type="warning"); return()
    }
    db_execute(con,"
      INSERT INTO hemato_liquides_decompte(liquide_id,cellule,nombre)
      VALUES (?,?,0)",params=list(liquide_actif(),nom))
    if(nzchar(touche)) {
      touches[nom] <- touche
      liquide_touches(touches)
    }
    updateTextInput(session,"hemato_liquide_autre_nom",value="")
    updateTextInput(session,"hemato_liquide_autre_touche",value="")
    refresh_hemato(refresh_hemato()+1L)
    showNotification(paste("Cellule ajoutée :",nom),type="message")
  })

  modifier_compte_liquide <- function(cellule,delta) {
    req(liquide_actif())
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    total <- db_query(con,"
      SELECT COALESCE(SUM(nombre),0) AS n
      FROM hemato_liquides_decompte WHERE liquide_id=?",
      params=list(liquide_actif()))$n[1]
    cur <- db_query(con,"
      SELECT nombre FROM hemato_liquides_decompte
      WHERE liquide_id=? AND cellule=?",
      params=list(liquide_actif(),cellule))
    if(nrow(cur)!=1) return(FALSE)
    if(delta>0 && total>=liquide_limite()) {
      showNotification("La limite de cellules est atteinte.",type="warning"); return(FALSE)
    }
    if(delta<0 && cur$nombre[1]<=0) return(FALSE)
    nouveau <- max(0L,as.integer(cur$nombre[1])+as.integer(delta))
    db_execute(con,"
      UPDATE hemato_liquides_decompte
      SET nombre=?
      WHERE liquide_id=? AND cellule=?",
      params=list(nouveau,liquide_actif(),cellule))
    db_execute(con,"
      UPDATE hemato_liquides
      SET total_cellules=(
        SELECT COALESCE(SUM(nombre),0)
        FROM hemato_liquides_decompte WHERE liquide_id=?
      )
      WHERE id=?",
      params=list(liquide_actif(),liquide_actif()))
    refresh_hemato(refresh_hemato()+1L)
    TRUE
  }

  # Un seul observateur pour tous les boutons +1/-1.
  # Évite de recréer des observeEvent à chaque rafraîchissement de l'interface.
  observeEvent(input$hemato_liquide_action,{
    req(liquide_actif())
    brut <- as.character(input$hemato_liquide_action)
    morceaux <- strsplit(brut,"|",fixed=TRUE)[[1]]
    if(length(morceaux)<2) return()
    cellule <- morceaux[1]
    delta <- suppressWarnings(as.integer(morceaux[2]))
    if(is.na(delta) || !delta %in% c(-1L,1L)) return()
    modifier_compte_liquide(cellule,delta)
  },ignoreInit=TRUE)

  # Capture clavier globale pour le décompte du liquide.
  observeEvent(input$hemato_liquide_touche_pressee,{
    req(liquide_actif())
    brut <- as.character(input$hemato_liquide_touche_pressee)
    key <- toupper(trimws(strsplit(brut,"|",fixed=TRUE)[[1]][1]))
    touches <- liquide_touches()
    if(is.null(touches) || length(touches)==0) return()
    cellule <- names(touches)[!is.na(unname(touches)) & unname(touches)==key]
    if(length(cellule)>=1 && nzchar(cellule[1]))
      modifier_compte_liquide(cellule[1],1L)
  })

