      db_execute(con,
        "INSERT INTO hemato_westgard(automate_id,analyse_id,regle,active) VALUES (?,?,?,1)",
        params=list(aid,tid,reg))
    db_execute(con,
      "INSERT OR IGNORE INTO hemato_automate_tests(automate_id,analyse_id,actif) VALUES (?,?,1)",
      params=list(aid,tid))
    showNotification("Règles Westgard enregistrées pour cet automate et ce test.",type="message")
  })

