  # OUTSTANDING DES SPÉCIMENS
  # ----------------------------------------------------------
  observe({
    req(utilisateur_connecte())
    refresh_outstanding()
    con <- ouvrir_db()
    on.exit(DBI::dbDisconnect(con), add=TRUE)
    d <- db_query(con, "
      SELECT DISTINCT COALESCE(NULLIF(TRIM(px),''),'SANS PX') AS px
      FROM specimens
      WHERE UPPER(COALESCE(statut_reception,'')) <> 'ANNULE'
      ORDER BY px")
    choix <- c("Tous"="", setNames(d$px,d$px))
    updateSelectizeInput(session,"outstanding_px",choices=choix,selected="",server=TRUE)
  })

  output$outstanding_departement_ui <- renderUI({
    req(utilisateur_connecte())
    px <- norm_txt(input$outstanding_px)
    con <- ouvrir_db()
    on.exit(DBI::dbDisconnect(con), add=TRUE)
    uact <- utilisateur_connecte()
    if (toupper(uact$role) %in% c("ADMIN","SUPERUTILISATEUR")) {
      if (nzchar(px) && px != "SANS PX") {
        d <- db_query(con,
          "SELECT DISTINCT departement FROM departements_px WHERE UPPER(COALESCE(px,''))=UPPER(?) ORDER BY departement",
          params=list(px))
      } else {
        d <- db_query(con,
          "SELECT DISTINCT departement FROM departements_px ORDER BY departement")
      }
    } else {
      autor <- departements_autorises_utilisateur(con,uact$id,uact$role)
      d <- data.frame(departement=autor$nom,stringsAsFactors=FALSE)
      if (nzchar(px) && px != "SANS PX" && nrow(autor)>0)
        d <- data.frame(departement=autor$nom[toupper(autor$px)==toupper(px)],stringsAsFactors=FALSE)
    }
    selectizeInput("outstanding_departement","Département",
      choices=c("Tous"="",setNames(d$departement,d$departement)),
      selected="",multiple=FALSE)
  })

  donnees_outstanding <- reactive({
    req(utilisateur_connecte())
    refresh_outstanding()
    input$outstanding_actualiser

    px <- norm_txt(input$outstanding_px)
    dep <- norm_txt(input$outstanding_departement)

    con <- ouvrir_db()
    on.exit(DBI::dbDisconnect(con),add=TRUE)

    # Charger les spécimens sans filtres SQL dynamiques, puis filtrer en R.
    # Ceci évite les différences SQLite/PostgreSQL sur les alias et paramètres.
    d <- tryCatch(
      db_query(con,"
        SELECT
          s.id,
          CASE
            WHEN UPPER(COALESCE(s.statut_reception,''))='RECU' THEN 'REÇU'
            WHEN COALESCE(s.etiquette_generee,0)=1 THEN 'COLB'
            ELSE 'ORD'
          END AS Statut,
          COALESCE(s.px,'') AS PX,
          COALESCE(s.departement,'') AS Departement,
          s.numero_specimen AS Specimen,
          s.code_barre AS `BC#`,
          r.numero_requisition AS Requisition,
          COALESCE(p.numero_dossier,'UNK') AS Dossier,
          TRIM(COALESCE(p.nom,'') || ', ' || COALESCE(p.prenom,'')) AS Patient,
          COALESCE(s.analyses,'') AS Analyses,
          COALESCE(s.contenant,'') AS Tube,
          COALESCE(s.priorite,'') AS Priorite,
          COALESCE(s.date_creation,'') AS `Date saisie`,
          COALESCE(s.date_etiquette_generee,'') AS `Etiquette generee`,
          COALESCE(s.date_reception,'') AS `Date reception`
        FROM specimens s
        JOIN patients p ON p.id=s.patient_id
        JOIN requisitions r ON r.id=s.requisition_id
        WHERE UPPER(COALESCE(s.statut_reception,'')) <> 'ANNULE'
        ORDER BY s.id DESC
      "),
      error=function(e) {
        message("ERREUR OUTSTANDING : ",conditionMessage(e))
        data.frame()
      }
    )

    if (nrow(d)==0) return(d)

    if (nzchar(px)) {
      if (toupper(px)=="SANS PX") {
        d <- d[!nzchar(trimws(as.character(d$PX))),,drop=FALSE]
      } else {
        d <- d[toupper(trimws(as.character(d$PX)))==toupper(px),,drop=FALSE]
      }
    }

    if (nzchar(dep) && nrow(d)>0) {
      d <- d[toupper(trimws(as.character(d$Departement)))==toupper(dep),,drop=FALSE]
    }

    uact <- utilisateur_connecte()
    if (!toupper(uact$role) %in% c("ADMIN","SUPERUTILISATEUR") && nrow(d)>0) {
      autor <- departements_autorises_utilisateur(con,uact$id,uact$role)
      if (nrow(autor)==0) {
        d <- d[0,,drop=FALSE]
      } else {
        px_autorises <- unique(unlist(lapply(autor$px,function(z)
          toupper(trimws(unlist(strsplit(ifelse(is.na(z),"",z),",")))))))
        px_autorises <- px_autorises[nzchar(px_autorises)]
        ok_dep <- toupper(d$Departement) %in% toupper(autor$nom) |
                  (nzchar(d$PX) & toupper(d$PX) %in% px_autorises)
        d <- d[ok_dep,,drop=FALSE]
      }
    }

    garder <- character(0)
    if (isTRUE(input$outstanding_recu)) garder <- c(garder,"REÇU")
    if (isTRUE(input$outstanding_colb)) garder <- c(garder,"COLB")
    if (isTRUE(input$outstanding_ord)) garder <- c(garder,"ORD")

    if (length(garder)==0 || nrow(d)==0) return(d[0,,drop=FALSE])
    d[d$Statut %in% garder,,drop=FALSE]
  })

  output$outstanding_resume <- renderUI({
    d <- donnees_outstanding()
    if (is.null(d) || nrow(d)==0 || !"Statut" %in% names(d)) {
      return(div(class="info-box",strong("Total : 0 spécimen")))
    }
    n_recu <- sum(d$Statut=="REÇU",na.rm=TRUE)
    n_colb <- sum(d$Statut=="COLB",na.rm=TRUE)
    n_ord <- sum(d$Statut=="ORD",na.rm=TRUE)
    div(class="info-box",
        strong(paste0("Total : ",nrow(d)," spécimen(s)")),
        HTML(paste0("&nbsp;&nbsp; REÇU : ",n_recu,
                    "&nbsp;&nbsp; | &nbsp;&nbsp; COLB : ",n_colb,
                    "&nbsp;&nbsp; | &nbsp;&nbsp; ORD : ",n_ord)))
  })

  output$table_outstanding <- DT::renderDT({
    d <- donnees_outstanding()
    if (is.null(d) || nrow(d)==0 || ncol(d)==0) {
      return(DT::datatable(
        data.frame(Message="Aucun spécimen correspondant aux filtres."),
        rownames=FALSE,options=list(dom="t")
      ))
    }
    if ("id" %in% names(d)) d$id <- NULL
    DT::datatable(d,rownames=FALSE,filter="top",
      options=list(pageLength=25,scrollX=TRUE))
  })

  observeEvent(input$outstanding_actualiser,{
    refresh_outstanding(refresh_outstanding()+1L)
  })

