      updateNumericInput(session,"mat_largeur",value=66.675)
      updateNumericInput(session,"mat_hauteur",value=25.4)
      updateNumericInput(session,"mat_papier_largeur",value=215.9)
      updateNumericInput(session,"mat_papier_hauteur",value=279.4)
      updateNumericInput(session,"mat_colonnes",value=3)
      updateNumericInput(session,"mat_lignes",value=10)
      updateNumericInput(session,"mat_marge_gauche",value=4.7625)
      updateNumericInput(session,"mat_marge_haut",value=12.7)
      updateNumericInput(session,"mat_pas_x",value=69.85)
