                as.character(as.integer(round(a$nb_tubes[1]))),
                as.character(a$nb_tubes[1])
              )
            )
          )
        )
      ),
      fluidRow(
        column(6, p(strong("Priorité : "), a$priorite_specimen[1])),
        column(6, p(strong("Délai (h) : "), a$delai_h[1]))
      ),
      hr(),
      h4("Notes / instructions"),
      div(
