  if(!dir.exists(dossier_modeles_requisition))
    dir.create(dossier_modeles_requisition,recursive=TRUE,showWarnings=FALSE)

  restaurer_modeles_pdf_depuis_db <- function() {
    con <- ouvrir_db()
    on.exit(try(DBI::dbDisconnect(con),silent=TRUE),add=TRUE)

    d <- tryCatch(
      db_query(con,"
        SELECT id,nom,fichier_pdf,pdf_base64
        FROM requisition_modeles
        WHERE actif=1
        ORDER BY id"),
      error=function(e) data.frame()
    )
    if(nrow(d)==0) return(invisible(FALSE))

    for(i in seq_len(nrow(d))) {
      b64 <- if("pdf_base64" %in% names(d) && !is.na(d$pdf_base64[i]))
        as.character(d$pdf_base64[i]) else ""
      ancien <- if(!is.na(d$fichier_pdf[i])) as.character(d$fichier_pdf[i]) else ""

      # Si le fichier existe encore, aucune reconstruction n'est nécessaire.
      if(nzchar(ancien) && file.exists(ancien)) next
      if(!nzchar(b64)) next

      nom_local <- paste0("modele_",d$id[i],"_",
        gsub("[^A-Za-z0-9_-]","_",as.character(d$nom[i])),".pdf")
      destination <- file.path(dossier_modeles_requisition,nom_local)

      ok <- tryCatch({
        brut <- jsonlite::base64_dec(b64)
        writeBin(brut,destination)
        file.exists(destination) && file.info(destination)$size > 0
      },error=function(e) FALSE)

      if(isTRUE(ok)) {
        try(db_execute(con,
          "UPDATE requisition_modeles SET fichier_pdf=? WHERE id=?",
          params=list(destination,as.integer(d$id[i]))),silent=TRUE)
      }
    }
    invisible(TRUE)
  }

  output$creation_modele_select_ui <- renderUI({
    req(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR"))
    refresh_modeles_requisition()

    try(restaurer_modeles_pdf_depuis_db(),silent=TRUE)

    con <- ouvrir_db()
    on.exit(try(DBI::dbDisconnect(con),silent=TRUE),add=TRUE)
    d <- tryCatch(
      db_query(con,"
        SELECT id,nom,fichier_pdf,pdf_base64
        FROM requisition_modeles
        WHERE actif=1
        ORDER BY nom"),
      error=function(e) {
        return(structure(data.frame(),erreur=conditionMessage(e)))
      }
    )

    if(nrow(d)==0) {
      err <- attr(d,"erreur")
      if(!is.null(err))
        return(div(class="danger-box",
          strong("Impossible de charger les modèles PDF : "),err))
      return(div(class="warning-box",
        "Aucun modèle PDF enregistré. Téléversez un formulaire PDF ci-dessus."))
    }

    disponible <- vapply(seq_len(nrow(d)),function(i) {
      chemin <- if(!is.na(d$fichier_pdf[i])) as.character(d$fichier_pdf[i]) else ""
      b64 <- if(!is.na(d$pdf_base64[i])) as.character(d$pdf_base64[i]) else ""
      (nzchar(chemin) && file.exists(chemin)) || nzchar(b64)
    },logical(1))

    lib <- paste0(d$nom,ifelse(disponible,""," — PDF à retéléverser"))
    choix <- setNames(as.character(d$id),lib)
    selectInput("creation_modele_id","Réquisition PDF à utiliser",
                choices=choix,selected=as.character(d$id[1]))
  })

