  initialiser_champs_patient_modele <- function(modele_id) {
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    existants <- db_query(con,
      "SELECT champ FROM requisition_modele_champs WHERE modele_id=?",
      params=list(modele_id))$champ
    # Default positions are intentionally neutral; admin can adjust for each form.
    defaults <- data.frame(
      champ=names(champs_patient_requisition),
      page=1L,
      x=c(.18,.38,.55,.38,.62,.72,.18,.18,.38,.55,.68,.18,.38,.58),
      y=c(.16,.16,.16,.23,.16,.16,.20,.23,.23,.23,.23,.27,.27,.27),
      taille=c(12,12,11,11,10,11,10,10,10,10,10,11,11,11),
      stringsAsFactors=FALSE
    )
    add <- defaults[!defaults$champ %in% existants,,drop=FALSE]
    if(nrow(add)>0) {
      for(i in seq_len(nrow(add))) {
        db_execute(con,"
          INSERT OR IGNORE INTO requisition_modele_champs
            (modele_id,champ,page,x,y,taille)
          VALUES (?,?,?,?,?,?)",
          params=list(modele_id,add$champ[i],add$page[i],
                      add$x[i],add$y[i],add$taille[i]))
      }
    }
  }

  observeEvent(input$creation_modele_id,{
    mid <- suppressWarnings(as.integer(input$creation_modele_id))
    if(!is.na(mid)) try(initialiser_champs_patient_modele(mid),silent=TRUE)
  },ignoreInit=FALSE)

