  observeEvent(input$mapping_ajouter,{
    mid <- suppressWarnings(as.integer(input$creation_modele_id))
    aid <- suppressWarnings(as.integer(input$mapping_analyse_id))
    if(is.na(mid) || is.na(aid)) {
      showNotification("Choisissez le modèle et l'analyse Vitalité.",type="error"); return()
    }
    code <- trimws(as.character(input$mapping_code_externe %||% ""))
    if(!nzchar(code)) {
      showNotification("Entrez le code utilisé sur la réquisition.",type="error"); return()
    }
    pg <- max(1L,suppressWarnings(as.integer(input$mapping_page %||% 1)))
    xx <- max(0,min(1,as.numeric(input$mapping_x %||% 50)/100))
    yy <- max(0,min(1,as.numeric(input$mapping_y %||% 50)/100))
    lib <- trimws(as.character(input$mapping_libelle_externe %||% ""))

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    db_execute(con,"
      INSERT INTO requisition_modele_tests
        (modele_id,analyse_id,code_externe,libelle_externe,page,x,y)
      VALUES (?,?,?,?,?,?,?)
      ON CONFLICT(modele_id,analyse_id) DO UPDATE SET
        code_externe=excluded.code_externe,
        libelle_externe=excluded.libelle_externe,
        page=excluded.page,x=excluded.x,y=excluded.y",
      params=list(mid,aid,code,lib,pg,xx,yy))
    refresh_modeles_requisition(refresh_modeles_requisition()+1L)
    showNotification(paste0("Correspondance enregistrée : ",
                             code," ↔ analyse Vitalité."),type="message")
  })

  observeEvent(input$creation_modele_ajouter,{
    req(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR"))
    f <- input$creation_modele_pdf
    nom <- trimws(as.character(input$creation_modele_nom %||% ""))
    if(is.null(f) || !nzchar(nom)) {
      showNotification("Indiquez un nom et choisissez un fichier PDF.",type="error"); return()
    }
    if(tolower(tools::file_ext(f$name))!="pdf") {
      showNotification("Le modèle doit être un fichier PDF.",type="error"); return()
    }

    nom_fichier <- paste0(
      format(Sys.time(),"%Y%m%d_%H%M%S"),"_",
      gsub("[^A-Za-z0-9_-]","_",tools::file_path_sans_ext(f$name)),".pdf")
    destination <- file.path(dossier_modeles_requisition,nom_fichier)
    ok <- file.copy(f$datapath,destination,overwrite=TRUE)
    if(!ok) {
      showNotification("Impossible de copier le PDF.",type="error"); return()
    }

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    ok_db <- tryCatch({
      pdf_base64 <- jsonlite::base64_enc(readBin(destination,"raw",n=file.info(destination)$size))
      db_execute(con,"
        INSERT INTO requisition_modeles(nom,fichier_pdf,pdf_base64,cree_par)
        VALUES (?,?,?,?)",
        params=list(nom,destination,pdf_base64,utilisateur_connecte()$id))
      TRUE
    },error=function(e) {
      showNotification(paste("Impossible d'enregistrer le modèle :",conditionMessage(e)),
                       type="error",duration=10)
      FALSE
    })
    if(ok_db) {
      nouveau_modele_id <- tryCatch(as.integer(db_query(
        con,"SELECT last_insert_rowid() AS id")$id[1]),error=function(e) NA_integer_)
      if(!is.na(nouveau_modele_id))
        try(initialiser_champs_patient_modele(nouveau_modele_id),silent=TRUE)
      refresh_modeles_requisition(refresh_modeles_requisition()+1L)
      showNotification("Modèle de réquisition ajouté.",type="message")
    }
  })

