  observeEvent(input$creation_req_attribuer,{
    req(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR"))
    try(restaurer_modeles_pdf_depuis_db(),silent=TRUE)
    pid <- suppressWarnings(as.integer(input$creation_req_patient_id))
    modele_id <- suppressWarnings(as.integer(input$creation_modele_id))
    eid <- suppressWarnings(as.integer(input$creation_req_etudiant_id))
    analyse_ids <- creation_req_selection()
    tests_manuels <- creation_req_tests_manuels()

    if(is.na(pid) || is.na(eid)) {
      showNotification("Choisissez un patient et un étudiant.",type="error"); return()
    }
    if(is.na(modele_id)) {
      showNotification("Choisissez le modèle PDF de réquisition.",type="error"); return()
    }
    con_check <- ouvrir_db()
    modele_ok <- tryCatch(
      db_query(con_check,
        "SELECT id,fichier_pdf FROM requisition_modeles WHERE id=? AND actif=1",
        params=list(modele_id)),
      error=function(e) data.frame()
    )
    try(DBI::dbDisconnect(con_check),silent=TRUE)
    if(nrow(modele_ok)!=1) {
      showNotification("Le modèle PDF sélectionné n'est plus disponible.",type="error"); return()
    }
    if(length(analyse_ids)==0) {
      showNotification("Cochez au moins une analyse.",type="error"); return()
    }

    con <- ouvrir_db(); on.exit({
      if(!is.null(con) && DBI::dbIsValid(con)) try(DBI::dbDisconnect(con),silent=TRUE)
    },add=TRUE)
    transaction_ouverte <- FALSE
    tryCatch({
      db_begin_retry(con)
      transaction_ouverte <- TRUE
      db_execute(con,"
        INSERT INTO requisition_exercices(
          patient_id,etudiant_id,attribue_par,consigne,statut,modele_id,
          adresse_postale,ville_postale,province_postale,code_postal,pays_postal,
          commentaire_requisition,commentaire_page,commentaire_x,commentaire_y,
          date_prelevement,heure_prelevement,location_prelevement)
        VALUES (?,?,?,?, 'A_FAIRE',?,?,?,?,?,?,?,?,?,?,?,?,?)",
        params=list(
          pid,eid,utilisateur_connecte()$id,norm_txt(input$creation_req_consigne),modele_id,
          if(isTRUE(input$creation_req_utiliser_adresse)) norm_txt(input$creation_req_adresse) else NA_character_,
          if(isTRUE(input$creation_req_utiliser_adresse)) norm_txt(input$creation_req_ville) else NA_character_,
          if(isTRUE(input$creation_req_utiliser_adresse)) norm_txt(input$creation_req_province) else NA_character_,
          if(isTRUE(input$creation_req_utiliser_adresse)) norm_upper(input$creation_req_code_postal) else NA_character_,
          if(isTRUE(input$creation_req_utiliser_adresse)) norm_txt(input$creation_req_pays) else NA_character_,
          norm_txt(input$creation_req_commentaire),
          1L,0.12,0.30,
          as.character(input$creation_req_date_prelevement %||% ""),
          norm_txt(input$creation_req_heure_prelevement),
          norm_txt(input$creation_req_location_prelevement)
        ))
      exid <- db_query(con,"SELECT last_insert_rowid() AS id")$id[1]

      ordre <- 0L
      for(aid in analyse_ids) {
        ordre <- ordre+1L
        db_execute(con,"
          INSERT OR IGNORE INTO requisition_exercice_tests(exercice_id,analyse_id,ordre_affichage)
          VALUES (?,?,?)",
          params=list(exid,as.integer(aid),ordre))
      }
      if(nrow(tests_manuels)>0) {
        for(i in seq_len(nrow(tests_manuels))) {
          ordre <- ordre+1L
          db_execute(con,"
            INSERT INTO requisition_exercice_tests_manuels
              (exercice_id,mnemonique,nom,ordre_affichage)
            VALUES (?,?,?,?)",
            params=list(
              exid,
              tests_manuels$mnemonique[i],
              tests_manuels$nom[i],
              ordre
            ))
        }
      }

      db_commit_retry(con)
      transaction_ouverte <- FALSE
      # L'attribution est terminée ici. Aucun traitement PDF n'est exécuté
      # dans cette transaction afin d'éviter de faire tomber la session Shiny.
      # Ne PAS déclencher l'aperçu/génération PDF ici.
      # L'attribution doit rester indépendante et légère.
      derniere_creation_requisition(as.integer(exid))
      creation_req_pdf_positions(NULL)
      creation_req_pdf_page(1L)
      refresh_exercices_requisition(refresh_exercices_requisition()+1L)
      creation_req_tests_manuels(
        data.frame(mnemonique=character(),nom=character(),
                   stringsAsFactors=FALSE)
      )
      creation_req_tests_recherche_ajoutes(integer(0))
      updateCheckboxGroupInput(session,"creation_req_tests_routine",selected=character(0))
      output$creation_req_message <- renderUI(
        div(class="success-box",
            strong("Réquisition pédagogique créée et attribuée. "),
            paste(length(analyse_ids)+nrow(tests_manuels),
                "analyse(s) attendue(s)."))
      )
    },error=function(e){
      if(isTRUE(transaction_ouverte) && !is.null(con) && DBI::dbIsValid(con))
        try(DBI::dbRollback(con),silent=TRUE)
      output$creation_req_message <- renderUI(
        div(class="danger-box",
            strong("Attribution impossible : "),
            conditionMessage(e)))
      showNotification(
        paste("Attribution impossible :",conditionMessage(e)),
        type="error",duration=12
      )
    })
  })

  # ----------------------------------------------------------
  # PDF DE REQUISITION : FORMULAIRE HORIZON ORIGINAL + CALQUES
  # ----------------------------------------------------------
  charger_fonds_horizon <- function() {
    cache <- horizon_req_backgrounds()
    if(!is.null(cache)) return(cache)
    if(!requireNamespace("png",quietly=TRUE))
      stop("Le package R 'png' est requis pour générer la réquisition originale.")

    lire_b64_png <- function(txt) {
      brut <- jsonlite::base64_dec(txt)
      f <- tempfile(fileext=".png")
      writeBin(brut,f)
      on.exit(unlink(f),add=TRUE)
      png::readPNG(f)
    }
    cache <- list(
      p1=lire_b64_png(HORIZON_REQUISITION_PAGE1_B64),
      p2=lire_b64_png(HORIZON_REQUISITION_PAGE2_B64)
    )
    horizon_req_backgrounds(cache)
    cache
  }

  positions_requisition_defaut <- function(codes) {
    codes <- unique(toupper(as.character(codes)))

    # Positions des renseignements du patient sur la page 1.
    pos <- data.frame(
      id=c("PAT_NOM","PAT_PRENOM","PAT_MEDICARE","PAT_DOB","PAT_DOSSIER"),
      libelle=c("Patient — Nom","Patient — Prénom","Patient — Medicare",
                "Patient — Date de naissance","Patient — Numéro de dossier"),
      page=1L,
      x=c(.270,.270,.270,.270,.585),
      y=c(.838,.811,.784,.733,.647),
      type="texte",
      stringsAsFactors=FALSE
    )

    ajouter_groupe <- function(cat,page,x,y0,pas) {
      d <- horizon_tests[horizon_tests$categorie==cat,,drop=FALSE]
      if(nrow(d)==0) return(NULL)
      d <- d[toupper(d$code) %in% codes,,drop=FALSE]
      if(nrow(d)==0) return(NULL)

      # Garder la position de la ligne originale, même si seuls certains tests sont cochés.
      allcat <- horizon_tests[horizon_tests$categorie==cat,,drop=FALSE]
      rang <- match(toupper(d$code),toupper(allcat$code))
      data.frame(
        id=paste0("TEST_",toupper(d$code)),
        libelle=paste0("Test — ",d$nom," [",toupper(d$code),"]"),
        page=as.integer(page),
        x=rep(x,nrow(d)),
        y=y0-(rang-1L)*pas,
        type="case",
        stringsAsFactors=FALSE
      )
    }

    # Page 1 : emplacements des cases du formulaire original.
    groupes <- list(
      ajouter_groupe("Hématologie — Routine",1,.091,.487,.0181),
      ajouter_groupe("Hématologie — Spécial / immunologie / hémostase",1,.384,.487,.0181),
      ajouter_groupe("Banque de sang",1,.091,.176,.0181),
      # Page 2.
      ajouter_groupe("Chimie — Routine",2,.111,.825,.01755),
      ajouter_groupe("Chimie — Hormones",2,.383,.825,.01755),
      ajouter_groupe("Chimie — Médicaments",2,.383,.487,.01755),
      ajouter_groupe("Chimie — Spécial / gaz sanguins",2,.111,.174,.0273)
    )
    groupes <- Filter(Negate(is.null),groupes)
    if(length(groupes)>0) pos <- rbind(pos,do.call(rbind,groupes))
    rownames(pos) <- NULL
    pos
  }

  valeurs_requisition_pdf <- function(exid) {
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    h <- db_query(con,"
      SELECT re.id,re.consigne,re.date_attribution,
             p.numero_dossier,p.medicare,p.nom,p.prenom,p.date_naissance,p.sexe
      FROM requisition_exercices re
      JOIN patients p ON p.id=re.patient_id
      WHERE re.id=?",params=list(exid))
    tt <- db_query(con,"
      SELECT UPPER(a.mnemonique) AS code
      FROM requisition_exercice_tests ret
      JOIN analyses a ON a.id=ret.analyse_id
      WHERE ret.exercice_id=?
      ORDER BY ret.ordre_affichage",params=list(exid))
    list(h=h,codes=unique(toupper(tt$code)))
  }

  output$creation_req_pdf_zone <- renderUI({
    req(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR"))
    exid <- derniere_creation_requisition()
    if(is.null(exid)) return(NULL)

    pos <- creation_req_pdf_positions()
    if(is.null(pos)) {
      pos <- tryCatch({
        z <- valeurs_requisition_pdf(exid)
        positions_requisition_defaut(z$codes)
      },error=function(e) NULL)
      if(is.null(pos))
        return(div(class="warning-box",
          "Réquisition attribuée avec succès. L'aperçu PDF n'a pas pu être préparé; ",
          "l'attribution et les tests attendus sont néanmoins enregistrés."))
      creation_req_pdf_positions(pos)
    }

    choix <- setNames(pos$id,pos$libelle)
    tagList(
      div(
        class="success-box",
        strong("Réquisition Horizon originale prête. "),
        "Vous pouvez corriger manuellement la position des écritures et des X avant le téléchargement."
      ),
      fluidRow(
        column(3,
          selectInput("creation_pdf_page","Page à afficher",
                      choices=c("Page 1"="1","Page 2"="2"),
                      selected=as.character(creation_req_pdf_page()))
        ),
        column(6,
          selectizeInput("creation_pdf_element","Élément à déplacer",
                         choices=choix,
                         options=list(placeholder="Choisir une écriture ou un test coché"))
        ),
        column(3,br(),
          actionButton("creation_pdf_reset","Réinitialiser les positions",class="btn-warning")
        )
      ),
      div(class="info-box",
          strong("Ajustement manuel : "),
          "choisissez l'élément à déplacer, puis cliquez directement sur la réquisition à l'endroit exact où il doit être imprimé."),
      uiOutput("creation_req_pdf_preview_html"),
      if(requireNamespace("magick",quietly=TRUE))
        downloadButton("creation_req_pdf_download",
                       "Télécharger le PDF final",
                       class="btn-primary")
