  observeEvent(input$creation_pdf_page,{
    creation_req_pdf_page(as.integer(input$creation_pdf_page))
  },ignoreInit=TRUE)

  observeEvent(input$creation_req_pdf_click_html,{
    req(input$creation_pdf_element)
    cl <- input$creation_req_pdf_click_html
    if(is.null(cl$x) || is.null(cl$y)) return()
    pos <- creation_req_pdf_positions()
    if(is.null(pos)) return()
    i <- match(input$creation_pdf_element,pos$id)
    if(is.na(i)) return()

    pos$x[i] <- max(0,min(1,as.numeric(cl$x)))
    pos$y[i] <- max(0,min(1,as.numeric(cl$y)))
    pos$page[i] <- as.integer(creation_req_pdf_page())
    creation_req_pdf_positions(pos)
    showNotification("Position modifiée.",type="message",duration=1.5)
  },ignoreInit=TRUE)

  observeEvent(input$creation_pdf_reset,{
    exid <- derniere_creation_requisition()
    req(!is.null(exid))
    z <- valeurs_requisition_pdf(exid)
    creation_req_pdf_positions(positions_requisition_defaut(z$codes))
    showNotification("Positions originales réinitialisées.",type="message")
  })

  output$creation_req_pdf_preview_html <- renderUI({
    exid <- derniere_creation_requisition()
    if(is.null(exid))
      return(div(class="warning-box","Aucune réquisition pédagogique sélectionnée."))

    pos <- creation_req_pdf_positions()
    if(is.null(pos))
      return(div(class="warning-box","Les positions du formulaire ne sont pas chargées."))

    page <- as.integer(creation_req_pdf_page())
    bg64 <- if(page==1L) HORIZON_REQUISITION_PAGE1_B64 else HORIZON_REQUISITION_PAGE2_B64

    z <- valeurs_requisition_pdf(exid)
    h <- z$h
    if(nrow(h)!=1)
      return(div(class="danger-box","Patient introuvable pour cette réquisition."))

    scalar <- function(x) {
      if(length(x)==0 || is.null(x) || is.na(x[1])) "" else as.character(x[1])
    }
    valeur <- function(id) {
      if(id=="PAT_NOM") return(scalar(h$nom))
      if(id=="PAT_PRENOM") return(scalar(h$prenom))
      if(id=="PAT_MEDICARE") return(scalar(h$medicare))
      if(id=="PAT_DOB") return(scalar(h$date_naissance))
      if(id=="PAT_DOSSIER") return(scalar(h$numero_dossier))
      if(startsWith(id,"TEST_")) return("X")
      ""
    }

    d <- pos[pos$page==page,,drop=FALSE]
    overlays <- lapply(seq_len(nrow(d)),function(i) {
      txt <- valeur(d$id[i])
      if(!nzchar(txt)) return(NULL)
      selected <- !is.null(input$creation_pdf_element) &&
                  identical(as.character(input$creation_pdf_element),as.character(d$id[i]))
      # Stored y uses PDF bottom-origin. CSS uses top-origin.
      top <- (1-as.numeric(d$y[i]))*100
      left <- as.numeric(d$x[i])*100
      style <- paste0(
        "position:absolute;left:",sprintf("%.4f",left),"%;top:",sprintf("%.4f",top),"%;",
        "transform:translate(",if(d$type[i]=="case") "-50%" else "0"," ,-50%);",
        "font-family:Arial,sans-serif;",
        "font-size:",if(d$type[i]=="case") "15px" else "12px",";",
        "font-weight:",if(d$type[i]=="case") "700" else "500",";",
        "color:#000;white-space:nowrap;",
        if(selected) "outline:2px solid #e67e22;background:rgba(255,255,255,.55);" else ""
      )
      tags$div(style=style,txt)
    })

    tags$div(
      style="max-width:900px;margin:0 auto 18px auto;",
      tags$div(
        id="creation_req_pdf_canvas",
        style=paste0(
          "position:relative;width:100%;aspect-ratio:8.5/11;",
          "background-image:url('data:image/png;base64,",bg64,"');",
          "background-size:100% 100%;background-repeat:no-repeat;",
          "border:1px solid #9aa7b4;box-shadow:0 2px 8px rgba(0,0,0,.15);",
          "cursor:crosshair;overflow:hidden;"
        ),
        overlays
      ),
      tags$script(HTML("
        (function(){
          var el=document.getElementById('creation_req_pdf_canvas');
          if(!el) return;
          el.onclick=function(ev){
            var r=el.getBoundingClientRect();
            var x=(ev.clientX-r.left)/r.width;
            var y=1-((ev.clientY-r.top)/r.height);
            Shiny.setInputValue(
              'creation_req_pdf_click_html',
              {x:x,y:y,nonce:Date.now()},
              {priority:'event'}
            );
          };
        })();
      "))
    )
  })

  output$creation_req_pdf_download <- downloadHandler(
    filename=function() {
      exid <- derniere_creation_requisition()
      paste0("REQUISITION_",exid,"_",format(Sys.Date(),"%Y%m%d"),".pdf")
    },
    contentType="application/pdf",
    content=function(file) {
      exid <- derniere_creation_requisition()
      if(is.null(exid)) stop("Aucune réquisition sélectionnée.")
      if(!requireNamespace("magick",quietly=TRUE))
        stop("Installez le package R 'magick' pour générer le PDF final.")

      con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
      d <- db_query(con,"
        SELECT re.modele_id,rm.fichier_pdf,
               p.nom,p.prenom,p.medicare,p.numero_dossier,p.date_naissance
        FROM requisition_exercices re
        JOIN patients p ON p.id=re.patient_id
        JOIN requisition_modeles rm ON rm.id=re.modele_id
        WHERE re.id=?",params=list(exid))
      if(nrow(d)!=1 || !file.exists(d$fichier_pdf[1]))
        stop("Le PDF original de cette réquisition est introuvable.")

      # Le PDF original est rendu page par page; aucune reconstruction du formulaire.
      pages <- magick::image_read_pdf(d$fichier_pdf[1],density=180)
      pos <- creation_req_pdf_positions()
      if(is.null(pos)) {
        z <- valeurs_requisition_pdf(exid)
        pos <- positions_requisition_defaut(z$codes)
      }

      scalar <- function(x) if(length(x)==0 || is.na(x[1])) "" else as.character(x[1])
      valeur <- function(id) {
        if(id=="PAT_NOM") return(scalar(d$nom))
        if(id=="PAT_PRENOM") return(scalar(d$prenom))
        if(id=="PAT_MEDICARE") return(scalar(d$medicare))
        if(id=="PAT_DOB") return(scalar(d$date_naissance))
        if(id=="PAT_DOSSIER") return(scalar(d$numero_dossier))
        if(startsWith(id,"TEST_")) return("X")
        ""
      }

      n <- length(pages)
      for(pg in seq_len(n)) {
        info <- magick::image_info(pages[pg])
        w <- info$width[1]; h <- info$height[1]
        pp <- pos[pos$page==pg,,drop=FALSE]
        if(nrow(pp)>0) {
          for(i in seq_len(nrow(pp))) {
            txt <- valeur(pp$id[i])
            if(!nzchar(txt)) next
            xx <- round(as.numeric(pp$x[i])*w)
            yy <- round((1-as.numeric(pp$y[i]))*h)
            pages[pg] <- magick::image_annotate(
              pages[pg],txt,
              size=if(pp$type[i]=="case") 24 else 18,
              weight=if(pp$type[i]=="case") 700 else 400,
              color="black",
              location=paste0("+",xx,"+",yy),
              gravity="northwest"
            )
          }
        }
      }
      magick::image_write(pages,path=file,format="pdf")
    }
  )

