  output$creation_pdf_analyses_ui <- renderUI({
    exid <- suppressWarnings(as.integer(input$creation_pdf_exercice_id))
    if(is.na(exid)) return(NULL)

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    a <- tryCatch(db_query(con,"
      SELECT a.mnemonique,a.nom,a.departement,
             COALESCE(rmt.code_externe,a.mnemonique) AS code_externe
      FROM requisition_exercice_tests ret
      JOIN requisition_exercices re ON re.id=ret.exercice_id
      JOIN analyses a ON a.id=ret.analyse_id
      LEFT JOIN requisition_modele_tests rmt
        ON rmt.modele_id=re.modele_id AND rmt.analyse_id=ret.analyse_id
      WHERE ret.exercice_id=?
      ORDER BY ret.ordre_affichage",
      params=list(exid)),error=function(e)data.frame())

    m <- tryCatch(db_query(con,"
      SELECT mnemonique,nom
      FROM requisition_exercice_tests_manuels
      WHERE exercice_id=?
      ORDER BY ordre_affichage",
      params=list(exid)),error=function(e)data.frame())

    total <- nrow(a)+nrow(m)
    if(total==0)
      return(div(class="warning-box","Aucune analyse enregistrée."))

    badges <- list()
    if(nrow(a)>0) {
      badges <- c(badges,lapply(seq_len(nrow(a)),function(i)
        tags$span(
          title=as.character(a$nom[i]),
          style="display:inline-block;padding:5px 9px;border:1px solid #b7cfd1;border-radius:14px;background:white;font-weight:600;",
          paste0(a$mnemonique[i],
                 ifelse(is.na(a$code_externe[i]) ||
                          a$code_externe[i]==a$mnemonique[i],"",
                        paste0(" → Horizon ",a$code_externe[i])))
        )))
    }
    if(nrow(m)>0) {
      badges <- c(badges,lapply(seq_len(nrow(m)),function(i)
        tags$span(
          title=as.character(m$nom[i]),
          style="display:inline-block;padding:5px 9px;border:1px dashed #8a8a8a;border-radius:14px;background:#fffaf0;font-weight:600;",
          paste0(m$mnemonique[i]," [spécifique]")
        )))
    }

    tags$div(
      style="margin:10px 0 14px 0;padding:12px 14px;border:1px solid #b9dfe2;border-radius:8px;background:#f5fbfc;",
      tags$div(style="font-weight:700;margin-bottom:7px;",
               paste0("Analyses demandées (",total,")")),
      tags$div(style="display:flex;flex-wrap:wrap;gap:7px;",badges)
    )
  })

