  output$creation_pdf_preview_ui <- renderUI({
    exid <- pdf_exercice_selectionne()
    if(is.null(exid)) return(NULL)
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)

    d <- tryCatch(db_query(con,"
      SELECT rm.fichier_pdf,re.modele_id,
             p.nom,p.prenom,p.medicare,p.numero_dossier,p.date_naissance,p.sexe,
             COALESCE(NULLIF(re.adresse_postale,''),p.adresse) AS adresse_aff,
             COALESCE(NULLIF(re.ville_postale,''),p.ville) AS ville_aff,
             COALESCE(NULLIF(re.province_postale,''),p.province) AS province_aff,
             COALESCE(NULLIF(re.code_postal,''),p.code_postal) AS code_postal_aff,
             COALESCE(NULLIF(re.pays_postal,''),p.pays) AS pays_aff,
             re.commentaire_requisition,re.commentaire_page,re.commentaire_x,re.commentaire_y,
             re.date_prelevement,re.heure_prelevement,re.location_prelevement
      FROM requisition_exercices re
      JOIN requisition_modeles rm ON rm.id=re.modele_id
      JOIN patients p ON p.id=re.patient_id
      WHERE re.id=?",params=list(exid)),error=function(e)data.frame())
    if(nrow(d)!=1 || !file.exists(d$fichier_pdf[1]))
      return(div(class="danger-box","PDF original introuvable."))

    champs <- tryCatch(db_query(con,"
      SELECT id,champ,page,x,y,taille FROM requisition_modele_champs
      WHERE modele_id=?",params=list(d$modele_id[1])),error=function(e)data.frame())

    tests <- tryCatch(db_query(con,"
      SELECT a.id AS analyse_id,a.mnemonique,
             COALESCE(rmt.code_externe,a.mnemonique) AS code_externe,
             rmt.id AS mapping_id,rmt.page,rmt.x,rmt.y
      FROM requisition_exercice_tests ret
      JOIN analyses a ON a.id=ret.analyse_id
      LEFT JOIN requisition_modele_tests rmt
        ON rmt.modele_id=? AND rmt.analyse_id=ret.analyse_id
      WHERE ret.exercice_id=? ORDER BY ret.ordre_affichage",
      params=list(d$modele_id[1],exid)),error=function(e)data.frame())

    ann <- tryCatch(db_query(con,"
      SELECT id,texte,page,x,y,taille FROM requisition_exercice_annotations
      WHERE exercice_id=? ORDER BY id",params=list(exid)),error=function(e)data.frame())

    val <- function(ch) {
      z <- switch(ch,NOM=d$nom[1],PRENOM=d$prenom[1],MEDICARE=d$medicare[1],
        DATE_NAISSANCE=d$date_naissance[1],SEXE=d$sexe[1],DOSSIER=d$numero_dossier[1],
        ADRESSE=d$adresse_aff[1],VILLE=d$ville_aff[1],PROVINCE=d$province_aff[1],
        CODE_POSTAL=d$code_postal_aff[1],PAYS=d$pays_aff[1],
        DATE_PRELEVEMENT=d$date_prelevement[1],
        HEURE_PRELEVEMENT=d$heure_prelevement[1],
        LOCATION_PRELEVEMENT=d$location_prelevement[1],"")
      if(length(z)==0 || is.na(z)) "" else as.character(z)
    }

    ov <- list()
    if(nrow(champs)>0) for(i in seq_len(nrow(champs))) {
      txt <- val(champs$champ[i]); if(!nzchar(txt)) next
      pg <- suppressWarnings(as.integer(champs$page[i])); if(is.na(pg)||pg<1) pg<-1L
      ov[[length(ov)+1]] <- tags$div(
        class="req-live-overlay",`data-kind`="patient",`data-id`=as.character(champs$id[i]),
        `data-key`=champs$champ[i],`data-page`=as.character(pg),
        style=paste0("position:absolute;left:",100*champs$x[i],"%;top:",100*champs$y[i],
          "%;font-size:",max(16L,as.integer(champs$taille[i])),"px;font-weight:700;color:#000;",
          "padding:2px 4px;border:2px dashed #0b8793;cursor:move;z-index:20;",
          "background:rgba(255,255,255,.25);user-select:none;"),txt)
    }
    if(nrow(tests)>0) for(i in seq_len(nrow(tests))) {
      if(is.na(tests$mapping_id[i])||is.na(tests$x[i])||is.na(tests$y[i])) next
      pg<-suppressWarnings(as.integer(tests$page[i])); if(is.na(pg)||pg<1) pg<-1L
      ov[[length(ov)+1]] <- tags$div(
        class="req-live-overlay",`data-kind`="test",`data-id`=as.character(tests$mapping_id[i]),
        `data-key`=tests$code_externe[i],`data-page`=as.character(pg),
        style=paste0("position:absolute;left:",100*tests$x[i],"%;top:",100*tests$y[i],
          "%;font-size:21px;font-weight:900;color:#000;cursor:move;z-index:21;user-select:none;"),"X")
    }
    comm<-if(is.na(d$commentaire_requisition[1])) "" else trimws(as.character(d$commentaire_requisition[1]))
    if(nzchar(comm)){
      pg<-suppressWarnings(as.integer(d$commentaire_page[1]));if(is.na(pg)||pg<1)pg<-1L
      cx<-ifelse(is.na(d$commentaire_x[1]),.12,d$commentaire_x[1])
      cy<-ifelse(is.na(d$commentaire_y[1]),.30,d$commentaire_y[1])
      ov[[length(ov)+1]]<-tags$div(
        class="req-live-overlay",`data-kind`="comment",`data-id`=as.character(exid),
        `data-key`="COMMENTAIRE",`data-page`=as.character(pg),
        style=paste0("position:absolute;left:",100*cx,"%;top:",100*cy,
          "%;font-size:15px;font-weight:600;background:rgba(255,255,210,.75);",
          "padding:3px 5px;border:2px dashed #b58a00;cursor:move;z-index:22;"),comm)
    }
    if(nrow(ann)>0) for(i in seq_len(nrow(ann))){
      pg<-suppressWarnings(as.integer(ann$page[i]));if(is.na(pg)||pg<1)pg<-1L
      ov[[length(ov)+1]]<-tags$div(
        class="req-live-overlay",`data-kind`="free",`data-id`=as.character(ann$id[i]),
        `data-key`=paste0("TEXTE_",ann$id[i]),`data-page`=as.character(pg),
        style=paste0("position:absolute;left:",100*ann$x[i],"%;top:",100*ann$y[i],
          "%;font-size:",max(14L,as.integer(ann$taille[i])),"px;font-weight:700;color:#000;",
          "background:rgba(230,245,255,.65);padding:2px 4px;border:2px dashed #356aa0;",
          "cursor:move;z-index:23;user-select:none;"),as.character(ann$texte[i]))
    }

    src<-paste0("requisition-pdf/",utils::URLencode(basename(d$fichier_pdf[1]),reserved=TRUE))
    tagList(
      div(style="margin:12px 0;padding:9px 11px;background:#fff8e5;border:1px solid #efcf72;border-radius:7px;",
          strong("Édition des 2 pages : "),
          "les renseignements du patient sont affichés plus gros. Les éléments peuvent être déplacés sur leur page."),
      div(id="req_pdf_pages",`data-pdf-url`=src,style="width:100%;"),
      div(id="req_overlay_bank",style="display:none;",ov),
      div(
        style="margin-top:12px;padding:10px 12px;background:#eef7f8;border:1px solid #b9d9dd;border-radius:8px;",
        strong("Impression : "),
        "utilisez le bouton « Télécharger / Imprimer le PDF généré » sous l'aperçu. ",
        "Le PDF s'ouvrira/téléchargera comme un vrai document PDF, sans fenêtre about:blank."
      ),
      tags$script(HTML("
setTimeout(async function(){
 var host=document.getElementById('req_pdf_pages'), bank=document.getElementById('req_overlay_bank');
 if(!host||!bank||!window.pdfjsLib)return;
 host.innerHTML='';
 var pdf=await pdfjsLib.getDocument(host.dataset.pdfUrl).promise;
 for(var n=1;n<=pdf.numPages;n++){
   var page=await pdf.getPage(n),base=page.getViewport({scale:1}),scale=Math.min(900/base.width,1.7);
   var vp=page.getViewport({scale:scale});
   var wrap=document.createElement('div');wrap.className='req-pdf-page-wrap';wrap.dataset.page=n;
   wrap.style.cssText='position:relative;width:100%;max-width:'+vp.width+'px;margin:38px auto 30px;background:#fff;box-shadow:0 1px 5px rgba(0,0,0,.2)';
   var lab=document.createElement('div');lab.textContent='Page '+n+' / '+pdf.numPages;
   lab.style.cssText='position:absolute;left:0;top:-30px;padding:4px 9px;font-weight:700;background:#eef4f5;border-radius:5px;z-index:5;';
   wrap.appendChild(lab);
   var c=document.createElement('canvas');c.className='req-pdf-page-canvas';c.width=vp.width;c.height=vp.height;c.style.cssText='display:block;width:100%;height:auto';wrap.appendChild(c);host.appendChild(wrap);
   await page.render({canvasContext:c.getContext('2d'),viewport:vp}).promise;
   Array.from(bank.querySelectorAll('.req-live-overlay[data-page=\"'+n+'\"]')).forEach(function(el){el.style.display='block';wrap.appendChild(el);});
 }
 if(window.initReqMultiDrag)window.initReqMultiDrag();
},250);
      "))
    )
  })

