  observeEvent(input$req_pdf_place_test,{
    z <- input$req_pdf_place_test
    aid <- suppressWarnings(as.integer(z$analyse_id))
    exid <- suppressWarnings(as.integer(z$exercice_id))
    xx <- suppressWarnings(as.numeric(z$x)); yy <- suppressWarnings(as.numeric(z$y))
    pg <- suppressWarnings(as.integer(z$page)); if(is.na(pg)||pg<1) pg<-1L
    if(any(is.na(c(aid,exid,xx,yy)))) return()

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    q <- db_query(con,"
      SELECT re.modele_id,a.mnemonique
      FROM requisition_exercices re CROSS JOIN analyses a
      WHERE re.id=? AND a.id=?",params=list(exid,aid))
    if(nrow(q)!=1) return()

    db_execute(con,"
      INSERT INTO requisition_modele_tests
        (modele_id,analyse_id,code_externe,libelle_externe,page,x,y)
      VALUES (?,?,?,NULL,?,?,?)
      ON CONFLICT(modele_id,analyse_id) DO UPDATE SET
        page=excluded.page,x=excluded.x,y=excluded.y",
      params=list(q$modele_id[1],aid,q$mnemonique[1],pg,xx,yy))

    showNotification(paste0("X placé pour ",q$mnemonique[1]),type="message")
    old <- pdf_exercice_selectionne()
    pdf_exercice_selectionne(NULL)
    later::later(function() pdf_exercice_selectionne(old),.05)
  })

  observeEvent(input$creation_pdf_tests_save,{
    exid <- pdf_exercice_selectionne()
    if(is.null(exid)) return()
    ids <- suppressWarnings(as.integer(input$creation_pdf_tests_checked %||% character(0)))
    ids <- ids[!is.na(ids)]

    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    tryCatch({
      db_execute(con,"BEGIN IMMEDIATE")
      db_execute(con,
        "DELETE FROM requisition_exercice_tests WHERE exercice_id=?",
        params=list(exid))
      if(length(ids)>0) {
        for(i in seq_along(ids))
          db_execute(con,"
            INSERT INTO requisition_exercice_tests
              (exercice_id,analyse_id,ordre_affichage)
            VALUES (?,?,?)",
            params=list(exid,ids[i],i))
      }
      db_execute(con,"COMMIT")
      showNotification("Cases de la réquisition enregistrées.",type="message")
      # force preview regeneration
      old <- pdf_exercice_selectionne()
      pdf_exercice_selectionne(NULL)
      later::later(function() pdf_exercice_selectionne(old),.05)
    },error=function(e){
      try(db_execute(con,"ROLLBACK"),silent=TRUE)
      showNotification(paste("Erreur :",conditionMessage(e)),type="error")
    })
  })

