    else if(kind=="test")
      db_execute(con,"UPDATE requisition_modele_tests SET page=?,x=?,y=? WHERE id=?",params=list(pg,xx,yy,rid))
    else if(kind=="comment")
      db_execute(con,"UPDATE requisition_exercices SET commentaire_page=?,commentaire_x=?,commentaire_y=? WHERE id=?",params=list(pg,xx,yy,rid))
    else if(kind=="free")
      db_execute(con,"UPDATE requisition_exercice_annotations SET page=?,x=?,y=? WHERE id=?",params=list(pg,xx,yy,rid))
  },ignoreInit=TRUE)

