      ORDER BY nom,prenom")

    choix_p <- if(nrow(pts)>0) setNames(as.character(pts$id),
      paste0(pts$nom,", ",pts$prenom," — ",COALESCE_R <- ifelse(is.na(pts$numero_dossier),"—",pts$numero_dossier))) else character(0)
    choix_e <- if(nrow(ets)>0) setNames(as.character(ets$id),
      paste0(ets$prenom," ",ets$nom," — ",ets$identifiant)) else character(0)

    tagList(
      fluidRow(
        column(5,selectizeInput("req_admin_patient_id","Patient",choices=choix_p,
                                options=list(placeholder="Choisir un patient"))),
        column(5,selectizeInput("req_admin_etudiant_id","Étudiant",choices=choix_e,
                                options=list(placeholder="Choisir un étudiant"))),
        column(2,br(),actionButton("req_admin_attribuer","Attribuer",class="btn-primary"))
      ),
      textAreaInput("req_admin_consigne","Consigne / note pour l'étudiant",rows=2,
                    placeholder="Ex. Entrer les analyses indiquées sur la requête remise en classe."),
      DT::DTOutput("req_admin_attributions_table")
    )
  })

  output$req_admin_attributions_table <- DT::renderDT({
    req(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR"))
    refresh_exercices_requisition()
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    d <- db_query(con,"
      SELECT re.id AS ID,
             p.numero_dossier AS Dossier,
             p.nom || ', ' || p.prenom AS Patient,
             u.prenom || ' ' || u.nom AS Étudiant,
             re.consigne AS Consigne,
             re.statut AS Statut,
             re.date_attribution AS Attribution
      FROM requisition_exercices re
      JOIN patients p ON p.id=re.patient_id
      JOIN utilisateurs u ON u.id=re.etudiant_id
      ORDER BY re.id DESC LIMIT 100")
    DT::datatable(d,rownames=FALSE,selection="none",
                  options=list(pageLength=8,scrollX=TRUE))
  })

  observeEvent(input$req_admin_attribuer,{
    req(toupper(utilisateur_connecte()$role) %in% c("ADMIN","SUPERUTILISATEUR"))
    pid <- suppressWarnings(as.integer(input$req_admin_patient_id))
    eid <- suppressWarnings(as.integer(input$req_admin_etudiant_id))
    if(is.na(pid) || is.na(eid)) {
      showNotification("Choisissez un patient et un étudiant.",type="error"); return()
    }
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    tryCatch({
      db_execute_retry(con,"
        INSERT INTO requisition_exercices(patient_id,etudiant_id,attribue_par,consigne,statut)
        VALUES (?,?,?,?, 'A_FAIRE')",
        params=list(pid,eid,utilisateur_connecte()$id,norm_txt(input$req_admin_consigne)))
      refresh_exercices_requisition(refresh_exercices_requisition()+1L)
      showNotification("Réquisition attribuée à l'étudiant.",type="message")
    },error=function(e)
      showNotification(paste("Attribution impossible :",conditionMessage(e)),type="error",duration=10))
  })

  output$req_etudiant_attribution_ui <- renderUI({
    req(toupper(utilisateur_connecte()$role)=="ETUDIANT")
    refresh_exercices_requisition()
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    d <- db_query(con,"
      SELECT re.id,p.nom,p.prenom,p.numero_dossier,re.consigne,re.date_attribution
      FROM requisition_exercices re
      JOIN patients p ON p.id=re.patient_id
      WHERE re.etudiant_id=? AND re.statut IN ('A_FAIRE','EN_COURS')
      ORDER BY CASE re.statut WHEN 'EN_COURS' THEN 0 ELSE 1 END,re.date_attribution",
      params=list(utilisateur_connecte()$id))
    if(nrow(d)==0)
      return(div(class="info-box","Aucune réquisition ne vous est actuellement attribuée."))

    choix <- setNames(as.character(d$id),
      paste0(d$nom,", ",d$prenom," — Dossier ",d$numero_dossier,
             " — attribuée ",d$date_attribution))
    tagList(
      selectInput("req_etudiant_exercice_id","Mes réquisitions",choices=choix),
      actionButton("req_etudiant_ouvrir","Ouvrir la réquisition",class="btn-primary"),
      uiOutput("req_etudiant_consigne_ui")
    )
  })

  output$req_etudiant_consigne_ui <- renderUI({
    ex <- exercice_requisition_actif()
    if(is.null(ex) || nrow(ex)!=1) return(NULL)
    if(is.na(ex$consigne[1]) || !nzchar(ex$consigne[1])) return(NULL)
    div(class="info-box",strong("Consigne : "),ex$consigne[1])
  })

  observeEvent(input$req_etudiant_ouvrir,{
    req(toupper(utilisateur_connecte()$role)=="ETUDIANT")
    exid <- suppressWarnings(as.integer(input$req_etudiant_exercice_id))
    req(!is.na(exid))
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    ex <- db_query(con,"
      SELECT re.*,p.*
      FROM requisition_exercices re
      JOIN patients p ON p.id=re.patient_id
      WHERE re.id=? AND re.etudiant_id=? AND re.statut IN ('A_FAIRE','EN_COURS')",
      params=list(exid,utilisateur_connecte()$id))
    if(nrow(ex)!=1) {
      showNotification("Cette réquisition n'est pas disponible.",type="error"); return()
    }
    exercice_requisition_actif(ex)

    # Recharger le patient imposé dans le formulaire.
    p <- db_query(con,"SELECT * FROM patients WHERE id=?",
                         params=list(ex$patient_id[1]))
    patient_requisition(p)
    val <- function(x,def="") if(length(x)==0 || is.na(x[1])) def else as.character(x[1])
    updateTextInput(session,"req_numero_dossier",value=val(p$numero_dossier))
    updateTextInput(session,"req_medicare",value=val(p$medicare))
    updateTextInput(session,"req_nom",value=val(p$nom))
    updateTextInput(session,"req_prenom",value=val(p$prenom))
    if(!is.na(p$date_naissance[1]) && nzchar(as.character(p$date_naissance[1])))
      updateDateInput(session,"req_date_naissance",value=as.Date(p$date_naissance[1]))
    updateSelectInput(session,"req_sexe",selected=val(p$sexe,"U"))
    updateTextInput(session,"req_adresse",value=val(p$adresse))
    updateTextInput(session,"req_ville",value=val(p$ville))
    updateTextInput(session,"req_province",value=val(p$province))
    updateTextInput(session,"req_code_postal",value=val(p$code_postal))
    updateTextInput(session,"req_pays",value=val(p$pays,"Canada"))

    db_execute_retry(con,"
      UPDATE requisition_exercices
      SET statut='EN_COURS',date_ouverture=COALESCE(date_ouverture,CURRENT_TIMESTAMP)
      WHERE id=? AND etudiant_id=?",
      params=list(exid,utilisateur_connecte()$id))
    order_actuel(order_vide())
    refresh_exercices_requisition(refresh_exercices_requisition()+1L)
    showNotification("Réquisition ouverte. Entrez maintenant les mnémoniques.",type="message")
  },ignoreInit=TRUE)

  observeEvent(input$req_rechercher_patient, {
    dossier <- norm_txt(input$req_numero_dossier)
    medicare <- norm_txt(input$req_medicare)

    if ((!nzchar(dossier) || identifiant_patient_inconnu(dossier)) &&
        (!nzchar(medicare) || identifiant_patient_inconnu(medicare))) {
      output$req_patient_message <- renderUI(
        div(class="info-box",
            "UNK indique un identifiant inconnu. Pour un nouveau patient, complétez le nom, le prénom et les autres renseignements, puis enregistrez la réquisition.")
      )
      return()
    }

    con <- ouvrir_db()
    on.exit(DBI::dbDisconnect(con), add=TRUE)

    # Lecture simple sans paramètre SQL : plus robuste avec PostgreSQL/Neon.
    patients_actifs <- tryCatch(
      db_query(con, "SELECT * FROM patients WHERE actif=1"),
      error=function(e) {
        output$req_patient_message <- renderUI(
          div(class="danger-box",
              paste0("Erreur de lecture des patients : ", conditionMessage(e)))
        )
        data.frame()
      }
    )
    if (nrow(patients_actifs)==0) return()

    cle <- function(x) {
      x <- as.character(x)
      x[is.na(x)] <- ""
      toupper(gsub("[^A-Za-z0-9]", "", x))
    }

    idx <- integer(0)
    if (nzchar(medicare) && !identifiant_patient_inconnu(medicare)) {
      idx <- which(cle(patients_actifs$medicare) == cle(medicare))
    } else if (nzchar(dossier) && !identifiant_patient_inconnu(dossier)) {
      idx <- which(cle(patients_actifs$numero_dossier) == cle(dossier))
    }

    p <- patients_actifs[idx,,drop=FALSE]

    if (nrow(p)==1) {
      patient_requisition(p)

      val <- function(x, def="") {
        if (length(x)==0 || is.na(x[1])) def else as.character(x[1])
      }

      updateTextInput(session,"req_numero_dossier",value=val(p$numero_dossier))
      updateTextInput(session,"req_medicare",value=val(p$medicare))
      updateTextInput(session,"req_nom",value=val(p$nom))
      updateTextInput(session,"req_prenom",value=val(p$prenom))

      dn <- val(p$date_naissance)
      if (nzchar(dn)) {
        dn2 <- suppressWarnings(as.Date(substr(dn,1,10)))
        if (!is.na(dn2))
          updateDateInput(session,"req_date_naissance",value=dn2)
      }

      updateSelectInput(session,"req_sexe",selected=val(p$sexe,"U"))
      updateTextInput(session,"req_adresse",value=val(p$adresse))
      updateTextInput(session,"req_ville",value=val(p$ville))
      updateTextInput(session,"req_province",value=val(p$province))
      updateTextInput(session,"req_code_postal",value=val(p$code_postal))
      updateTextInput(session,"req_pays",value=val(p$pays,"Canada"))

      output$req_patient_message <- renderUI(
        div(class="success-box",
            paste0("Patient trouvé : ", val(p$nom), ", ", val(p$prenom)))
      )
      session$sendCustomMessage("focusOrder", list())

    } else if (nrow(p)>1) {
      patient_requisition(NULL)
      output$req_patient_message <- renderUI(
        div(class="danger-box",
            "Plusieurs patients correspondent à cet identifiant.")
      )
    } else {
      patient_requisition(NULL)
      output$req_patient_message <- renderUI(
        div(class="warning-box",
            "Aucun patient actif trouvé avec ce numéro de dossier ou Medicare.")
      )
    }
  })

