    d <- charger_audit_patient(ref)
    journaliser("CONSULTATION_AUDIT_PATIENT",paste0("Traçabilité consultée : ",ref))
    if (nrow(d)==0) showNotification("Aucune trace trouvée.",type="warning")
  })

