  observeEvent(input$sauvegarder_modifications_user, {
    req(utilisateur_connecte()$perm_utilisateurs == 1)
    req(input$modifier_user_id)

    user_id <- as.integer(input$modifier_user_id)
    email <- tolower(norm_txt(input$edit_email))

    if (!email_valide(email)) {
      output$message_modifier_user <- renderUI(
        div(style = "color:red;", "Adresse courriel invalide.")
      )
      return()
    }

    if (input$edit_role == "ADMIN") {
      pr <- pp <- pq <- pat <- prec <- ph <- pu <- pa <- 1L
    } else {
      pr <- as.integer(input$edit_p_recherche)
      pp <- as.integer(input$edit_p_patients)
      pq <- as.integer(input$edit_p_requisition)
      pat <- as.integer(input$edit_p_ajout_tests)
      prec <- as.integer(input$edit_p_reception)
      ph <- as.integer(input$edit_p_historique)
      pu <- as.integer(input$edit_p_utilisateurs)
      pa <- as.integer(input$edit_p_analyses)
    }

    con <- ouvrir_db()
    on.exit(DBI::dbDisconnect(con), add = TRUE)

    doublon <- db_query(
      con,
      "
      SELECT id
      FROM utilisateurs
      WHERE
        (
          matricule = ?
          OR identifiant = ?
          OR LOWER(email) = LOWER(?)
        )
        AND id <> ?
      ",
      params = list(
        norm_txt(input$edit_matricule),
        norm_txt(input$edit_identifiant),
        email,
        user_id
      )
    )

    if (nrow(doublon) > 0) {
      output$message_modifier_user <- renderUI(
        div(style = "color:red;", "Matricule, identifiant ou courriel déjà utilisé.")
      )
      return()
    }

    db_execute(
      con,
      "
      UPDATE utilisateurs
      SET
        matricule = ?,
        initiales = ?,
        nom = ?,
        prenom = ?,
        email = ?,
        identifiant = ?,
        role = ?,
        actif = ?,
        perm_recherche_patient = ?,
        perm_patients = ?,
        perm_requisition = ?,
        perm_ajout_tests = ?,
        perm_reception = ?,
        perm_historique = ?,
        perm_utilisateurs = ?,
        perm_analyses = ?
      WHERE id = ?
      ",
      params = list(
        norm_txt(input$edit_matricule),
        norm_upper(input$edit_initiales),
        norm_upper(input$edit_nom),
        norm_txt(input$edit_prenom),
        email,
        norm_txt(input$edit_identifiant),
        input$edit_role,
        as.integer(input$edit_actif),
        pr, pp, pq, pat, prec, ph, pu, pa,
        user_id
      )
    )

    db_execute(con,
      "DELETE FROM utilisateur_departements WHERE utilisateur_id=?",
      params=list(user_id))
    deps <- suppressWarnings(as.integer(input$edit_user_departements))
    deps <- deps[!is.na(deps)]
    if (length(deps)>0) {
      for (dep_id in unique(deps)) {
        db_execute(con,
          "INSERT OR IGNORE INTO utilisateur_departements(utilisateur_id,departement_id,attribue_par) VALUES (?,?,?)",
          params=list(user_id,dep_id,utilisateur_connecte()$id))
      }
    }

    refresh_users(refresh_users() + 1L)

    output$message_modifier_user <- renderUI(
      div(class = "success-box", "Utilisateur et permissions mis à jour.")
    )
  })

  observeEvent(input$supprimer_utilisateur_historique,{
    req(utilisateur_connecte()$perm_utilisateurs==1,input$modifier_user_id)
    uid <- suppressWarnings(as.integer(input$modifier_user_id))
    if(is.na(uid)) return()
    if(uid==as.integer(utilisateur_connecte()$id)) {
      showNotification("Vous ne pouvez pas supprimer votre propre compte pendant votre session.",type="error")
      return()
    }
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    u <- db_query(con,"SELECT matricule,prenom,nom FROM utilisateurs WHERE id=?",params=list(uid))
    if(nrow(u)!=1) return()
    showModal(modalDialog(
      title="Suppression définitive de l'utilisateur",
      tags$p("Utilisateur : ",tags$strong(paste(u$matricule[1],u$prenom[1],u$nom[1]))),
      tags$p("Le compte et les enregistrements reliés par les clés étrangères seront supprimés définitivement."),
      tags$p(tags$strong("Cette action est irréversible.")),
      footer=tagList(modalButton("Annuler"),
                     actionButton("confirmer_suppression_utilisateur_historique",
                                  "Supprimer le compte et l'historique",class="btn-danger")),
      easyClose=FALSE
    ))
  },ignoreInit=TRUE)

  observeEvent(input$confirmer_suppression_utilisateur_historique,{
    req(utilisateur_connecte()$perm_utilisateurs==1,input$modifier_user_id)
    uid <- suppressWarnings(as.integer(input$modifier_user_id))
    if(is.na(uid) || uid==as.integer(utilisateur_connecte()$id)) { removeModal(); return() }
    con <- ouvrir_db(); on.exit(DBI::dbDisconnect(con),add=TRUE)
    tryCatch({
      db_begin_retry(con)
      edusillab_supprimer_cascade(con,"utilisateurs",uid)
      db_commit_retry(con)
      removeModal()
      output$formulaire_modifier_utilisateur <- renderUI(NULL)
      refresh_users(refresh_users()+1L)
      showNotification("Utilisateur et historique relié supprimés.",type="message")
    },error=function(e){
      try(DBI::dbRollback(con),silent=TRUE)
      removeModal()
      showNotification(paste("Suppression impossible :",conditionMessage(e)),type="error",duration=12)
    })
  },ignoreInit=TRUE)

